function evHash(text){
  var h=0, str=String(text||'');
  for(var i=0;i<str.length;i++) h=((h<<5)-h+str.charCodeAt(i))|0;
  return Math.abs(h);
}
function evGermanRoomLabel(room){
  return room && room.name ? evText(room.name) : 'dieser Raum';
}
function evGermanQuestion(room, original){
  /* V48S34_VALUES_BANK_HYGIENE:
     Old repeated Values question banks were removed from this base translator.
     Live Values entrance is handled by the dynamic gate system; protected room/game logic is untouched.
     Keep incoming question objects unchanged for Dua/Ibadet or any live system that still asks a real question. */
  try{
    if(original && original.q && original.opts) return original;
  }catch(e){}
  return original;
}

function evGermanCardText(original){
  /* V48S34_VALUES_CARD_HYGIENE:
     Old repeated Values card text banks were removed. Return translated/normal text only. */
  try{ return evText(original); }catch(e){}
  return original;
}

