function evSetRoomQuestionChrome(){
  var lang=(evValuesOn()&&evValuesLang)?evValuesLang():'';
  var de=lang==='de', en=lang==='en', fr=lang==='fr', ar=lang==='ar';
  var tag=document.querySelector('#ov-soru2 .sq2-tag');
  var next=document.getElementById('sq2-next');
  var skip=document.querySelector('.sq2-skip');
  if(tag) tag.textContent=en?'* DID YOU KNOW? *':(de?'* WUSSTEST DU? *':(fr?'* LE SAVAIS-TU ? *':(ar?'* هل تعلم؟ *':'* BILIYOR MUSUN? *')));
  if(next) next.textContent=en?'Enter room':(de?'Raum betreten':(fr?'Entrer dans la salle':(ar?'ادخل الغرفة':'Odaya Gir')));
  if(skip) skip.textContent=en?'I do not know, continue':(de?'Ich weiss es nicht, weiter':(fr?'Je ne sais pas, continuer':(ar?'لا أعرف، متابعة':'Bilmiyorum, gec')));
}
