    if(arLower.indexOf('doga')>=0 || arLower.indexOf('cevre')>=0 || arLower.indexOf('agac')>=0) return '\u0644\u0646\u062d\u0645 \u0627\u0644\u0637\u0628\u064a\u0639\u0629. \u0643\u0644 \u062e\u0637\u0648\u0629 \u0635\u063a\u064a\u0631\u0629 \u0645\u0647\u0645\u0629.';
    if(arLower.indexOf('nefes')>=0 || arLower.indexOf('sakin')>=0) return '\u062a\u0646\u0641\u0633 \u0628\u0647\u062f\u0648\u0621. \u0623\u0646\u062a \u0645\u0633\u062a\u0639\u062f.';
