    if(arLower.indexOf('sanat')>=0 || arLower.indexOf('renk')>=0 || arLower.indexOf('boya')>=0) return '\u062e\u064a\u0627\u0644\u0643 \u064a\u0644\u0645\u0639. \u0627\u0635\u0646\u0639 \u0634\u064a\u0626\u0627 \u062c\u0645\u064a\u0644\u0627!';
    if(arLower.indexOf('puzzle')>=0) return '\u062d\u0627\u0646 \u0648\u0642\u062a \u0627\u0644\u0623\u062d\u062c\u064a\u0629! \u0633\u064a\u0633\u0627\u0639\u062f\u0643 \u0627\u0644\u0635\u0628\u0631 \u0648\u0627\u0644\u0645\u0646\u0637\u0642.';
    if(arLower.indexOf('lazer')>=0 || arLower.indexOf('refleks')>=0) return '\u0631\u0643\u0632! \u0627\u0628\u0642 \u0647\u0627\u062f\u0626\u0627 \u0648\u062a\u0641\u0627\u0639\u0644 \u0628\u0633\u0631\u0639\u0629.';
    if(arLower.indexOf('dogru')>=0 || arLower.indexOf('bravo')>=0 || arLower.indexOf('harika')>=0 || arLower.indexOf('super')>=0) return '\u0623\u062d\u0633\u0646\u062a! \u0625\u062c\u0627\u0628\u0629 \u0635\u062d\u064a\u062d\u0629. \u062a\u0627\u0628\u0639!';
    if(arLower.indexOf('hata')>=0 || arLower.indexOf('neredeyse')>=0 || arLower.indexOf('balon')>=0) return '\u0627\u0642\u062a\u0631\u0628\u062a! \u0627\u0646\u0638\u0631 \u062c\u064a\u062f\u0627 \u0648\u062d\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.';
