function evV42ShowSakinlikRitual(type){
  try{
    var old=document.getElementById('v42-sakinlik-ritual');
    if(old) old.remove();
    var icon={breath:'🌬️',mirror:'🪞',lantern:'🏮',stone:'💎',box:'📦',silence:'🕯️'}[type]||'✨';
    var title=evV42SakinlikLabel(type)||evV42SakinlikLabel('ritual');
    var msg=evV42SakinlikMsg(type);
    var ov=document.createElement('div');
    ov.id='v42-sakinlik-ritual';
    ov.setAttribute('translate','no');
    ov.style.cssText='position:fixed;inset:0;z-index:100000;display:flex;align-items:center;justify-content:center;padding:22px;background:radial-gradient(circle at 50% 45%,rgba(134,231,255,.18),transparent 26%),rgba(1,8,18,.68);backdrop-filter:blur(6px);';
    ov.innerHTML='<div style="width:min(390px,92vw);border-radius:28px;padding:22px 18px;text-align:center;background:linear-gradient(145deg,rgba(255,255,255,.18),rgba(255,255,255,.06),rgba(80,180,210,.14));border:1.5px solid rgba(180,240,255,.28);box-shadow:0 28px 90px rgba(0,0,0,.48),0 0 48px rgba(134,231,255,.18);font-family:Fredoka One,system-ui,sans-serif;color:white;">'+
      '<div style="font-size:4rem;filter:drop-shadow(0 0 24px rgba(180,240,255,.65));">'+icon+'</div>'+
      '<div style="margin-top:6px;font-size:1.22rem;color:#dff8ff;">'+title+'</div>'+
      '<div style="margin:12px auto 0;max-width:320px;font-family:Nunito,system-ui,sans-serif;font-weight:900;font-size:.94rem;line-height:1.55;color:rgba(255,255,255,.90);">'+msg+'</div>'+
      '<button id="v42-sakinlik-close" style="margin-top:18px;width:100%;padding:13px 16px;border:none;border-radius:22px;background:linear-gradient(135deg,#86e7ff,#b7ffd3);color:#06222a;font-family:Fredoka One,sans-serif;font-size:1rem;cursor:pointer;">'+evV42SakinlikLabel('continue')+'</button>'+
      '</div>';
    document.body.appendChild(ov);
    var b=document.getElementById('v42-sakinlik-close');
    if(b) b.onclick=function(){var o=document.getElementById('v42-sakinlik-ritual'); if(o)o.remove();};
    if(typeof showOkiBubble==='function') setTimeout(function(){showOkiBubble(msg);},150);
  }catch(e){}
}
function evV42SakinlikZones(){
  return [
    {type:'breath',x:W*.50,y:H*.43,r:Math.min(W,H)*.13},
    {type:'mirror',x:W*.20,y:H*.58,r:Math.min(W,H)*.09},
    {type:'lantern',x:W*.78,y:H*.56,r:Math.min(W,H)*.10},
    {type:'stone',x:W*.34,y:H*.78,r:Math.min(W,H)*.08},
    {type:'box',x:W*.66,y:H*.78,r:Math.min(W,H)*.08},
    {type:'silence',x:W*.50,y:H*.86,r:Math.min(W,H)*.10}
  ];
}
function evV42TrySakinlikTap(x,y){
  try{
    if(!currentRoom || currentRoom.id!=='ibadet' || !(evValuesOn&&evValuesOn())) return false;
    var now=Date.now();
    if(now-_v42SakinlikLastTap<900) return true;
    var zones=evV42SakinlikZones();
    for(var i=0;i<zones.length;i++){
      var z=zones[i], dx=x-z.x, dy=y-z.y;
      if(Math.sqrt(dx*dx+dy*dy)<z.r){
        _v42SakinlikLastTap=now;
        evV42ShowSakinlikRitual(z.type);
        return true;
      }
    }
  }catch(e){}
  return false;
}



