      {x:.50,y:.44,r:.10,ico:'🎁',title:'Yardım Görevi',msg:'Bugün küçük bir yardım yap ve kimseye gösteriş yapma.'},
      {x:.70,y:.52,r:.10,ico:'🏅',title:'İyilik Rozeti',msg:'İyilik büyüktür; küçük bir davranış bile dünyayı güzelleştirir.'}
