    mountain(H*.58, [[.10,.34,.25],[.32,.26,.52],[.58,.38,.73],[.78,.28,.98]], 'rgba(12,28,44,.72)');
    mountain(H*.66, [[.03,.48,.22],[.24,.40,.45],[.48,.45,.68],[.70,.36,.98]], 'rgba(20,45,58,.72)');

