    ctx.lineTo(W*.54,H*.56);
    ctx.bezierCurveTo(W*.46,H*.68,W*.60,H*.78,W*.67,H);
    ctx.lineTo(W*.34,H);
    ctx.bezierCurveTo(W*.42,H*.80,W*.40,H*.69,W*.49,H*.56);
    ctx.closePath();
    ctx.fill();

    // Yolun kenar ışıkları / küçük adımlar
    for(var sp=0;sp<12;sp++){
      var k=sp/11;
      var y=H*(.60+k*.36);
      var curve=Math.sin(k*Math.PI*2+t*.15)*W*.020;
      var center=W*(.50+.10*k)+curve;
      var gap=W*(.040+.115*k);
      var al=.16+.20*Math.abs(Math.sin(t*1.4+sp));
      ctx.fillStyle='rgba(255,218,120,'+al+')';
      ctx.beginPath(); ctx.arc(center-gap,y,2.2+sp*.10,0,Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(center+gap,y,2.2+sp*.10,0,Math.PI*2); ctx.fill();

      // basamak taşları
      ctx.fillStyle='rgba(235,220,180,.18)';
      ctx.beginPath();
      ctx.ellipse(center,y+H*.010,W*(.020+.006*k),H*(.006+.004*k),Math.sin(sp)*.25,0,Math.PI*2);
      ctx.fill();
    }

    // Sağda hedef bayrağı
    var flagX=W*.66, flagY=H*.49;
    ctx.strokeStyle='rgba(225,210,160,.80)';
    ctx.lineWidth=4;
    ctx.lineCap='round';
    ctx.beginPath(); ctx.moveTo(flagX,flagY+H*.18); ctx.lineTo(flagX,flagY); ctx.stroke();

    var flagWave=Math.sin(t*3)*W*.010;
    ctx.fillStyle='rgba(255,90,90,.88)';
    ctx.beginPath();
    ctx.moveTo(flagX,flagY);
    ctx.quadraticCurveTo(flagX+W*.070,flagY-H*.020+flagWave,flagX+W*.135,flagY+H*.010);
    ctx.quadraticCurveTo(flagX+W*.072,flagY+H*.040-flagWave,flagX,flagY+H*.025);
    ctx.closePath(); ctx.fill();

    ctx.fillStyle='rgba(255,235,140,.95)';
    ctx.font='bold '+Math.round(Math.min(W,H)*.023)+'px Fredoka One';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('⭐',flagX+W*.063,flagY+H*.010);

    // Sol tarafta kamp feneri
    var lanX=W*.24, lanY=H*.68;
    ctx.fillStyle='rgba(45,32,26,.90)';
    ctx.beginPath(); ctx.roundRect(lanX-W*.024,lanY,W*.048,H*.10,7); ctx.fill();
    ctx.strokeStyle='rgba(255,218,120,.55)';
    ctx.lineWidth=2;
    ctx.beginPath(); ctx.arc(lanX,lanY-H*.002,W*.022,Math.PI,Math.PI*2); ctx.stroke();
    ctx.fillStyle='rgba(255,210,100,.78)';
    ctx.beginPath(); ctx.roundRect(lanX-W*.014,lanY+H*.025,W*.028,H*.038,5); ctx.fill();

    var glowLan=ctx.createRadialGradient(lanX,lanY+H*.045,0,lanX,lanY+H*.045,H*.18);
    glowLan.addColorStop(0,'rgba(255,205,90,.25)');
    glowLan.addColorStop(.45,'rgba(255,175,80,.10)');
    glowLan.addColorStop(1,'transparent');
    ctx.fillStyle=glowLan; ctx.fillRect(lanX-W*.20,lanY-H*.12,W*.40,H*.35);

    // Tırmanma taşları / rozet gibi küçük hedefler
    var rocks=[
      [.34,.67,.038],[.43,.62,.030],[.53,.65,.034],[.60,.71,.040],
      [.38,.79,.045],[.52,.82,.050],[.66,.87,.045],[.46,.91,.052]
    ];
    rocks.forEach(function(r,i){
      var x=W*r[0], y=H*r[1], s=Math.min(W,H)*r[2];
      var rg=ctx.createLinearGradient(x-s,y-s,x+s,y+s);
      rg.addColorStop(0,'rgba(150,130,105,.86)');
      rg.addColorStop(1,'rgba(70,58,52,.88)');
      ctx.fillStyle=rg;
      ctx.beginPath(); ctx.ellipse(x,y,s*1.25,s*.62,Math.sin(i)*.4,0,Math.PI*2); ctx.fill();
      ctx.fillStyle='rgba(255,255,255,.14)';
      ctx.beginPath(); ctx.ellipse(x-s*.25,y-s*.12,s*.32,s*.12,Math.sin(i)*.4,0,Math.PI*2); ctx.fill();
    });

    // Küçük sırt çantası
    var bagX=W*.31, bagY=H*.78;
    ctx.fillStyle='rgba(50,35,30,.28)';
    ctx.beginPath(); ctx.ellipse(bagX,bagY+H*.040,W*.060,H*.018,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='rgba(76,132,165,.82)';
    ctx.beginPath(); ctx.roundRect(bagX-W*.040,bagY-H*.020,W*.080,H*.070,12); ctx.fill();
    ctx.strokeStyle='rgba(255,255,255,.18)';
    ctx.lineWidth=2;
    ctx.beginPath(); ctx.arc(bagX,bagY-H*.012,W*.030,Math.PI,Math.PI*2); ctx.stroke();
    ctx.fillStyle='rgba(255,210,110,.80)';
    ctx.beginPath(); ctx.roundRect(bagX-W*.022,bagY+H*.010,W*.044,H*.020,5); ctx.fill();

    // Motivasyon yıldızları / emek parçacıkları
    for(var pa=0;pa<26;pa++){
      var px=W*(.12+(pa*0.053)%0.78)+Math.sin(t*.8+pa)*W*.014;
      var py=H*(.40+(pa%7)*.065)+Math.cos(t*.6+pa)*H*.009;
      var al=.08+.18*Math.abs(Math.sin(t*1.5+pa));
      ctx.fillStyle=pa%3===0?'rgba(255,220,120,'+al+')':(pa%3===1?'rgba(165,210,255,'+al+')':'rgba(255,150,130,'+al+')');
      ctx.beginPath(); ctx.arc(px,py,1.4+(pa%3)*.35,0,Math.PI*2); ctx.fill();
    }

    // Küçük işaret tabelası
    var signX=W*.78, signY=H*.73;
    ctx.strokeStyle='rgba(120,75,42,.82)';
    ctx.lineWidth=4;
    ctx.beginPath(); ctx.moveTo(signX,signY); ctx.lineTo(signX,signY+H*.12); ctx.stroke();
    ctx.fillStyle='rgba(155,95,48,.86)';
    ctx.beginPath(); ctx.roundRect(signX-W*.090,signY-H*.034,W*.180,H*.055,8); ctx.fill();
    ctx.strokeStyle='rgba(255,222,150,.22)';
    ctx.lineWidth=1;
    ctx.strokeRect(signX-W*.090,signY-H*.034,W*.180,H*.055);
    ctx.fillStyle='rgba(255,235,180,.90)';
    ctx.font='bold '+Math.round(Math.min(W,H)*.018)+'px Fredoka One';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    var stepTxt=(evValuesOn()&&evValuesLang()==='en')?'ONE STEP':(evValuesOn()&&evValuesLang()==='de')?'EIN SCHRITT':(evValuesOn()&&evValuesLang()==='fr')?'UN PAS':(evValuesOn()&&evValuesLang()==='ar')?'خطوة':'BİR ADIM';
    ctx.fillText(stepTxt,signX,signY-H*.006);

    // Başlık levhası
    ctx.save();
    ctx.translate(W*.50,H*.095);
    ctx.fillStyle='rgba(12,20,36,.68)';
    ctx.strokeStyle='rgba(255,220,150,.32)';
    ctx.lineWidth=2;
    ctx.beginPath(); ctx.roundRect(-W*.20,-H*.033,W*.40,H*.066,16); ctx.fill(); ctx.stroke();
    ctx.fillStyle='rgba(255,235,180,.94)';
    ctx.font='bold '+Math.round(Math.min(W,H)*.030)+'px Fredoka One';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    var label=(evValuesOn()&&evValuesLang()==='en')?'EFFORT ROOM':(evValuesOn()&&evValuesLang()==='de')?'FLEISS-RAUM':(evValuesOn()&&evValuesLang()==='fr')?'SALLE DE L EFFORT':(evValuesOn()&&evValuesLang()==='ar')?'غرفة الجهد':'ÇABA ODASI';
    ctx.fillText(label,0,0);
    ctx.restore();

    // Alt kısa mesaj
    ctx.save();
    ctx.fillStyle='rgba(255,235,205,.78)';
    ctx.font=Math.round(Math.min(W,H)*.021)+'px Fredoka One';
    ctx.textAlign='center';
    var sub=(evValuesOn()&&evValuesLang()==='en')?'Every small step brings you closer.':(evValuesOn()&&evValuesLang()==='de')?'Jeder kleine Schritt bringt dich näher.':(evValuesOn()&&evValuesLang()==='fr')?'Chaque petit pas te rapproche.':(evValuesOn()&&evValuesLang()==='ar')?'كل خطوة صغيرة تقرّبك':'Her küçük adım zirveye yaklaştırır.';
    ctx.fillText(sub,W*.5,H*.93);
