    var mg=ctx.createLinearGradient(machX-machW*.5,machY-machH*.5,machX+machW*.5,machY+machH*.5);
    mg.addColorStop(0,'#2b1a14'); mg.addColorStop(.45,'#a35a26'); mg.addColorStop(1,'#20100d');
    ctx.fillStyle=mg; ctx.beginPath(); ctx.roundRect(machX-machW*.5,machY-machH*.5,machW,machH,18); ctx.fill();
    ctx.strokeStyle='rgba(255,220,100,.35)'; ctx.lineWidth=2; ctx.beginPath(); ctx.roundRect(machX-machW*.5,machY-machH*.5,machW,machH,18); ctx.stroke();

