    ctx.fillStyle='rgba(255,220,110,.90)'; ctx.font='bold '+Math.round(Math.min(W,H)*.030)+'px Fredoka One'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('WORT',machX,machY-H*.006);

