    ctx.beginPath(); ctx.moveTo(wx,wy+wh*.52); ctx.lineTo(wx+ww,wy+wh*.52); ctx.stroke();
    var sky=ctx.createLinearGradient(wx,wy,wx,wy+wh);
    sky.addColorStop(0,'rgba(165,230,255,.40)');
    sky.addColorStop(1,'rgba(210,255,225,.20)');
    ctx.fillStyle=sky; ctx.fillRect(wx+4,wy+4,ww-8,wh-8);

    // Işık huzmesi
    ctx.save();
    ctx.globalAlpha=.12;
    var beam=ctx.createLinearGradient(wx+ww*.75,wy+wh,W*.54,H);
    beam.addColorStop(0,'rgba(210,255,230,.55)');
    beam.addColorStop(1,'rgba(210,255,230,0)');
    ctx.fillStyle=beam;
    ctx.beginPath();
