    ctx.beginPath(); ctx.roundRect(boardX-boardW*.5+6,boardY-boardH*.5+7,boardW,boardH,14); ctx.fill();
    var board=ctx.createLinearGradient(boardX-boardW*.5,boardY-boardH*.5,boardX+boardW*.5,boardY+boardH*.5);
    board.addColorStop(0,'rgba(225,255,245,.18)');
    board.addColorStop(.55,'rgba(120,230,210,.14)');
    board.addColorStop(1,'rgba(70,180,210,.12)');
    ctx.fillStyle=board;
    ctx.beginPath(); ctx.roundRect(boardX-boardW*.5,boardY-boardH*.5,boardW,boardH,14); ctx.fill();
    ctx.strokeStyle='rgba(215,255,240,.26)';
    ctx.lineWidth=2; ctx.stroke();

