    ctx.lineTo(boardW*.38,0);
    ctx.stroke();
    ctx.fillStyle='rgba(255,110,140,.75)';
    ctx.font=Math.round(boardH*.32)+'px serif';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('💚',0,-boardH*.32);
