    miniPoster(W*.39,H*.30,'🏃','HAREKET');

    // 2.5D temiz zemin
    var floor=ctx.createLinearGradient(0,floorY-H*.06,0,H);
    floor.addColorStop(0,'rgba(100,175,165,.58)');
    floor.addColorStop(.55,'rgba(45,105,98,.82)');
    floor.addColorStop(1,'rgba(10,36,32,.98)');
    ctx.fillStyle=floor;
    ctx.beginPath();
    ctx.moveTo(W*.04,floorY);
