    for(var i=0;i<9;i++){
      var xx=W*(.10+i*.10);
      ctx.beginPath(); ctx.moveTo(xx,H); ctx.lineTo(W*.50,H*.58); ctx.stroke();
    }
    for(var j=0;j<7;j++){
      var yy=floorY+j*H*.038;
      ctx.beginPath(); ctx.moveTo(W*.08,yy); ctx.lineTo(W*.92,yy); ctx.stroke();
    }

    // Ortada yuvarlak kontrol platformu / canlılık masası
    var platX=W*.50, platY=H*.68, platW=W*.46, platH=H*.11;
    ctx.fillStyle='rgba(0,0,0,.20)';
    ctx.beginPath(); ctx.ellipse(platX,platY+platH*.62,platW*.60,platH*.24,0,0,Math.PI*2); ctx.fill();

    var plat=ctx.createRadialGradient(platX-platW*.15,platY-platH*.20,platH*.08,platX,platY,platW*.50);
    plat.addColorStop(0,'rgba(235,255,250,.86)');
    plat.addColorStop(.50,'rgba(130,225,205,.72)');
    plat.addColorStop(1,'rgba(36,110,105,.78)');
    ctx.fillStyle=plat;
    ctx.beginPath(); ctx.ellipse(platX,platY,platW*.52,platH*.56,0,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle='rgba(235,255,245,.32)';
    ctx.lineWidth=2; ctx.stroke();

    // Platform üstü canlık küresi / kalp
    var orbX=platX, orbY=platY-H*.08, orbR=Math.min(W,H)*.065;
    var orb=ctx.createRadialGradient(orbX-orbR*.28,orbY-orbR*.35,orbR*.08,orbX,orbY,orbR);
    orb.addColorStop(0,'rgba(255,255,255,.90)');
    orb.addColorStop(.28,'rgba(180,255,220,.38)');
    orb.addColorStop(.68,'rgba(80,215,255,.18)');
    orb.addColorStop(1,'rgba(255,255,255,.06)');
    ctx.fillStyle=orb;
    ctx.beginPath(); ctx.arc(orbX,orbY,orbR,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle='rgba(210,255,240,.42)';
    ctx.beginPath(); ctx.arc(orbX,orbY,orbR,0,Math.PI*2); ctx.stroke();
    ctx.font=Math.round(orbR*.70)+'px serif';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('💚',orbX,orbY+orbR*.05);

    // Su damlası istasyonu
    var dropX=W*.28, dropY=H*.61;
    ctx.fillStyle='rgba(0,0,0,.18)';
    ctx.beginPath(); ctx.ellipse(dropX,dropY+H*.105,W*.090,H*.020,0,0,Math.PI*2); ctx.fill();
    var bottle=ctx.createLinearGradient(dropX-W*.035,dropY-H*.06,dropX+W*.035,dropY+H*.08);
    bottle.addColorStop(0,'rgba(210,250,255,.82)');
    bottle.addColorStop(.55,'rgba(80,190,230,.38)');
    bottle.addColorStop(1,'rgba(35,120,160,.52)');
