    var fruits=[['🍎',-.055,-.005],['🍌',-.018,-.022],['🥕',.022,-.008],['🍊',.055,-.015],['🥦',.005,-.045]];
    fruits.forEach(function(f){
      ctx.font=Math.round(H*.036)+'px serif';
      ctx.fillText(f[0],fruitX+W*f[1],fruitY+H*f[2]);
    });

    // Uyku / dinlenme köşesi
    var bedX=W*.18, bedY=H*.78, bedW=W*.22, bedH=H*.075;
