    ctx.beginPath(); ctx.ellipse(bedX,bedY+bedH*.40,bedW*.56,bedH*.20,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='rgba(125,170,210,.58)';
    ctx.beginPath(); ctx.roundRect(bedX-bedW*.5,bedY-bedH*.5,bedW,bedH,12); ctx.fill();
    ctx.fillStyle='rgba(240,255,250,.72)';
    ctx.beginPath(); ctx.roundRect(bedX-bedW*.42,bedY-bedH*.38,bedW*.30,bedH*.36,8); ctx.fill();
    ctx.fillStyle='rgba(185,230,255,.46)';
    ctx.beginPath(); ctx.roundRect(bedX-bedW*.10,bedY-bedH*.34,bedW*.48,bedH*.30,8); ctx.fill();
