    ctx.fillStyle=floor;
    ctx.beginPath();
    ctx.moveTo(W*.04,floorY);
    ctx.lineTo(W*.50,H*.56);
    ctx.lineTo(W*.96,floorY);
    ctx.lineTo(W*.82,H);
    ctx.lineTo(W*.18,H);
    ctx.closePath(); ctx.fill();

