    ctx.beginPath(); ctx.ellipse(bookX,bookY+bookH*.52,bookW*.56,bookH*.18,0,0,Math.PI*2); ctx.fill();

    ctx.fillStyle='rgba(255,248,225,.94)';
    ctx.beginPath();
    ctx.moveTo(bookX,bookY-H*.035);
    ctx.quadraticCurveTo(bookX-bookW*.36,bookY-bookH*.22,bookX-bookW*.54,bookY+bookH*.36);
    ctx.quadraticCurveTo(bookX-bookW*.25,bookY+bookH*.58,bookX,bookY+bookH*.28);
    ctx.closePath(); ctx.fill();

