  // Oki ipucu — çocuk cevap balonunu arasın
  setTimeout(function(){
    showOkiBubble((evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='en')?'❓ Find the answer balloon and pop it! 🎈':((evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='fr')?'❓ Trouve le ballon-reponse et eclate-le ! 🎈':((evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='ar')?'❓ \u0627\u0639\u062b\u0631 \u0639\u0644\u0649 \u0628\u0627\u0644\u0648\u0646 \u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0648\u0641\u062c\u0631\u0647! 🎈':'❓ Cevap balonunu bul ve patlat! 🎈')));
  }, 800);
