    if(mailFr) mailFr.textContent='Envoyer par e-mail';
    var closesFr=document.querySelectorAll('#qr-ov button[onclick*="qr-ov"]');
    closesFr.forEach(function(b){
      if(b.getAttribute('data-qr-close-icon')==='1'){ b.textContent='×'; b.setAttribute('aria-label','Fermer'); b.setAttribute('title','Fermer'); }
      else { b.textContent='Fermer'; }
    });
