      rsde('🌍','Gesamte Woerter',words+' Woerter')+
      rsde('\uD83D\uDD25','Tages-Serie',streak+' Tage')+
      rsde('🏠','Entdeckte Raeume',rooms+' / '+ROOMS.length+' Raeume')+
      rsde('💪','Beste Aktivitaet',bestName)+
      '<div style="margin-top:10px;padding:12px 14px;border-radius:12px;background:rgba(120,190,170,.12);border:1px solid rgba(120,190,170,.28);font-size:.8rem;line-height:1.5;color:rgba(255,255,255,.82);font-weight:700;">Values-Modus: neutral, international und ohne religioese Inhalte.</div>';
    document.getElementById('rov').classList.add('show');
