function showChamp(){
  var fake=[{n:'Ahmet Y.',s:3420},{n:'Zeynep K.',s:2980},{n:'Mehmet A.',s:2650},{n:'Elif S.',s:2100},{n:'Yusuf T.',s:1850},{n:'Fatma D.',s:1620},{n:'Omar R.',s:1400}];
  var all=fake.concat([{n:playerName+' (Sen!)',s:totalScore,me:true}]);
  all.sort(function(a,b){return b.s-a.s;});
  var medals=['🥇','🥈','🥉'];
  document.getElementById('c-list').innerHTML=all.map(function(p,i){
    return '<div style="display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:14px;margin-bottom:8px;background:'+(p.me?'rgba(255,200,0,.12)':'rgba(255,255,255,.05)')+'">'
      +'<div style="font-family:Fredoka One;font-size:1.3rem;color:#FFD700;min-width:32px">'+(medals[i]||(i+1)+'.')+'</div>'
      +'<div style="font-family:Nunito;font-size:.9rem;font-weight:800;color:rgba(255,255,255,.88);flex:1">'+(p.me?'⭐ ':'')+p.n+'</div>'
      +'<div style="font-family:Fredoka One;font-size:1.05rem;color:#F4C430">'+p.s+'⭐</div>'
      +'</div>';
  }).join('');
  document.getElementById('cov').classList.add('show');
}

