// 🌍 VALUES MODE SİSTEMİ
// İslami içerik → Evrensel değerler
// ════════════════════════════════════════════════
var _valuesMode = false;

// Oda dönüşüm haritası: islami → evrensel
var VALUES_ROOMS = {
  ibadet:   { name:'Sakinlik Evi', ico:'🕯️', desc:'Nefes, duygu, iyi dilek' },
  arapca:   { name:'Kaligrafi',   ico:'✍️', desc:'Sanat, yazı, yaratıcılık' },
  para:     { name:'Paylaşım',    ico:'🤝', desc:'Yardımlaşma, değer bilme' },
  sifa:     { name:'Sağlık',      ico:'🌿', desc:'Doğal sağlık, bitkiler' },
  dua:      { name:'Dilekler',    ico:'⭐', desc:'Umutlar, hayaller' },
};

// Ana ekran başlığı
var VALUES_TITLE = { islam: 'Keşif Gezegeni', values: 'Wonder House' };

function _toggleValuesMode(){
  _valuesMode = !_valuesMode;
  _applyValuesMode();
  
  // Toast
  var t = document.createElement('div');
  t.className = '_gf';
  t.style.cssText = 'position:fixed;bottom:80px;left:50%;transform:translateX(-50%);z-index:9998;border-radius:20px;padding:8px 18px;font-family:Fredoka One;font-size:.85rem;white-space:nowrap;pointer-events:none;box-shadow:0 4px 20px rgba(0,0,0,.3);';
  if(_valuesMode){
    t.style.background = 'linear-gradient(135deg,#1a6a3a,#2a9a5a)';
    t.style.color = '#fff';
    t.style.border = '1px solid rgba(100,255,150,.3)';
    t.textContent = '🌍 Values Mode aktif';
  } else {
    t.style.background = 'linear-gradient(135deg,#1a1060,#3a2090)';
    t.style.color = '#FFD700';
    t.style.border = '1px solid rgba(255,215,0,.3)';
    t.textContent = '🕌 İslam Modu aktif';
  }
  document.body.appendChild(t);
  setTimeout(function(){ t.style.opacity='0'; t.style.transition='opacity .5s'; setTimeout(function(){ if(t.parentNode) t.remove(); },500); }, 2500);
  
  // Kaydet
  localStorage.setItem('eduverse_values_mode', _valuesMode ? '1' : '0');
}

function _applyValuesMode(){
  var btn = document.getElementById('values-toggle-btn');
  var title = document.getElementById('hm-title');
  
  if(_valuesMode){
    // Düğme aktif görünümü
    if(btn){
      btn.style.background = 'rgba(50,200,100,.25)';
      btn.style.borderColor = 'rgba(100,255,150,.5)';
      btn.style.color = '#88FF88';
    }
    // Başlık değişimi
    if(title) title.textContent = VALUES_TITLE.values;
    // Odaları dönüştür
    ROOMS.forEach(function(r){
      if(VALUES_ROOMS[r.id]){
        r._origName = r._origName || r.name;
        r._origIco  = r._origIco  || r.ico;
        r.name = VALUES_ROOMS[r.id].name;
        r.ico  = VALUES_ROOMS[r.id].ico;
      }
    });
  } else {
    // Düğme pasif görünümü
    if(btn){
      btn.style.background = 'rgba(255,255,255,.08)';
      btn.style.borderColor = 'rgba(255,255,255,.15)';
      btn.style.color = 'rgba(255,255,255,.3)';
    }
    // Başlık eski haline dön
    if(title) title.textContent = (typeof evDiscoveryPlanetTitle==='function' && window.playerName) ? evDiscoveryPlanetTitle(window.playerName) : VALUES_TITLE.islam;
    // Odaları geri al
    ROOMS.forEach(function(r){
      if(r._origName){ r.name = r._origName; delete r._origName; }
      if(r._origIco) { r.ico  = r._origIco;  delete r._origIco;  }
    });
  }
  
  // Grid'i yenile
  if(typeof buildGrid === 'function') buildGrid();
}

// Sayfa açılışında kayıtlı modu yükle
window.addEventListener('load', function(){
  var saved = localStorage.getItem('eduverse_values_mode');
  if(saved === '1'){
    _valuesMode = true;
    setTimeout(_applyValuesMode, 500);
  }
});


