var _eduTapCount = 0;
var _eduTapTimer = null;
function _eduTap(){
  _eduTapCount++;
  clearTimeout(_eduTapTimer);
  if(_eduTapCount >= 7){
    _eduTapCount = 0;
    // Gizli odanın kilidini geçici olarak aç
    var sr = ROOMS.find(function(r){ return r.id === 'gizli'; });
    if(sr){
      var origUnlock = sr.unlock;
      sr.unlock = 0;
      buildGrid();
      // 1 saniyelik görsel ipucu
      var logo = document.getElementById('edu-logo-tap');
      if(logo){
        logo.style.textShadow = '0 0 16px #FFD700, 0 0 32px #FFD700';
        logo.style.transition = 'text-shadow .3s';
        setTimeout(function(){
          logo.style.textShadow = '';
        }, 1500);
      }
      // Küçük bir uyarı toast
      var t = document.createElement('div');
      t.className = '_gf';
      t.style.cssText = 'position:fixed;bottom:80px;left:50%;transform:translateX(-50%);z-index:9998;background:linear-gradient(135deg,#1a0060,#4a0080);border:1px solid rgba(200,100,255,.4);border-radius:20px;padding:8px 18px;font-family:Fredoka One;font-size:.8rem;color:#DDA0FF;box-shadow:0 4px 20px rgba(100,0,200,.4);white-space:nowrap;pointer-events:none;';
      t.textContent = '🔮 Gizli Oda aktif!';
      document.body.appendChild(t);
      setTimeout(function(){ t.style.opacity='0'; t.style.transition='opacity .5s'; setTimeout(function(){ if(t.parentNode) t.remove(); }, 500); }, 2000);
    }
    // Ebeveyn raporunu aç
    setTimeout(function(){ showReport(); }, 500);
    return;
  }
  // 800ms içinde tıklanmazsa sıfırla
  _eduTapTimer = setTimeout(function(){ _eduTapCount = 0; }, 800);
}

function goHome(){
  evV47KMERemoveNav&&evV47KMERemoveNav();
  if(currentRoom){
    // Track rooms visited today for parent report
    var today=new Date().toDateString();
    var rv=JSON.parse(localStorage.getItem('dei_visited')||'{}');
    if(!rv[today]) rv[today]=[];
    if(rv[today].indexOf(currentRoom.id)<0) rv[today].push(currentRoom.id);
    localStorage.setItem('dei_visited',JSON.stringify(rv));
  }
  if(currentRoom&&roomScore>(roomBests[currentRoom.id]||0)){
    roomBests[currentRoom.id]=roomScore;
    savePlayerData();
  }
  gameActive=false;
  window._okBaliklar = null; // okyanus balıklarını sıfırla
  // Tema butonunu gizle ve sıfırla
  var _rtb2 = document.getElementById('_room-theme-btn');
  if(_rtb2){ _rtb2.style.display='none'; }
  _resetRoomTheme();
  stopCoinRain(); // Para yağmurunu durdur
  evV48S35MissionCleanup();
  // Ekrandaki tüm DOM balonları / float elementlerini temizle
  // Oyun sırasında eklenen TÜM geçici DOM elementlerini temizle
  document.querySelectorAll('._gf, .fm').forEach(function(el){ el.remove(); });
  var _ov=document.getElementById('hazine-done-ov'); if(_ov) _ov.style.display='none';
  var _ci=document.getElementById('coin-rain-counter'); if(_ci) _ci.remove();
  // Smooth fade out
  var gs2=document.getElementById('gs');
  if(gs2){
    gs2.style.transition='opacity .25s ease';
    gs2.style.opacity='0';
    setTimeout(function(){
      gs2.style.display='none';
      gs2.style.opacity='1';
      gs2.style.transition='';
      currentRoom=null; objs=[]; parts=[];
      // Extra safety: clear again after any delayed burst() calls fire
      setTimeout(function(){ parts=[]; objs=[]; },600);
      // Nuclear cleanup: catch any element that snuck through all guards
      setTimeout(function(){
        if(gameActive) return; // user re-entered a room, don't clean
        document.querySelectorAll('._gf, .fm').forEach(function(e){ e.remove(); });
      }, 800);
      var hm2=document.getElementById('hm');
      if(hm2){ hm2.style.opacity='0'; hm2.style.display='flex'; hm2.style.transition='opacity .25s ease'; setTimeout(function(){hm2.style.opacity='1'; setTimeout(function(){hm2.style.transition='';},260);},20); }
    },260);
  } else {
    currentRoom=null; objs=[]; parts=[];
    document.getElementById('hm').style.display='flex';
  }
  document.getElementById('hsc').textContent=totalScore;
  loadSavedChar(); updateLvl(); buildGrid(); setTimeout(initOki,100); setCharState('idle');
  updateDailyStrip(); setTimeout(okiGreet,1200); okiStartReminders(); setTimeout(initHmSpace,200);
  // Müzik player ana ekranda da her zaman görünür
  setTimeout(function(){
    var m=document.getElementById('ada-muzik');
    if(m) m.style.display='flex';
  },300);
}

// ── ENTRY ──

// İsme özel kaydetme
function _hzKey(){ return 'hazine_daily_'+(playerName||'x').toLowerCase().replace(/[^a-z0-9]/g,'_'); }
function _fedKey(){ return 'melek_fed_'+(playerName||'x').toLowerCase().replace(/[^a-z0-9]/g,'_'); }
function _playerKey(){
  var nm=(playerName||'kahraman').toLowerCase().replace(/[^a-z0-9]/g,'_');
  return 'dei_player_'+nm;
}

// V48S75: oyuncu bazlı kayıt izolasyonu + skor anahtarı senkronu.
// Eski prefixsiz kayıtlar silinmez; aktif oyuncuya güvenli kopyalanır.
function _eduPlayerId(){
  var nm='';
  try{ nm=playerName||localStorage.getItem('eduverse_player_name')||localStorage.getItem('playerName')||'kahraman'; }catch(e){ nm=playerName||'kahraman'; }
  nm=String(nm||'kahraman').toLowerCase().replace(/[^a-z0-9]/g,'_');
  return nm||'kahraman';
}
function _eduScopedKey(k){ return k+'__'+_eduPlayerId(); }
function _eduGetRaw(k,d){ try{ var v=localStorage.getItem(k); return v===null||v===undefined?d:v; }catch(e){ return d; } }
function _eduSetRaw(k,v){ try{ localStorage.setItem(k,String(v)); }catch(e){} }
function _eduGetScoped(k,d){
  var sk=_eduScopedKey(k), sv=_eduGetRaw(sk,null);
  if(sv!==null&&sv!==undefined) return sv;
  var lv=_eduGetRaw(k,null);
  if(lv!==null&&lv!==undefined){ try{ localStorage.setItem(sk,lv); }catch(e){} return lv; }
  return d;
}
function _eduSetScoped(k,v){
  try{ localStorage.setItem(_eduScopedKey(k),String(v)); }catch(e){}
  try{ localStorage.setItem(k,String(v)); }catch(e){}
}
function _eduJsonGetScoped(k,d){
  var v=_eduGetScoped(k,null);
  if(v===null||v===undefined||v==='') return d;
  try{ return JSON.parse(v); }catch(e){ return d; }
}
function _eduJsonSetScoped(k,v){
  var txt=''; try{ txt=JSON.stringify(v); }catch(e){ txt=JSON.stringify([]); }
  _eduSetScoped(k,txt);
}
function _eduScoreLegacyMax(){
  var a=parseInt(_eduGetRaw('edu_totalScore','0'),10)||0;
  var b=parseInt(_eduGetRaw('eduverse_totalScore','0'),10)||0;
  return Math.max(a,b);
}
function _eduScoreSync(v){
  var n=parseInt(v,10); if(isNaN(n)) n=0;
  try{ localStorage.setItem('edu_totalScore',String(n)); }catch(e){}
  try{ localStorage.setItem('eduverse_totalScore',String(n)); }catch(e){}
  try{ localStorage.setItem(_eduScopedKey('edu_totalScore'),String(n)); }catch(e){}
  try{ localStorage.setItem(_eduScopedKey('eduverse_totalScore'),String(n)); }catch(e){}
}
function savePlayerData(){
  var key=_playerKey();
  var _char=(function(){try{return _eduGetScoped('oki_char','erkek')||'erkek';}catch(e){return 'erkek';}}());
  var _ward=(function(){try{return _eduJsonGetScoped('oki_wardrobe',{});}catch(e){return {};}}());
  var _streak=(function(){try{return _eduGetScoped('dei_streak','0')||'0';}catch(e){return '0';}}());
  var _last=(function(){try{return _eduGetScoped('dei_last','')||'';}catch(e){return '';}}());
  _eduScoreSync(totalScore);
  localStorage.setItem(key, JSON.stringify({
    score:   totalScore,
    secret:  secretScore,
    bests:   roomBests,
    words:   learnedWords,
    seen:    seenCount,
    owned:   _shopRoomOwned,
    wearing: _shopRoomWearing,
    char:    _char,
    wardrobe:_ward,
    streak:  _streak,
    last:    _last
  }));
}

// EV_DISCOVERY_NAME: Ana İslami alan kapı başlığı artık 'Dua Evi' değil, oyuncuya özel Keşif Gezegeni.
function evTrPossessiveSuffix(name){
  var n=String(name||'').toLowerCase();
  var vowels='aıoueiöü';
  var last='', lastChar='';
  for(var c=n.length-1;c>=0;c--){ if(/[a-zçğıöşü]/i.test(n.charAt(c))){ lastChar=n.charAt(c); break; } }
  for(var i=n.length-1;i>=0;i--){ if(vowels.indexOf(n.charAt(i))>=0){ last=n.charAt(i); break; } }
  var base=(last==='a' || last==='ı') ? 'ın' : ((last==='o' || last==='u') ? 'un' : ((last==='ö' || last==='ü') ? 'ün' : 'in'));
  return (vowels.indexOf(lastChar)>=0 ? 'n' : '') + base;
}
function evDiscoveryPlanetTitle(name){
  var n=String(name||'Kahraman').trim()||'Kahraman';
  return n + "'" + evTrPossessiveSuffix(n) + ' Keşif Gezegeni';
}
try{ window.evDiscoveryPlanetTitle=evDiscoveryPlanetTitle; }catch(e){}

function startHouse(){
  var nm=document.getElementById('ni').value.trim();
  playerName=nm||'Kahraman';
  // V48S44: oyuncu adını yerel cihazda kilitle; görev/robot kayıtları isme göre ayrılır.
  try{ localStorage.setItem('eduverse_player_name', playerName); localStorage.setItem('playerName', playerName); }catch(e){}
  // LOCAL_EDGE_FIX: on file:// do not touch browser permission APIs; Edge can keep the tab spinning. HTTPS deploy may ask normally.
  try{ if(String(location.protocol||'')!=='file:' && typeof evRestoreLocationPermissionFlow==='function') evRestoreLocationPermissionFlow('startHouse'); }catch(e){}
  // Yeni oyuncu — hazine tamamen sıfırla
  localStorage.removeItem(_hzKey());
  // Yeni oyuncu — yemek besleme sıfırla (her kullanıcı kendi gününde besler)
  var _fedToday = new Date().toDateString();
  var _fedData = {};
  try{ _fedData = JSON.parse(localStorage.getItem(_fedKey())||'{}')||{}; }catch(e){ _fedData = {}; try{ localStorage.removeItem(_fedKey()); }catch(_rf){} }
  delete _fedData[_fedToday];
  try{ localStorage.setItem(_fedKey(), JSON.stringify(_fedData)); }catch(e){}
  var _hov=document.getElementById('hazine-done-ov');
  if(_hov) _hov.remove();
  _lastOkiMsg = '';
  _okiPopCount = 0;
  _okiGameMsgIdx = 0;

  // İsme özel kayıt yükle
  try{ _eduGetScoped('oki_char', localStorage.getItem('oki_char')||'erkek'); _eduGetScoped('oki_wardrobe', localStorage.getItem('oki_wardrobe')||'{}'); _eduGetScoped('sr_owned', localStorage.getItem('sr_owned')||'[]'); _eduGetScoped('sr_wearing', localStorage.getItem('sr_wearing')||'{}'); _eduGetScoped('sr_spent', localStorage.getItem('sr_spent')||'0'); _eduGetScoped('dei_streak', localStorage.getItem('dei_streak')||'0'); _eduGetScoped('dei_last', localStorage.getItem('dei_last')||''); }catch(e){}
  var saved={};
  try{ saved=JSON.parse(localStorage.getItem(_playerKey())||'{}')||{}; }catch(e){ saved={}; try{ localStorage.removeItem(_playerKey()); }catch(_rs){} }
  var _legacyScore=_eduScoreLegacyMax();
  totalScore    = parseInt((saved.score!==undefined?saved.score:_legacyScore)||0);
  if(!saved.score && _legacyScore>totalScore) totalScore=_legacyScore;
  secretScore   = parseInt(saved.secret||0);
  roomBests     = saved.bests||{};
  learnedWords  = saved.words||{};
  seenCount     = saved.seen||{};
  _shopRoomOwned   = saved.owned||_eduJsonGetScoped('sr_owned',[]);
  _shopRoomWearing = saved.wearing||_eduJsonGetScoped('sr_wearing',{});

  // Karakter - SAFE_ENTRY_FIX: girişte seçilen Edu/Verse değerini normalize et; otomatik load seçimi kullanıcı seçimi sayılmaz.
  try{
    var _entryChar = _normalizeOkiChar(_selectedChar||_eduGetScoped('oki_char','erkek'));
    var _savedRaw = saved.char || _eduGetScoped('oki_char','erkek') || 'erkek';
    var _savedChar = _normalizeOkiChar(_savedRaw);
    var _finalChar = _charSelectedOnEntry ? _entryChar : (_savedChar || _entryChar || 'erkek');
    _selectedChar = _finalChar;
    _eduSetScoped('oki_char', _finalChar);
    localStorage.setItem('oki_char', _finalChar);
  }catch(e){}
  try{ _eduJsonSetScoped('oki_wardrobe', saved.wardrobe||_eduJsonGetScoped('oki_wardrobe',{})); }catch(e){}

  // Streak — isime özel
  try{
    if(saved.streak!==undefined) _eduSetScoped('dei_streak', saved.streak);
    else _eduSetScoped('dei_streak', _eduGetScoped('dei_streak','0'));
    if(saved.last!==undefined) _eduSetScoped('dei_last', saved.last);
    else _eduSetScoped('dei_last', _eduGetScoped('dei_last',''));
  }catch(e){}
  _eduScoreSync(totalScore);

  localStorage.setItem('dei_lastplayer', playerName);

  updateStreak();
  nextAch=0; for(var i=0;i<ACH_LIST.length;i++) if(totalScore>=ACH_LIST[i].at) nextAch=i+1;
  document.getElementById('ns').style.display='none';
  document.getElementById('hm').style.display='flex';
  setTimeout(function(){ showStreakOverlay(); }, 1200);
  document.getElementById('hm-title').textContent=evDiscoveryPlanetTitle(playerName);
  document.getElementById('hsc').textContent=totalScore;
  updateLvl(); buildGrid();
  setTimeout(initOki,100);
  // Müzik player'ı göster
  setTimeout(function(){ var m=document.getElementById('ada-muzik'); if(m) m.style.display='flex'; },500);
  // Preload voices
  if(window.speechSynthesis) window.speechSynthesis.getVoices();
}

