function isFemale(){
  var n=playerName.toLowerCase();
  var f=['ayse','fatma','zeynep','elif','selin','damla','esra','merve','busra','nisa','hilal','rabia'];
  return f.indexOf(n)>=0||(n.length>3&&(n[n.length-1]==='e'||n[n.length-1]==='a'));
}

function drawFriendChar(x,y,ts){
  var s=52; var bounce=Math.sin(ts*.003)*4;
  ctx.save(); ctx.translate(x,y+bounce);
  // Shadow
  ctx.fillStyle='rgba(0,0,0,.12)'; ctx.beginPath(); ctx.ellipse(0,s*.5+5,s*.32,s*.07,0,0,Math.PI*2); ctx.fill();
  // Legs
  ctx.fillStyle='#E8B400'; ctx.fillRect(-s*.15,s*.24,s*.13,s*.26); ctx.fillRect(s*.02,s*.24,s*.13,s*.26);
  ctx.fillStyle='#D4A017'; ctx.beginPath(); ctx.ellipse(-s*.08,s*.5,s*.1,s*.05,0,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(s*.08,s*.5,s*.1,s*.05,0,0,Math.PI*2); ctx.fill();
  // Body - blue for boy friend, pink for girl friend
  var bodyCol=isFemale()?'#6a9ae0':'#FF9EC5';
  var bodyGrad=ctx.createRadialGradient(-s*.08,-s*.04,0,0,s*.1,s*.38);
  bodyGrad.addColorStop(0,'#FFE566'); bodyGrad.addColorStop(1,'#FFD700');
  ctx.fillStyle=bodyGrad; ctx.beginPath(); ctx.ellipse(0,s*.16,s*.26,s*.3,0,0,Math.PI*2); ctx.fill();
  // Arms
  ctx.fillStyle='#FFD700'; ctx.save(); ctx.rotate(-.22); ctx.beginPath(); ctx.ellipse(-s*.3,s*.07,s*.09,s*.06,0,0,Math.PI*2); ctx.fill(); ctx.restore();
  ctx.save(); ctx.rotate(.22); ctx.beginPath(); ctx.ellipse(s*.3,s*.07,s*.09,s*.06,0,0,Math.PI*2); ctx.fill(); ctx.restore();
  // Head
  var hg=ctx.createRadialGradient(-s*.1,-s*.22,s*.04,0,-s*.2,s*.28);
  hg.addColorStop(0,'#FFF0A0'); hg.addColorStop(1,'#FFE566');
  ctx.fillStyle=hg; ctx.beginPath(); ctx.arc(0,-s*.2,s*.28,0,Math.PI*2); ctx.fill();
  // Hair/Hijab
  if(isFemale()){
    ctx.fillStyle='#A0C8F0'; ctx.beginPath(); ctx.ellipse(0,-s*.2,s*.26,s*.32,0,0,Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(s*.04,-s*.06,s*.32,s*.19,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='#FDDCB8'; ctx.beginPath(); ctx.arc(0,-s*.24,s*.2,0,Math.PI*2); ctx.fill();
  } else {
    ctx.fillStyle='#5a3a1a'; ctx.beginPath(); ctx.arc(0,-s*.3,s*.25,Math.PI,0); ctx.fill();
  }
  // Eyes
  ctx.fillStyle='white'; ctx.beginPath(); ctx.arc(-s*.09,-s*.26,s*.08,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(s*.09,-s*.26,s*.08,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#2a2a2a'; ctx.beginPath(); ctx.arc(-s*.08,-s*.255,s*.04,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(s*.1,-s*.255,s*.04,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='white'; ctx.beginPath(); ctx.arc(-s*.06,-s*.272,s*.016,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(s*.12,-s*.272,s*.016,0,Math.PI*2); ctx.fill();
  // Cheeks
  ctx.fillStyle='rgba(255,150,100,.28)'; ctx.beginPath(); ctx.arc(-s*.18,-s*.2,s*.065,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(s*.18,-s*.2,s*.065,0,Math.PI*2); ctx.fill();
  // Smile
  ctx.strokeStyle='#D4A017'; ctx.lineWidth=2; ctx.beginPath(); ctx.arc(0,-s*.14,s*.08,.1,Math.PI-.1); ctx.stroke();
  // Speech bubble
  if(friendMsg && Date.now()<friendMsgT){
    var bx=Math.min(W-140,Math.max(100,x+80)), by=y-s*.7+bounce;
    ctx.save(); ctx.fillStyle='rgba(255,255,255,.92)'; ctx.shadowColor='rgba(0,0,0,.2)'; ctx.shadowBlur=8;
    ctx.beginPath(); ctx.roundRect(bx-85,by-20,170,40,12); ctx.fill(); ctx.shadowBlur=0;
    ctx.fillStyle='#333'; ctx.font='bold 11px Nunito'; ctx.textAlign='center'; ctx.textBaseline='middle';
    var txt=friendMsg.length>22?friendMsg.substr(0,22):friendMsg;
    ctx.fillText(txt,bx,by); ctx.restore();
  }
  ctx.restore();
}

function drawFireTrail(x,y){
  for(var i=0;i<3;i++){
    fireParts.push({x:x+(Math.random()-.5)*16,y:y,vx:(Math.random()-.5)*1.5,vy:-Math.random()*3-1.5,al:0.8,dc:0.04,r:Math.random()*8+4});
  }
  fireParts=fireParts.filter(function(p){
    p.x+=p.vx; p.y+=p.vy; p.vy+=.05; p.al-=p.dc;
    if(p.al<=0) return false;
    ctx.save(); ctx.globalAlpha=p.al;
    var fg=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r);
    fg.addColorStop(0,'rgba(255,255,200,'+p.al+')'); fg.addColorStop(.4,'rgba(255,150,0,'+p.al+')'); fg.addColorStop(1,'rgba(200,0,0,0)');
    ctx.fillStyle=fg; ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fill();
    ctx.restore(); return p.al>0;
  });
}

function drawSecretExtras(ts){
  // Background phase
  var phase = secretScore<200?0:secretScore<900?1:secretScore<2200?2:secretScore<3000?3:4;
  // Phase overlay
  if(phase>=2){
    // Ocean
    var wg=ctx.createLinearGradient(0,H*.62,0,H);
    wg.addColorStop(0,'#1a5a8a'); wg.addColorStop(1,'#0a2a4a');
    ctx.fillStyle=wg; ctx.fillRect(0,H*.62,W,H*.38);
    for(var i=0;i<3;i++){
      ctx.strokeStyle='rgba(100,200,255,'+(0.15+i*.04)+')'; ctx.lineWidth=2;
      ctx.beginPath();
      for(var wx=0;wx<=W;wx+=5){var wy=H*(.63+i*.025)+Math.sin((wx+ts*.06)*.022+i)*12;wx===0?ctx.moveTo(wx,wy):ctx.lineTo(wx,wy);}
      ctx.stroke();
    }
  }
  if(phase>=3){
    // Race track
    ctx.fillStyle='#2a2a2a'; ctx.fillRect(0,H*.72,W,H*.28);
    ctx.strokeStyle='rgba(255,255,0,.5)'; ctx.lineWidth=3; ctx.setLineDash([28,18]);
    ctx.beginPath(); ctx.moveTo(0,H*.82); ctx.lineTo(W,H*.82); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle='#333'; ctx.fillRect(0,H*.72,W,H*.03);
  }
  if(phase>=4){
    // Golden palace glow
    var gg=ctx.createRadialGradient(W*.5,H*.5,H*.1,W*.5,H*.5,H*.7);
    gg.addColorStop(0,'rgba(255,200,50,.1)'); gg.addColorStop(1,'transparent');
    ctx.fillStyle=gg; ctx.fillRect(0,0,W,H);
  }
  // Rocket
  if(rocketActive){
    rocketY-=3.5;
    if(rocketY<-200){rocketActive=false;rocketY=H+200;}
    var rx=W*.5+Math.sin(ts*.0008)*W*.04;
    drawFireTrail(rx,rocketY+75);
    ctx.save(); ctx.translate(rx,rocketY);
    ctx.fillStyle='#C0C8D8'; ctx.beginPath(); ctx.ellipse(0,0,16,42,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='#E8EEF8'; ctx.beginPath(); ctx.ellipse(-5,-8,7,16,-.3,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='#FF4444'; ctx.beginPath(); ctx.moveTo(0,-42); ctx.lineTo(-16,-4); ctx.lineTo(16,-4); ctx.closePath(); ctx.fill();
    ctx.fillStyle='#4466CC'; ctx.beginPath(); ctx.moveTo(-16,28); ctx.lineTo(-32,50); ctx.lineTo(-16,42); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(16,28); ctx.lineTo(32,50); ctx.lineTo(16,42); ctx.closePath(); ctx.fill();
    ctx.fillStyle='rgba(100,200,255,.8)'; ctx.beginPath(); ctx.arc(0,0,8,0,Math.PI*2); ctx.fill();
    ctx.restore();
  }
  // Ship
  if(shipActive){
    shipX+=1.2;
    if(shipX>W+400){shipActive=false;}
    ctx.save(); ctx.translate(shipX,H*.62);
    ctx.fillStyle='#8B4513'; ctx.beginPath(); ctx.moveTo(-110,0); ctx.lineTo(-120,38); ctx.lineTo(120,38); ctx.lineTo(110,0); ctx.closePath(); ctx.fill();
    ctx.fillStyle='#A0522D'; ctx.fillRect(-95,-18,190,20);
    ctx.fillStyle='#DEB887'; ctx.fillRect(-85,-20,170,4);
    ctx.fillStyle='#5C3317'; ctx.fillRect(-3,-75,6,58);
    ctx.fillStyle='rgba(245,235,210,.88)'; ctx.beginPath(); ctx.moveTo(0,-75); ctx.lineTo(52,-52); ctx.lineTo(0,-18); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(0,-75); ctx.lineTo(-52,-52); ctx.lineTo(0,-18); ctx.closePath();
    ctx.fillStyle='rgba(230,220,195,.8)'; ctx.fill();
    ctx.fillStyle='#CC2222'; ctx.fillRect(0,-90,22,13);
    ctx.restore();
  }
  // Car
  if(carActive){
    carX+=carSpeed; carSpeed=Math.min(carSpeed+.06,13);
    if(carX>W+300){carActive=false;}
    // Speed lines
    ctx.strokeStyle='rgba(255,200,50,.25)'; ctx.lineWidth=2;
    for(var i=0;i<4;i++){ctx.beginPath();ctx.moveTo(carX-100-i*35,H*.78+i*6);ctx.lineTo(carX-170-i*35,H*.78+i*6);ctx.stroke();}
    drawFireTrail(carX-65,H*.79);
    ctx.save(); ctx.translate(carX,H*.79);
    var cg=ctx.createLinearGradient(-62,-14,62,28); cg.addColorStop(0,'#FF2222'); cg.addColorStop(.5,'#FF5555'); cg.addColorStop(1,'#CC0000');
    ctx.fillStyle=cg; ctx.beginPath(); ctx.roundRect(-62,-13,124,33,7); ctx.fill();
    ctx.fillStyle='#CC1111'; ctx.beginPath(); ctx.moveTo(-28,-13); ctx.quadraticCurveTo(-18,-38,8,-38); ctx.quadraticCurveTo(33,-38,42,-13); ctx.closePath(); ctx.fill();
    ctx.fillStyle='rgba(100,200,255,.72)'; ctx.beginPath(); ctx.moveTo(-16,-13); ctx.quadraticCurveTo(-8,-32,6,-32); ctx.quadraticCurveTo(26,-32,35,-13); ctx.closePath(); ctx.fill();
    [[-40,19],[40,19]].forEach(function(w){
      ctx.fillStyle='#1a1a1a'; ctx.beginPath(); ctx.arc(w[0],w[1],15,0,Math.PI*2); ctx.fill();
      ctx.fillStyle='#555'; ctx.beginPath(); ctx.arc(w[0],w[1],9,0,Math.PI*2); ctx.fill();
      ctx.strokeStyle='#777'; ctx.lineWidth=1.5;
      for(var s=0;s<4;s++){var sa=s*Math.PI/2+ts*.015*carSpeed;ctx.beginPath();ctx.moveTo(w[0],w[1]);ctx.lineTo(w[0]+Math.cos(sa)*8,w[1]+Math.sin(sa)*8);ctx.stroke();}
    });
    ctx.fillStyle='white'; ctx.font='bold 13px Fredoka One'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText('1',0,-25);
    ctx.restore();
  }
  // Friend character
  if(!friendX) friendX=W*.25;
  if(Math.random()<.008) friendX=Math.random()*(W*.6)+W*.15;
  drawFriendChar(friendX,H*.76,ts);
  // Fire particles
  if(Math.random()<.06) drawFireTrail(Math.random()*W,H*.85+Math.random()*H*.1);
}



