function getMelekSize(){
  var fed=JSON.parse(localStorage.getItem(_fedKey())||'{}');
  var streak=0;
  // Count days fed (skip today if not yet fed - don't punish)
  for(var i=1;i<=30;i++){
    var d=new Date(); d.setDate(d.getDate()-i);
    if(fed[d.toDateString()]) streak++;
    else break;
  }
  // Also count today if fed
  if(fed[new Date().toDateString()]) streak++;
  // Size: starts at 0.45, grows per day fed, max 1.0
  return Math.min(1.0, 0.45+streak*0.06);
}

function feedMelek(){
  var fed=JSON.parse(localStorage.getItem(_fedKey())||'{}');
  var today=new Date().toDateString();
  if(fed[today]){
    var alreadyFood=getTodayFood();
    showOkiBubble(evEnglishValuesActive()?'I already ate '+evEnglishFoodName(alreadyFood.name)+' today. Come back tomorrow!':(evValuesOn()&&evValuesLang()==='de'?'Heute habe ich schon '+evGermanFoodName(alreadyFood.name)+' gegessen. Komm morgen wieder!':'Bugun zaten '+alreadyFood.name+' yedim! Yarin gel!'));
    return;
  }
  fed[today]=true;
  localStorage.setItem(_fedKey(),JSON.stringify(fed));
  var food=getTodayFood();
  totalScore+=20; savePlayerData();
  document.getElementById('hsc').textContent=totalScore;
  updateLvl();
  showOkiBubble(evEnglishValuesActive()?'Yum! I ate '+evEnglishFoodName(food.name)+'! +20 stars':(evValuesOn()&&evValuesLang()==='de'?evGermanFoodName(food.name)+' gegessen! +20 Sterne':food.ico+' '+food.name+' yedim! +20'));
  setTimeout(function(){ initOki(); },600);
  for(var i=0;i<3;i++) setTimeout(function(){burst(60+Math.random()*100,120+Math.random()*60,'#FFD700',false);},i*200);
  playSpec();
}

