function showParentQR(){
  evFixReportShareChrome();
  var d = buildReportData();
  document.getElementById('qr-ov').style.display='flex';
  // Let DOM render first, then draw
  setTimeout(function(){
    var prev = document.getElementById('qr-preview');
    if(prev) prev.innerHTML = buildReportHTML(d, false);
    drawSimpleQR(d);
  }, 50);
}

