// Seçilen dile göre dua içeriğini al
function _getDuaLocal(d){
  var L = _duaLang || 'tr';
  var loc = d[L] || d.tr;
  var safeIcons={sabah:'\uD83C\uDF05',gece:'\uD83C\uDF19',istek:'\u2728',sukur:'\uD83D\uDC9B',yemek:'\uD83C\uDF7D\uFE0F',yolculuk:'\u2708\uFE0F',ders:'\uD83D\uDCDA',uyku:'\uD83D\uDE34'};
  return {ico:safeIcons[d.key]||'\u2728', name:loc.name, text:loc.text, key:d.key};
}
var _selDua=null,_duaSkyAnim=null,_duaAngelAnim=null;


// Dua overlay'ini seçilen dile çevir
function _applyDuaLang(){
  var L = DUA_LANG_DATA[_duaLang] || DUA_LANG_DATA.tr;
  // DUAS isimlerini çevir
  var nameMap = ['sabah','gece','istek','sukur','yemek','yolculuk','ders','uyku'];
  DUAS.forEach(function(d,i){
    if(L.duaNames && L.duaNames[nameMap[i]]) d._localName = L.duaNames[nameMap[i]];
    else d._localName = d.name;
  });
  // Butonları bul ve güncelle
  var kendiBtn = document.querySelector('[onclick="duaKendiYaz()"]');
  if(kendiBtn) kendiBtn.firstChild && (kendiBtn.innerHTML = L.kendiDua);
  var geriBtn = document.querySelector('[onclick="closeDuaOv()"]');
  // Mühürle butonu
  var muhurBtn = document.getElementById('dua-send-btn');
  if(muhurBtn) muhurBtn.textContent = L.muhurBtn;
  // Başka dua seç
  var baskaBtn = document.querySelector('[onclick="duaGeri()"]');
  if(baskaBtn) baskaBtn.textContent = L.baskaSecBtn;
}

