var _prayerTimers = [];
var _prayerTimes = null;
var _prayerNames = {
  Fajr:'Sabah Namazı 🌅',
  Dhuhr:'Öğle Namazı ☀️',
  Asr:'İkindi Namazı 🌤️',
  Maghrib:'Akşam Namazı 🌇',
  Isha:'Yatsı Namazı 🌙'
};

function initPrayerTimes(){
  /* V48S73: Values/login ekraninda konum veya bildirim izni isteme.
     Namaz vakti sistemi sadece Dua/Ibadet tarafinda kullanilsin. */
  try{ if(typeof evValuesOn==='function' && evValuesOn()) return; }catch(e){}
  try{ if(localStorage.getItem('eduverse_values_mode')==='1') return; }catch(e2){}
  try{
    var ns=document.getElementById('ns');
    var cs=ns?window.getComputedStyle(ns):null;
    if(cs && cs.display!=='none' && cs.visibility!=='hidden') return;
  }catch(e3){}
  if('Notification' in window && Notification.permission==='default'){
    Notification.requestPermission();
  }
  if(!navigator.geolocation){ return; }
  navigator.geolocation.getCurrentPosition(function(pos){
    _fetchPrayerTimes(pos.coords.latitude, pos.coords.longitude);
  }, function(err){
    console.warn('Location unavailable:', err.message);
  }, {timeout:3000});
}


/* V48S81 ROBOT TRIAL: restore non-blocking location permission flow.
   Must not block entry. It only asks for location from a real click/enter gesture
   and feeds the existing namaz time system when permission is granted. */
var _evLocationPermissionAskedThisSession = false;
function evRestoreLocationPermissionFlow(reason){
  try{
    if(_evLocationPermissionAskedThisSession) return;
    _evLocationPermissionAskedThisSession = true;
    if(!navigator.geolocation){ return; }
    // Edge/local file safety: file:// pages can leave the tab spinning or permission in an odd state.
    // In local desktop tests, do not block entry with browser permission; deployed HTTPS can ask normally.
    if(String(location.protocol||'')==='file:'){
      try{ localStorage.setItem('eduverse_location_permission_status','local_file_skipped'); }catch(_lf){}
      return;
    }
    if('Notification' in window && Notification.permission==='default'){
      try{ Notification.requestPermission(); }catch(_nerr){}
    }
    navigator.geolocation.getCurrentPosition(function(pos){
      try{
        localStorage.setItem('eduverse_location_permission_status','granted');
        localStorage.setItem('eduverse_location_last_reason', String(reason||'entry'));
      }catch(_s1){}
      try{ _fetchPrayerTimes(pos.coords.latitude, pos.coords.longitude); }catch(_ferr){}
    }, function(err){
      try{
        localStorage.setItem('eduverse_location_permission_status', err && err.code===1 ? 'denied' : 'unavailable');
        localStorage.setItem('eduverse_location_last_error', err && err.message ? String(err.message) : 'unknown');
      }catch(_s2){}
      try{ console.warn('Location permission flow:', err && err.message ? err.message : err); }catch(_c){}
    }, {enableHighAccuracy:false, timeout:7000, maximumAge:21600000});
  }catch(e){ try{ console.warn('Location permission flow failed:', e); }catch(_e){} }
}

function _fetchPrayerTimes(lat, lng){
  var now = new Date();
  var ts = Math.floor(now.getTime()/1000);
  var url = 'https://api.aladhan.com/v1/timings/'+ts+'?latitude='+lat+'&longitude='+lng+'&method=13';
  
  fetch(url)
    .then(function(r){ return r.json(); })
    .then(function(data){
      if(data.code!==200) return;
      _prayerTimes = data.data.timings;
      _schedulePrayers(_prayerTimes);
      _showNextPrayer(_prayerTimes);
    })
    .catch(function(e){ console.warn('Namaz vakitleri alınamadı'); });
}

function _schedulePrayers(timings){
  // Clear old timers
  _prayerTimers.forEach(function(t){ clearTimeout(t); });
  _prayerTimers = [];
  
  var now = new Date();
  var prayers = ['Fajr','Dhuhr','Asr','Maghrib','Isha'];
  
  prayers.forEach(function(prayer){
    var timeStr = timings[prayer]; // e.g. "05:32"
    if(!timeStr) return;
    var parts = timeStr.split(':');
    var prayerDate = new Date();
    prayerDate.setHours(parseInt(parts[0]), parseInt(parts[1]), 0, 0);
    
    var diff = prayerDate - now;
    if(diff < -60000) return; // already passed (more than 1 min ago)
    if(diff < 0) diff = 0;
    
    var timer = setTimeout(function(){
      _onPrayerTime(prayer, timeStr);
    }, diff);
    _prayerTimers.push(timer);
    
    // 10 min warning
    if(diff > 600000){
      var warnTimer = setTimeout(function(){
        _showPrayerWarning(prayer, timeStr);
      }, diff - 600000);
      _prayerTimers.push(warnTimer);
    }
  });
}

function _onPrayerTime(prayer, timeStr){
  if(evValuesOn()) return;
  var name = _prayerNames[prayer] || prayer;
  // Show banner
  var banner = document.getElementById('prayer-banner');
  var nameEl = document.getElementById('prayer-name');
  var txtEl = document.getElementById('prayer-time-txt');
  if(banner && nameEl && txtEl){
    nameEl.textContent = name;
    txtEl.textContent = timeStr + ' — Namaz vakti geldi';
    banner.style.display = 'block';
    // Auto hide after 30s
    setTimeout(function(){
      if(banner) banner.style.display='none';
    }, 30000);
  }
  // Browser notification
  if('Notification' in window && Notification.permission==='granted'){
    new Notification('🕌 '+name, {
      body: timeStr+' — Allah kabul etsin 🤲',
      icon: 'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><text y=".9em" font-size="90">🕌</text></svg>',
      tag: 'prayer-'+prayer
    });
  }
  // Play azan sound (simple tone sequence)
  _playAzanTone();
}

function _showPrayerWarning(prayer, timeStr){
  if(evValuesOn()) return;
  var name = _prayerNames[prayer] || prayer;
  var banner = document.getElementById('prayer-banner');
  var nameEl = document.getElementById('prayer-name');
  var txtEl = document.getElementById('prayer-time-txt');
  if(banner && nameEl && txtEl){
    nameEl.textContent = name+' — 10 Dakika Kaldı ⏰';
    txtEl.textContent = timeStr+' saatinde namaz vakti';
    banner.style.display='block';
    setTimeout(function(){ if(banner) banner.style.display='none'; }, 15000);
  }
}

function _showNextPrayer(timings){
  var now = new Date();
  var prayers = ['Fajr','Dhuhr','Asr','Maghrib','Isha'];
  var next = null;
  prayers.forEach(function(p){
    var parts = (timings[p]||'').split(':');
    var pd = new Date();
    pd.setHours(parseInt(parts[0]||0), parseInt(parts[1]||0), 0, 0);
    if(pd > now && !next) next = {name:_prayerNames[p], time:timings[p]};
  });
  if(!next) return;
  // Update home screen if visible
  var el = document.getElementById('prayer-next');
  if(el){ el.textContent = 'Sonraki namaz: '+next.name+' — '+next.time; }
}

function _playAzanTone(){
  try{
    var ac2=new(window.AudioContext||window.webkitAudioContext)();
    // Simple ascending spiritual tone
    var freqs=[440,495,440,392,440,495,528];
    var time=ac2.currentTime;
    freqs.forEach(function(f,i){
      var o=ac2.createOscillator(),g=ac2.createGain();
      o.type='sine'; o.frequency.value=f;
      g.gain.setValueAtTime(0,time+i*.4);
      g.gain.linearRampToValueAtTime(.15,time+i*.4+.15);
      g.gain.exponentialRampToValueAtTime(.001,time+i*.4+.5);
      o.connect(g); g.connect(ac2.destination);
      o.start(time+i*.4); o.stop(time+i*.4+.6);
    });
  }catch(e){}
}

// Start prayer system when page loads
window.addEventListener('load', function(){
  try{ if(String(location.protocol||'')==='file:') return; }catch(_filePrayer){}
  setTimeout(initPrayerTimes, 2000);
  // Refresh daily at midnight
  var msToMidnight = new Date();
  msToMidnight.setHours(24,0,5,0);
  setTimeout(function(){
    try{ if(typeof evValuesOn==='function' && evValuesOn()) return; }catch(e){}
    try{ if(localStorage.getItem('eduverse_values_mode')==='1') return; }catch(e2){}
    if(navigator.geolocation){
      navigator.geolocation.getCurrentPosition(function(pos){
        _fetchPrayerTimes(pos.coords.latitude, pos.coords.longitude);
      });
    }
  }, msToMidnight - new Date());
});

