function okiEnterRoom(roomId){
  var enValues=!!(evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='en');
  var enRoomMessages={
    ders:[
      '_N, welcome to the Learning Room! Today we will discover new ideas! 📚',
      '_N, learning time! Let us begin! 💡',
      '_N, books and questions are great friends! 📖'
    ]
  };
  var msgs = (enValues && enRoomMessages[roomId]) ? enRoomMessages[roomId] : (_okiRoomMessages[roomId] || _defaultRoomMsgs);
  var msg = msgs[Math.floor(Math.random()*msgs.length)];
  setTimeout(function(){
    showOkiBubble(msg);
    // Odaya girerken COŞKULU — zıpla ve spark at
    setCharState('jump', 1800);
    setTimeout(_spawnSpark, 200);
    setTimeout(_spawnSpark, 400);
    setTimeout(_spawnSpark, 600);
  }, 600);
}
