var _okiTapIdx = 0;
var _okiGameMsgIdx = 0;

function _getRoomMsg(){
  var id = currentRoom ? currentRoom.id : 'default';
  var msgs = _okiRoomGameMsgs[id] || _okiRoomGameMsgs.default;
  return msgs[Math.floor(Math.random()*msgs.length)];
}

function _getUniqueMsg(arr){
  var attempts = 0;
  var msg;
  do {
    msg = arr[Math.floor(Math.random()*arr.length)];
    attempts++;
  } while(msg === _lastOkiMsg && attempts < 8);
  _lastOkiMsg = msg;
  // Çalışma zamanında ismi yerleştir — önce _NU (büyük), sonra _N (normal)
  var pn = playerName || '';
  if(msg && pn){
    msg = msg.replace(/_NU/g, pn.toUpperCase()).replace(/_N/g, pn);
  }
  return msg;
}

function okiGameTapped(){
  var msg = _okiTapMsgs[_okiTapIdx % _okiTapMsgs.length];
  _okiTapIdx++;
  _lastOkiMsg = msg;
  showOkiBubble(msg);
  var face = document.getElementById('oki-game-face');
  if(face){
    face.style.transform='scale(1.5) rotate(15deg)';
    setTimeout(function(){ face.style.transform='scale(1) rotate(0deg)'; },300);
  }
  try{
    var ac2=new(window.AudioContext||window.webkitAudioContext)();
    [523,659,784,659,523,440,523].forEach(function(f,i){
      var o=ac2.createOscillator(),g=ac2.createGain();
      o.type='sine'; o.frequency.value=f;
      g.gain.setValueAtTime(0,ac2.currentTime+i*.08);
      g.gain.linearRampToValueAtTime(.1,ac2.currentTime+i*.08+.05);
      g.gain.exponentialRampToValueAtTime(.001,ac2.currentTime+i*.08+.2);
      o.connect(g); g.connect(ac2.destination);
      o.start(ac2.currentTime+i*.08); o.stop(ac2.currentTime+i*.08+.25);
    });
  }catch(e){}
}

