var OKI_COIN_STAGES = [
  {min:0,   name:'Yumurta 🥚',  emoji:'🥚'},
  {min:10,  name:'Bebek 🐣',    emoji:'🐣'},
  {min:30,  name:'Kucuk 🐥',   emoji:'🐥'},
  {min:60,  name:'Genc 🐦',    emoji:'🐦'},
  {min:100, name:'Buyuk ✨',   emoji:'✨'},
  {min:150, name:'Melek 👼',   emoji:'👼'},
];

// ── VERİ FONKSİYONLARI ──
function getTotalStars(){ return totalScore; }
function getCoins(){ return Math.floor(totalScore/100); }
function getTodayKey(){ return new Date().toDateString(); }
function getTodayStars(){
  var k='daily_stars_'+_playerKey()+'_'+getTodayKey();
  return parseInt(localStorage.getItem(k)||'0');
}
function saveTodayStars(n){
  localStorage.setItem('daily_stars_'+_playerKey()+'_'+getTodayKey(), n);
  savePlayerData();
}
function getCoinStage(){
  var c=getCoins();
  for(var i=OKI_COIN_STAGES.length-1;i>=0;i--)
    if(c>=OKI_COIN_STAGES[i].min) return OKI_COIN_STAGES[i];
  return OKI_COIN_STAGES[0];
}
function get7DayScores(){
  var scores=[];
  for(var i=6;i>=0;i--){
    var d=new Date(); d.setDate(d.getDate()-i);
    var k='daily_stars_'+_playerKey()+'_'+d.toDateString();
    var v=parseInt(localStorage.getItem(k)||'0');
    scores.push(v);
  }
  return scores;
}

// ── MİNİ ÇİZİCİLER ──
var _miniAnim=null;
function startMiniAnim(){
  if(_miniAnim) return;
  function tick(ts){
    _drawHeartMini(ts);
    _drawCrystalMini(ts);
    _drawGoldMini(ts);
    _updateVals();
    _miniAnim=requestAnimationFrame(tick);
  }
  _miniAnim=requestAnimationFrame(tick);
}

function _updateVals(){
  var se=document.getElementById('jar-heart-val');
  var ce=document.getElementById('jar-crystal-val');
  var ge=document.getElementById('jar-gold-val');
  var lh=document.querySelector('#jar-heart + div'); if(lh) lh.textContent=evJarText('starsTitle');
  var lc=document.querySelector('#jar-crystal + div'); if(lc) lc.textContent=evJarText('coinsTitle');
  var lg=document.querySelector('#jar-gold + div'); if(lg) lg.textContent=evJarText('todayTitle');
  if(se) se.textContent=getTotalStars()+' '+evJarText('stars');
  if(ce) ce.textContent=getCoins()+' '+evJarText('coins');
  if(ge) ge.textContent='+'+getTodayStars()+' '+evJarText('today');
}

function _drawHeartMini(ts){
  var c=document.getElementById('jar-heart');
  if(!c) return;
  var ctx=c.getContext('2d'), W=c.width, H=c.height, t=ts*.001;
  ctx.clearRect(0,0,W,H);
  var pulse=1+Math.sin(t*2)*.05;
  var cx=W/2, cy=H/2-4, s=W*.38*pulse;
  ctx.save(); ctx.translate(cx,cy); ctx.scale(s,s);
  ctx.beginPath();
  ctx.moveTo(0,.3);
  ctx.bezierCurveTo(0,-.1,-.5,-.5,-1,-.1);
  ctx.bezierCurveTo(-1.4,.3,-1,.9,0,1.4);
  ctx.bezierCurveTo(1,.9,1.4,.3,1,-.1);
  ctx.bezierCurveTo(.5,-.5,0,-.1,0,.3);
  ctx.closePath();
  var g=ctx.createRadialGradient(-.2,-.1,.1,0,.5,1.2);
  g.addColorStop(0,'rgba(255,180,180,.9)');
  g.addColorStop(.4,'rgba(220,50,80,.85)');
  g.addColorStop(1,'rgba(150,0,40,.9)');
  ctx.fillStyle=g; ctx.fill();
  ctx.fillStyle='rgba(255,255,255,.35)';
  ctx.beginPath(); ctx.ellipse(-.35,-.25,.18,.28,-.5,0,Math.PI*2); ctx.fill();
  ctx.restore();
  // Stars
  var stars=Math.min(5,Math.floor(getTotalStars()/200)+1);
  for(var i=0;i<stars;i++){
    var ang=t*.4+i*(Math.PI*2/Math.max(stars,1));
    ctx.font='9px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.globalAlpha=.7;
    ctx.beginPath(); ctx.arc(cx+Math.cos(ang)*W*.2,cy+Math.sin(ang)*H*.14+H*.06,2.2,0,Math.PI*2); ctx.fillStyle='rgba(255,215,80,.9)'; ctx.fill();
  }
  ctx.globalAlpha=1;
}

function _drawCrystalMini(ts){
  var c=document.getElementById('jar-crystal');
  if(!c) return;
  var ctx=c.getContext('2d'), W=c.width, H=c.height, t=ts*.001;
  ctx.clearRect(0,0,W,H);
  var cx=W/2, cy=H/2-2, r=W*.36;
  var glow=ctx.createRadialGradient(cx,cy,r*.1,cx,cy,r*1.5);
  glow.addColorStop(0,'rgba(160,80,255,.3)'); glow.addColorStop(1,'transparent');
  ctx.fillStyle=glow; ctx.fillRect(0,0,W,H);
  var sg=ctx.createRadialGradient(cx-r*.3,cy-r*.3,r*.05,cx,cy,r);
  sg.addColorStop(0,'rgba(255,255,255,.65)');
  sg.addColorStop(.25,'rgba(180,120,255,.8)');
  sg.addColorStop(.7,'rgba(100,40,200,.9)');
  sg.addColorStop(1,'rgba(60,0,140,.95)');
  ctx.fillStyle=sg; ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2); ctx.fill();
  // Stars inside
  for(var i=0;i<8;i++){
    var a=.12+.88*(.5+.5*Math.sin(t*2+i));
    ctx.beginPath(); ctx.arc(cx+Math.cos(i*1.3+t*.3)*r*.6,cy+Math.sin(i*.9+t*.4)*r*.5,1.2,0,Math.PI*2);
    ctx.fillStyle='rgba(255,255,255,'+a+')'; ctx.fill();
  }
  var stage=getCoinStage();
  ctx.font=Math.round(r*.65)+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.globalAlpha=.85+Math.sin(t*1.5)*.1;
  ctx.fillStyle='rgba(220,185,255,.95)'; ctx.beginPath(); ctx.moveTo(cx,cy-r*.42); ctx.lineTo(cx+r*.34,cy); ctx.lineTo(cx,cy+r*.42); ctx.lineTo(cx-r*.34,cy); ctx.closePath(); ctx.fill(); ctx.globalAlpha=1;
  ctx.fillStyle='rgba(255,255,255,.2)';
  ctx.beginPath(); ctx.ellipse(cx-r*.28,cy-r*.28,r*.16,r*.1,-.5,0,Math.PI*2); ctx.fill();
}

function _drawGoldMini(ts){
  var c=document.getElementById('jar-gold');
  if(!c) return;
  var ctx=c.getContext('2d'), W=c.width, H=c.height, t=ts*.001;
  ctx.clearRect(0,0,W,H);
  var cx=W/2;
  var jx=W*.1, jy=H*.15, jw=W*.8, jh=H*.65;
  var todayPct=Math.min(1,getTodayStars()/500);
  ctx.fillStyle='rgba(0,0,0,.15)';
  ctx.beginPath(); ctx.ellipse(cx,H*.9,jw*.38,H*.035,0,0,Math.PI*2); ctx.fill();
  ctx.save();
  ctx.beginPath(); ctx.roundRect(jx,jy,jw,jh,6); ctx.clip();
  ctx.fillStyle='rgba(255,250,230,.08)'; ctx.fillRect(jx,jy,jw,jh);
  var fy=jy+jh*(1-todayPct), wave=Math.sin(t*1.5)*2;
  ctx.beginPath(); ctx.moveTo(jx,fy+wave);
  for(var wx=0;wx<=jw;wx+=5)
    ctx.lineTo(jx+wx,fy+Math.sin((wx/jw)*Math.PI*4+t*2)*2+wave);
  ctx.lineTo(jx+jw,jy+jh); ctx.lineTo(jx,jy+jh); ctx.closePath();
  var lg=ctx.createLinearGradient(0,fy,0,jy+jh);
  lg.addColorStop(0,'rgba(255,200,50,.95)'); lg.addColorStop(1,'rgba(200,100,0,.85)');
  ctx.fillStyle=lg; ctx.fill();
  ctx.restore();
  ctx.strokeStyle='rgba(255,215,80,.55)'; ctx.lineWidth=2;
  ctx.beginPath(); ctx.roundRect(jx,jy,jw,jh,6); ctx.stroke();
  ctx.strokeStyle='rgba(255,255,255,.25)'; ctx.lineWidth=2.5;
  ctx.beginPath(); ctx.moveTo(jx+5,jy+8); ctx.lineTo(jx+5,jy+jh-8); ctx.stroke();
  var lidG=ctx.createLinearGradient(0,jy-15,0,jy);
  lidG.addColorStop(0,'#FFE070'); lidG.addColorStop(1,'#CC8800');
  ctx.fillStyle=lidG;
  ctx.beginPath(); ctx.roundRect(jx-3,jy-15,jw+6,16,4); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,.2)';
  ctx.beginPath(); ctx.roundRect(jx+3,jy-12,jw-6,6,2); ctx.fill();
  ctx.fillStyle='#CC8800';
  ctx.beginPath(); ctx.ellipse(cx,jy-17,6,4,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#FFD700';
  ctx.beginPath(); ctx.ellipse(cx,jy-18,4,2.5,0,0,Math.PI*2); ctx.fill();
}


