function _drawCrystalBig(c,ts){
  if(!c||document.getElementById('crystal-ov').style.display==='none'){
    cancelAnimationFrame(_crystalBigAnim); return;
  }
  var ctx=c.getContext('2d'),W=c.width,H=c.height,t=ts*.001;
  ctx.clearRect(0,0,W,H);
  var cx=W/2,cy=H*.5,r=W*.42;
  var glow=ctx.createRadialGradient(cx,cy,r*.1,cx,cy,r*1.6);
  glow.addColorStop(0,'rgba(160,80,255,.35)'); glow.addColorStop(1,'transparent');
  ctx.fillStyle=glow; ctx.fillRect(0,0,W,H);
  var sg=ctx.createRadialGradient(cx-r*.3,cy-r*.3,r*.05,cx,cy,r);
  sg.addColorStop(0,'rgba(255,255,255,.7)'); sg.addColorStop(.25,'rgba(180,120,255,.85)');
  sg.addColorStop(.7,'rgba(100,40,200,.92)'); sg.addColorStop(1,'rgba(60,0,140,.98)');
  ctx.fillStyle=sg; ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2); ctx.fill();
  // Nebula
  ctx.save(); ctx.globalCompositeOperation='screen';
  [[.25,.25,'rgba(200,100,255,.25)'],[.7,.65,'rgba(100,200,255,.18)'],[.4,.7,'rgba(255,150,200,.18)']].forEach(function(n){
    var ng=ctx.createRadialGradient(cx+r*(n[0]-.5)*1.5,cy+r*(n[1]-.5)*1.5,0,cx+r*(n[0]-.5)*1.5,cy+r*(n[1]-.5)*1.5,r*.45);
    ng.addColorStop(0,n[2]); ng.addColorStop(1,'transparent');
    ctx.fillStyle=ng; ctx.fillRect(0,0,W,H);
  });
  ctx.restore();
  // Stars
  for(var i=0;i<16;i++){
    var a=.15+.85*(.5+.5*Math.sin(t*2+i));
    ctx.beginPath(); ctx.arc(cx+Math.cos(i*1.3+t*.3)*r*.65,cy+Math.sin(i*.9+t*.4)*r*.55,1.5,0,Math.PI*2);
    ctx.fillStyle='rgba(255,255,255,'+a+')'; ctx.fill();
  }
  // Floating coins
  var coins=Math.min(8,getCoins());
  for(var j=0;j<coins;j++){
    var ca=t*.4+j*(Math.PI*2/Math.max(coins,1));
    var cr=r*(j%2===0?.45:.3);
    ctx.font='14px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.globalAlpha=.65; ctx.fillStyle='rgba(255,215,80,.9)'; ctx.beginPath(); ctx.arc(cx+Math.cos(ca)*cr,cy+Math.sin(ca)*cr,5,0,Math.PI*2); ctx.fill();
  }
  ctx.globalAlpha=1;
  // Oki
  var stage=getCoinStage();
  ctx.font=Math.round(r*.75)+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.globalAlpha=.9+Math.sin(t*1.5)*.1;
  ctx.fillStyle='rgba(220,185,255,.95)'; ctx.beginPath(); ctx.moveTo(cx,cy-r*.42); ctx.lineTo(cx+r*.34,cy); ctx.lineTo(cx,cy+r*.42); ctx.lineTo(cx-r*.34,cy); ctx.closePath(); ctx.fill(); ctx.globalAlpha=1;
  // Shine
  ctx.fillStyle='rgba(255,255,255,.22)';
  ctx.beginPath(); ctx.ellipse(cx-r*.28,cy-r*.28,r*.18,r*.12,-.5,0,Math.PI*2); ctx.fill();
  // Base
  ctx.fillStyle='rgba(100,50,200,.3)';
  ctx.beginPath(); ctx.ellipse(cx,cy+r+6,r*.45,r*.09,0,0,Math.PI*2); ctx.fill();
}
function _updateCrystalOverlay(){
  var coins=getCoins(), stage=getCoinStage();
  var arJar=evArabicActive();
  var deJar=evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='de';
  var enJar=evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='en';
  var ce=document.getElementById('crystal-count'); if(ce) ce.textContent=arJar?(coins+' '+evAr('coins')):(deJar?(coins+' Muenzen'):(enJar?(coins+' coins'):(coins+' '+evJarText('coins'))));
  var idx=OKI_COIN_STAGES.indexOf(stage), next=OKI_COIN_STAGES[idx+1];
  var arStageNames=[evAr('egg'),evAr('baby'),evAr('child'),evAr('young'),evAr('big'),evAr('angel')];
  var deStageNames=['Ei','Baby','Klein','Jung','Gross','Engel'];
  var enStageNames=['Egg','Baby','Little','Young','Big','Angel'];
  var trStageNames=['Yumurta Oki','Bebek Oki','Küçük Oki','Genç Oki','Büyük Oki','Melek Oki'];
  var trJar=evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='tr';
  var sn=document.getElementById('crystal-stage'); if(sn) sn.textContent=arJar?(stage.emoji+' '+(arStageNames[idx]||stage.name)):(deJar?(stage.emoji+' '+(deStageNames[idx]||stage.name)):(enJar?(stage.emoji+' '+(enStageNames[idx]||stage.name)):(trJar?(stage.emoji+' '+(trStageNames[idx]||stage.name)):stage.name)));
  var pct=next?((coins-stage.min)/(next.min-stage.min))*100:100;
  var bar=document.getElementById('crystal-bar'); if(bar) bar.style.width=Math.min(100,pct)+'%';
  var nt=document.getElementById('crystal-next');
  if(nt) nt.textContent=arJar?(next?('\u0628\u0627\u0642\u064A '+(next.min-coins)+' \u0646\u0642\u0648\u062F \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 '+(arStageNames[idx+1]||next.name)):evAr('maxLevel')):(deJar?(next?((next.min-coins)+' Muenzen bis '+(deStageNames[idx+1]||next.name)):'Maximales Level!'):(enJar?(next?((next.min-coins)+' more coins to '+(enStageNames[idx+1]||next.name)):'Maximum level!'):(trJar?(next?((next.min-coins)+' para daha → '+(trStageNames[idx+1]||next.name)):'Maksimum seviye!'):(next?(next.min-coins)+' '+evJarText('moreCoins')+' -> '+next.name:evJarText('max')))));
}

function showDailyJar(){
  document.getElementById('daily-ov').style.display='block';
  if(evArabicActive()){
    var dailyOv=document.getElementById('daily-ov');
    if(dailyOv){
      var title=dailyOv.querySelector('div[style*="font-size:1.6rem"]'); if(title) title.textContent=evAr('dailyReport');
      var close=dailyOv.querySelector('button'); if(close) close.textContent=evAr('close');
    }
  }
  _updateDailyOverlay();
  function tick(ts){
    _drawGoldBig(document.getElementById('gold-big'),ts);
    _goldBigAnim=requestAnimationFrame(tick);
  }
  if(_goldBigAnim) cancelAnimationFrame(_goldBigAnim);
  _goldBigAnim=requestAnimationFrame(tick);
}
function _drawGoldBig(c,ts){
  if(!c||document.getElementById('daily-ov').style.display==='none'){
    cancelAnimationFrame(_goldBigAnim); return;
  }
  var ctx=c.getContext('2d'),W=c.width,H=c.height,t=ts*.001;
  ctx.clearRect(0,0,W,H);
  var cx=W/2, jx=W*.08, jy=H*.14, jw=W*.84, jh=H*.67;
  var pct=Math.min(1,getTodayStars()/500);
  ctx.fillStyle='rgba(0,0,0,.15)';
  ctx.beginPath(); ctx.ellipse(cx,H*.92,jw*.38,H*.035,0,0,Math.PI*2); ctx.fill();
  ctx.save(); ctx.beginPath(); ctx.roundRect(jx,jy,jw,jh,8); ctx.clip();
  ctx.fillStyle='rgba(255,250,230,.06)'; ctx.fillRect(jx,jy,jw,jh);
  var fy=jy+jh*(1-pct), wave=Math.sin(t*1.5)*3;
  ctx.beginPath(); ctx.moveTo(jx,fy+wave);
  for(var wx=0;wx<=jw;wx+=6)
    ctx.lineTo(jx+wx,fy+Math.sin((wx/jw)*Math.PI*4+t*2)*3+wave);
  ctx.lineTo(jx+jw,jy+jh); ctx.lineTo(jx,jy+jh); ctx.closePath();
  var lg=ctx.createLinearGradient(0,fy,0,jy+jh);
  lg.addColorStop(0,'rgba(255,210,50,.98)'); lg.addColorStop(.5,'rgba(255,160,20,.92)'); lg.addColorStop(1,'rgba(180,80,0,.88)');
  ctx.fillStyle=lg; ctx.fill();
  // Floating emojis
  ['🪙','⭐','💫','🪙','⭐'].forEach(function(ico,i){
    var fx=jx+jw*(.15+i*.18), fy2=fy+10+Math.sin(t*1.2+i)*10+(jh-(fy-jy))*(.2+i*.08);
    if(fy2>jy+jh-6) return;
    ctx.font='13px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.globalAlpha=.75; ctx.fillText(ico,fx,fy2); ctx.globalAlpha=1;
  });
  ctx.restore();
  ctx.strokeStyle='rgba(255,215,80,.6)'; ctx.lineWidth=2.5;
  ctx.beginPath(); ctx.roundRect(jx,jy,jw,jh,8); ctx.stroke();
  ctx.strokeStyle='rgba(255,255,255,.28)'; ctx.lineWidth=3;
  ctx.beginPath(); ctx.moveTo(jx+6,jy+10); ctx.lineTo(jx+6,jy+jh-10); ctx.stroke();
  var lidG=ctx.createLinearGradient(0,jy-20,0,jy-2);
  lidG.addColorStop(0,'#FFE570'); lidG.addColorStop(.5,'#FFBE20'); lidG.addColorStop(1,'#BB7700');
  ctx.fillStyle=lidG; ctx.beginPath(); ctx.roundRect(jx-5,jy-20,jw+10,22,5); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,.28)';
  ctx.beginPath(); ctx.roundRect(jx+4,jy-17,jw-8,8,3); ctx.fill();
  ctx.fillStyle='#AA7700';
  ctx.beginPath(); ctx.ellipse(cx,jy-23,9,5.5,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#FFD700';
  ctx.beginPath(); ctx.ellipse(cx,jy-24,6,3.5,0,0,Math.PI*2); ctx.fill();
  ctx.font=Math.round(W*.18)+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.fillText('🐣',cx,jy-H*.08);
}
function _updateDailyOverlay(){
  var today=getTodayStars(), scores=get7DayScores();
  var avg=Math.round(scores.reduce(function(a,b){return a+b;},0)/7);
  var dailyLang=evValuesOn() ? (evValuesLang() || 'tr') : 'tr';
  var dailyLabels={
    tr:{earned:'Kazanilan',today:'bugun',average:'Ortalama',days:'7 gun',chart:'Son 7 gun'},
    en:{earned:'Earned',today:'today',average:'Average',days:'7 days',chart:'Last 7 days'},
    de:{earned:'Verdient',today:'heute',average:'Durchschnitt',days:'7 Tage',chart:'Letzte 7 Tage'},
    fr:{earned:'Gagne',today:'aujourd hui',average:'Moyenne',days:'7 jours',chart:'7 derniers jours'},
    ar:{earned:'\u0627\u0644\u0645\u0643\u062A\u0633\u0628',today:'\u0627\u0644\u064A\u0648\u0645',average:'\u0627\u0644\u0645\u062A\u0648\u0633\u0637',days:'7 \u0623\u064A\u0627\u0645',chart:'\u0622\u062E\u0631 7 \u0623\u064A\u0627\u0645'}
  };
  var dl=dailyLabels[dailyLang]||dailyLabels.tr;
  var del=document.getElementById('daily-earned-label'); if(del) del.textContent=dl.earned;
  var dtl=document.getElementById('daily-today-label'); if(dtl) dtl.textContent=dl.today;
  var dal=document.getElementById('daily-average-label'); if(dal) dal.textContent=dl.average;
  var ddl=document.getElementById('daily-days-label'); if(ddl) ddl.textContent=dl.days;
  var dcl=document.getElementById('daily-chart-label'); if(dcl) dcl.textContent=dl.chart;
  var de=document.getElementById('daily-in'); if(de) de.textContent='+'+today;
  var ae=document.getElementById('daily-avg'); if(ae) ae.textContent=avg;
  var dd=document.getElementById('daily-date');
  var dailyLocales={tr:'tr-TR',de:'de-DE',en:'en-US',fr:'fr-FR',ar:'ar-SA'};
  if(dd) dd.textContent=new Date().toLocaleDateString(dailyLocales[dailyLang]||'tr-TR',{weekday:'long',day:'numeric',month:'long'});
  // Mini tasks
  var tl=document.getElementById('daily-tasks-mini');
  if(tl&&typeof DAILY_TASKS!=='undefined'&&typeof getTodayTasks==='function'){
    var done=getTodayTasks();
    var dailyTaskLang=evValuesOn()?evValuesLang():'';
    var dailyTasks=evValuesOn()
      ? (dailyTaskLang==='ar'?getArabicDailyTasks():(dailyTaskLang==='en'?getEnglishDailyTasks():(dailyTaskLang==='de'?getValuesDailyTasks():(dailyTaskLang==='fr'?getFrenchDailyTasks():getTurkishValuesDailyTasks()))))
      : DAILY_TASKS;
    var html='';
    dailyTasks.slice(0,6).forEach(function(t){
      var ok=!!done[t.id];
      html+='<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;">'+
        '<span style="font-size:1rem;">'+t.icon+'</span>'+
        '<span style="font-size:.78rem;color:'+(ok?'rgba(100,255,100,.8)':'rgba(255,255,255,.5)')+';">'+t.name+'</span>'+
        '<span style="margin-left:auto;font-size:.85rem;">'+(ok?'✅':'⭕')+'</span></div>';
    });
    tl.innerHTML=html;
  }
  // 7-day chart
  var chart=document.getElementById('daily-chart');
  if(chart){
    var ctx=chart.getContext('2d'),CW=320,CH=60;
    chart.width=CW; chart.height=CH;
    ctx.clearRect(0,0,CW,CH);
    var max=Math.max(1,Math.max.apply(null,scores));
    var bw=(CW-20)/7;
    scores.forEach(function(s,i){
      var bh=Math.max(4,(s/max)*(CH-20));
      var bx=10+i*bw+bw*.1, by=CH-bh-4;
      var isToday=(i===6);
      var bg=ctx.createLinearGradient(0,by,0,CH-4);
      bg.addColorStop(0,isToday?'rgba(255,215,80,.95)':'rgba(255,180,50,.5)');
      bg.addColorStop(1,isToday?'rgba(200,100,0,.8)':'rgba(150,80,0,.3)');
      ctx.fillStyle=bg;
      ctx.beginPath(); ctx.roundRect(bx,by,bw*.8,bh,3); ctx.fill();
      if(s>0){
        ctx.font='9px Arial'; ctx.fillStyle='rgba(255,255,255,.6)'; ctx.textAlign='center';
        ctx.fillText(s,bx+bw*.4,by-3);
      }
    });
    // Day labels
    var dayLabelMap={
      tr:['Pz','Pt','Sa','Ca','Pe','Cu','Ct'],
      en:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'],
      de:['So','Mo','Di','Mi','Do','Fr','Sa'],
      fr:['Dim','Lun','Mar','Mer','Jeu','Ven','Sam'],
      ar:['\u0623\u062D','\u0627\u062B','\u062B\u0644','\u0623\u0631','\u062E\u0645','\u062C\u0645','\u0633\u0628']
    };
    var days=dayLabelMap[dailyLang]||dayLabelMap.tr;
    var today=new Date().getDay();
    ctx.font='8px Arial'; ctx.fillStyle='rgba(255,255,255,.35)'; ctx.textAlign='center';
    scores.forEach(function(_,i){
      var dayIdx=(today-6+i+7)%7;
      ctx.fillText(days[dayIdx],10+i*bw+bw*.4,CH-1);
    });
  }
}

// ── GÜNLÜK YILDIZ TAKİBİ ──
var _prevTotal=0;
function trackDailyStars(){
  var now=getTotalStars();
  if(now>_prevTotal){
    var gained=now-_prevTotal;
    saveTodayStars(getTodayStars()+gained);
    // Check coin milestone
    var oldCoins=Math.floor(_prevTotal/100);
    var newCoins=Math.floor(now/100);
    if(newCoins>oldCoins){
      _onNewCoin(newCoins);
    }
    _prevTotal=now;
  }
}

function _okiDanceIfExists(){
  try{
    var oc=document.getElementById('oki-canvas');
    if(oc){ oc.classList.add('oki-happy'); setTimeout(function(){oc.classList.remove('oki-happy');},1000); }
    okiBouncing=true; setTimeout(function(){okiBouncing=false;},1200);
    if(typeof showOkiBubble==='function') showOkiBubble('Yeni seviye! 🎉');
  }catch(e){}
}

var _prevCoinStage=0;
function _onNewCoin(coins){
  // Check stage up
  var levels=[0,10,30,60,100,150];
  var stageNames=['Yumurta','Bebek','Kucuk','Genc','Buyuk','Melek'];
  var stageEmojis=['🥚','🐣','🐥','🐦','✨','👼'];
  var curStage=0;
  levels.forEach(function(l,i){ if(coins>=l) curStage=i; });
  if(curStage>_prevCoinStage){
    _prevCoinStage=curStage;
    // Level up!
    showOkiBubble('Buyudum! Artik '+stageNames[curStage]+' '+stageEmojis[curStage]+' oldum! 🎉');
    _okiDanceIfExists();
    // Auto outfit
    updateOkiByCoins();
  }
}



// ── BAŞLATMA ──
window.addEventListener('load',function(){
  _prevTotal=getTotalStars();
  startMiniAnim();
  setInterval(function(){ trackDailyStars(); updateOkiByCoins(); }, 2000);
});

function _dropCoin(x, y){
  if(!gameActive){ return; } // Oyun bitmişse coin uçurma
  var icons = ['🪙','⭐','💰','🪙','⭐','🪙'];
  var n = Math.random()<0.3 ? 3 : 2;
  for(var i=0;i<n;i++){
    (function(delay, ico){
      setTimeout(function(){
        if(!gameActive) return; // gecikme sırasında oyun bittiyse çık
        var el = document.createElement('div');
        el.textContent = ico;
        el.className = '_gf'; // game float — temizlik için
        // Başlangıç: ekranın ÜSTÜNDE rastgele X
        var startX = (x||window.innerWidth/2) + (Math.random()-0.5)*80;
        // Bitiş: ekranın ALTINDAki kavanoz bölgesine
        var jarX = window.innerWidth/2 + (Math.random()-0.5)*60;
        var jarY = window.innerHeight - 55;
        el.style.cssText =
          'position:fixed;'+
          'left:'+startX+'px;'+
          'top:-40px;'+
          'font-size:2rem;'+
          'z-index:9999;'+
          'pointer-events:none;'+
          'text-shadow:0 3px 12px rgba(0,0,0,.6);'+
          'transition:none;';
        evGameLayer().appendChild(el);

        // 1. Adım: üstten ortaya hızlıca düş (0.6sn)
        requestAnimationFrame(function(){
          requestAnimationFrame(function(){
            if(!el.parentNode) return;
            el.style.transition =
              'left 0.6s ease-in, top 0.6s cubic-bezier(.2,0,.8,1), font-size 0.6s ease';
            el.style.top = (window.innerHeight*0.4)+'px';
            el.style.left = startX+'px';
            el.style.fontSize = '2.4rem';
          });
        });

        // 2. Adım: ortadan kavanoza git (0.7sn sonra)
        setTimeout(function(){
          if(!el.parentNode) return;
          el.style.transition =
            'left 0.65s ease-in, top 0.65s cubic-bezier(.4,0,1,1), font-size 0.65s ease-in, opacity 0.65s ease-in';
          el.style.left = jarX+'px';
          el.style.top  = jarY+'px';
          el.style.fontSize = '0.5rem';
          el.style.opacity  = '0';
        }, 700);

        // Temizle + kavanoz güncelle
        setTimeout(function(){
          if(el.parentNode) el.remove();
          trackDailyStars();
        }, 1400);
      }, delay);
    })(i*200, icons[Math.floor(Math.random()*icons.length)]);
  }
}


// ══ PARA YAĞMURU SİSTEMİ ══
var _coinRainTimer = null;
var _coinRainCount = 0;  // bu oturumda düşen para

function startCoinRain(){
  stopCoinRain();
  _coinRainTimer = setInterval(function(){
    if(!gameActive) return;
    _spawnFallingCoin();
  }, 2500); // her 2.5 saniyede bir para
}

function stopCoinRain(){
  if(_coinRainTimer){ clearInterval(_coinRainTimer); _coinRainTimer=null; }
}

function _spawnFallingCoin(){
  if(!gameActive){ return; } // Oyun bitmişse para düşürme
  var icons = ['🪙','🪙','⭐','🪙','💰'];
  var ico = icons[Math.floor(Math.random()*icons.length)];
  var startX = 30 + Math.random()*(window.innerWidth-60);
  var dur = 2.5 + Math.random()*1.5; // düşme süresi

  var el = document.createElement('div');
  el.textContent = ico;
  el.className = '_gf'; // game float — temizlik için
  el.style.cssText =
    'position:fixed;left:'+startX+'px;top:-50px;'+
    'font-size:2rem;z-index:9999;pointer-events:none;'+
    'text-shadow:0 3px 10px rgba(0,0,0,.5);'+
    'transition:top '+dur+'s linear, opacity '+dur+'s ease-in;';
  evGameLayer().appendChild(el);

  requestAnimationFrame(function(){
    requestAnimationFrame(function(){
      if(!el.parentNode) return;
      el.style.top = (window.innerHeight+10)+'px';
      el.style.opacity = '0.15';
    });
  });

  // Para yere değince kavanoza gir
  setTimeout(function(){
    if(!el.parentNode) return; // element zaten temizlendiyse
    // Kavanoza uç animasyonu
    var jarX = window.innerWidth/2;
    var jarY = window.innerHeight - 55;
    el.style.transition = 'left .4s ease-in, top .4s ease-in, font-size .4s, opacity .4s';
    el.style.left = jarX+'px';
    el.style.top  = jarY+'px';
    el.style.fontSize = '0.4rem';
    el.style.opacity = '1';
    setTimeout(function(){
      el.remove();
      // Kavanoza ekle
      _coinRainCount++;
      _updateRainCounter();
      trackDailyStars();
      // Kavanoz titreşimi
      var jh = document.getElementById('jar-gold');
      if(jh){ jh.style.transform='scale(1.2)'; setTimeout(function(){jh.style.transform='scale(1)';},200); }
    }, 420);
  }, dur*1000);
}

function _updateRainCounter(){
  // Oyun ekranında sağ üstte para sayacı göster
  var el = document.getElementById('coin-rain-counter');
  if(!el){
    el = document.createElement('div');
    el.id = 'coin-rain-counter';
    el.style.cssText =
      'position:fixed;top:58px;right:10px;z-index:9998;'+
      'background:rgba(0,0,0,.55);border:1.5px solid rgba(255,215,0,.4);'+
      'border-radius:20px;padding:4px 12px;'+
      'font-family:Fredoka One,Arial;font-size:.9rem;color:#FFD700;'+
      'display:flex;align-items:center;gap:5px;'+
      'transition:transform .15s;';
    document.getElementById('gs').appendChild(el);
  }
  el.textContent = '🫙 '+_coinRainCount+' 🪙';
  el.style.transform='scale(1.2)';
  setTimeout(function(){ el.style.transform='scale(1)'; },200);
}


