function okiWearItem(item){
  var slot={'Başlık':'hat','Sırt':'back','Aksesuar':'acc','Kostüm':'cos','Kıyafet':'cloth'}[item.cat]||'misc';
  // Bath items: önce tamamen soyun
  if(item.special==='shampoo'||item.special==='soap'||item.special==='towel'||item.special==='robe'){
    wearing={};
    saveWearing({});  // localStorage'ı hemen temizle
    showOkiBubble('Soyunuyorum... 😅 Duş zamanı!');
  }
  wearing[slot]=item.id;
  saveWearing(wearing);
  _renderShop();
  _animShopOki();
  var name=playerName||'canım';
  var wearMsgs=[
    'Hm hm hm... '+item.emoji+' nasıl duruyor '+name+'? 🤔',
    'Ayna ayna söyle bana, '+item.emoji+' ile kim en güzel? Ben! 😂',
    item.emoji+' giydim! '+name+' beğendi mi acaba? 💅',
    name+' bak bak bak! '+item.emoji+' yakıştı mı? 🤩',
    'Kilom mu verdi acaba '+item.emoji+' ile? 😂',
    name+'! Bu '+item.name+' tam bana göre değil mi? 😍',
  ];
  showOkiBubble(_shopMsg(SHOP_WEAR_MSGS(item)));
  _okiBounceAnim();
}

function okiRemoveItem(item){
  var slot={'Başlık':'hat','Sırt':'back','Aksesuar':'acc','Kostüm':'cos','Kıyafet':'cloth'}[item.cat]||'misc';
  delete wearing[slot];
  saveWearing(wearing);
  _renderShop();
  _animShopOki();
  showOkiBubble(_shopMsg(SHOP_UNDRESS_MSGS()));
}

function okiUndress(){
  saveWearing({});
  _renderShop();
  _animShopOki();
  showOkiBubble('Tamam tamam! Soyundum! 😂');
}

