var _prevCoinStage=0;
function _checkCoinStageUp(newCoins){
  var levels=[0,10,30,60,100,150];
  var stageNames=['Yumurta','Bebek','Kucuk Oki','Genc Oki','Buyuk Oki','Melek Oki'];
  var stageEmojis=['🥚','🐣','🐥','🐦','✨','👼'];
  var curStage=0;
  levels.forEach(function(l,i){ if(newCoins>=l) curStage=i; });
  if(curStage>_prevCoinStage){
    _prevCoinStage=curStage;
    showOkiBubble('Buyudum! '+stageNames[curStage]+' '+stageEmojis[curStage]+' oldum! 🎉');
    if(typeof _okiDance==='function') _okiDance();
    updateOkiByCoins();
  }
}

// ══ GİRİŞ EKRANI YILDIZLAR ══
function initNsStars(){
  var c=document.getElementById('ns-stars');
  if(!c) return;
  c.width=window.innerWidth; c.height=window.innerHeight;
  var ctx=c.getContext('2d');
  var stars=[];
  for(var i=0;i<180;i++){
    stars.push({
      x:Math.random()*c.width, y:Math.random()*c.height,
      r:.5+Math.random()*2, a:Math.random(), da:.005+Math.random()*.01,
      col:Math.random()<.3?'#FFD700':Math.random()<.5?'#88CCFF':'#ffffff'
    });
  }
  // Shooting stars
  var shoots=[];
  function addShoot(){
    shoots.push({x:Math.random()*c.width,y:0,vx:3+Math.random()*4,vy:2+Math.random()*3,life:1});
    setTimeout(addShoot,1500+Math.random()*2000);
  }
  addShoot();
  
  function draw(){
    if(!document.getElementById('ns')||document.getElementById('ns').style.display==='none') return;
    ctx.clearRect(0,0,c.width,c.height);
    // Stars
    stars.forEach(function(s){
      s.a+=s.da; if(s.a>1||s.a<0) s.da*=-1;
      ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,Math.PI*2);
      ctx.fillStyle=s.col; ctx.globalAlpha=s.a*.9; ctx.fill();
    });
    // Shooting stars
    shoots.forEach(function(s,i){
      ctx.beginPath(); ctx.moveTo(s.x,s.y); ctx.lineTo(s.x-s.vx*8,s.y-s.vy*8);
      ctx.strokeStyle='rgba(255,220,150,'+s.life+')'; ctx.lineWidth=1.5; ctx.stroke();
      s.x+=s.vx; s.y+=s.vy; s.life-=.02;
      if(s.life<0||s.x>c.width) shoots.splice(i,1);
    });
    ctx.globalAlpha=1;
    requestAnimationFrame(draw);
  }
  draw();
}
window.addEventListener('load', function(){ setTimeout(initNsStars, 100); });

// ══ DÜKKAN UZAY YILDIZLARI ══
function initShopStars(){
  var c=document.getElementById('shop-stars-c');
  if(!c) return;
  var ov=document.getElementById('shop-ov');
  if(ov) ov.style.background='linear-gradient(180deg,#000510 0%,#020820 30%,#050d30 60%,#0a0520 100%)';
  c.width=window.innerWidth; c.height=window.innerHeight;
  var ctx=c.getContext('2d');
  var stars=[];
  for(var i=0;i<200;i++){
    stars.push({
      x:Math.random()*c.width, y:Math.random()*c.height,
      r:.3+Math.random()*1.8, a:Math.random(),
      da:.003+Math.random()*.008,
      col:Math.random()<.25?'#FFD700':Math.random()<.4?'#88CCFF':'rgba(255,255,255,'
    });
  }
  var nebulas=[
    {x:.2,y:.3,r:120,col:'rgba(80,40,200,'},
    {x:.8,y:.6,r:100,col:'rgba(40,80,200,'},
    {x:.5,y:.8,r:80, col:'rgba(120,40,160,'},
  ];
  function draw(){
    if(!document.getElementById('shop-ov')||document.getElementById('shop-ov').style.display==='none') return;
    ctx.clearRect(0,0,c.width,c.height);
    // Nebula
    nebulas.forEach(function(n){
      var ng=ctx.createRadialGradient(n.x*c.width,n.y*c.height,0,n.x*c.width,n.y*c.height,n.r);
      ng.addColorStop(0,n.col+'.08)'); ng.addColorStop(1,'transparent');
      ctx.fillStyle=ng; ctx.fillRect(0,0,c.width,c.height);
    });
    // Stars
    stars.forEach(function(s){
      s.a+=s.da; if(s.a>1||s.a<0) s.da*=-1;
      ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,Math.PI*2);
      ctx.fillStyle=s.col.startsWith('rgba')?s.col:s.col+s.a+')';
      ctx.globalAlpha=s.col.startsWith('rgba')?s.a:.9;
      ctx.fill();
    });
    ctx.globalAlpha=1;
    requestAnimationFrame(draw);
  }
  draw();
}

// ══ ANA SAYFA UZAY EFEKTİ ══
var _hmSpaceAnim = null;

function initHmSpace(){
  var c = document.getElementById('hm-space-c');
  if(!c) return;
  if(_hmSpaceAnim){ cancelAnimationFrame(_hmSpaceAnim); _hmSpaceAnim=null; }
  
  c.width = window.innerWidth;
  c.height = window.innerHeight;
  var ctx = c.getContext('2d');
  
  // Yıldızlar
  var stars = [];
  for(var i=0;i<250;i++){
    stars.push({
      x: Math.random()*c.width,
      y: Math.random()*c.height,
      r: 0.3 + Math.random()*2,
      a: Math.random(),
      da: 0.003 + Math.random()*0.01,
      col: Math.random()<0.2?'#FFD700':Math.random()<0.3?'#88CCFF':'#ffffff',
      speed: 0.02 + Math.random()*0.05
    });
  }
  
  // EduVerse yazıları havada yüzüyor
  var eduTexts = [];
  var textPool = ['EduVerse','Edu','Verse','✦','★','✦','EduVerse'];
  for(var j=0;j<18;j++){
    eduTexts.push({
      x: Math.random()*c.width,
      y: Math.random()*c.height,
      vx: (Math.random()-0.5)*0.3,
      vy: -0.2 - Math.random()*0.4,
      alpha: 0.04 + Math.random()*0.12,
      size: 8 + Math.random()*22,
      text: textPool[j%textPool.length],
      col: Math.random()<0.5?'#FFD700':'#88CCFF',
      rot: (Math.random()-0.5)*0.3,
    });
  }
  
  // Kayan yıldızlar
  var shoots = [];
  function addShoot(){
    if(document.getElementById('hm') && document.getElementById('hm').style.display!=='none'){
      shoots.push({
        x: Math.random()*c.width*0.7,
        y: Math.random()*c.height*0.4,
        vx: 4+Math.random()*6,
        vy: 2+Math.random()*4,
        life: 1, trail: 12+Math.random()*18
      });
      setTimeout(addShoot, 1200+Math.random()*2500);
    }
  }
  setTimeout(addShoot, 800);
  
  // Nebula blob'ları
  var nebulas = [
    {x:0.1, y:0.2, r:160, col:'rgba(80,30,180,'},
    {x:0.9, y:0.7, r:140, col:'rgba(30,60,180,'},
    {x:0.5, y:0.5, r:120, col:'rgba(100,20,150,'},
    {x:0.2, y:0.8, r:100, col:'rgba(20,80,160,'},
  ];
  
  function draw(ts){
    var hm = document.getElementById('hm');
    if(!hm || hm.style.display==='none'){
      cancelAnimationFrame(_hmSpaceAnim);
      _hmSpaceAnim=null;
      return;
    }
    ctx.clearRect(0,0,c.width,c.height);
    
    // Nebula
    nebulas.forEach(function(n){
      var g=ctx.createRadialGradient(n.x*c.width,n.y*c.height,0,n.x*c.width,n.y*c.height,n.r);
      g.addColorStop(0,n.col+'0.06)');
      g.addColorStop(1,'transparent');
      ctx.fillStyle=g; ctx.fillRect(0,0,c.width,c.height);
    });
    
    // Yıldızlar
    stars.forEach(function(s){
      s.a += s.da;
      if(s.a>1||s.a<0) s.da*=-1;
      s.y -= s.speed;
      if(s.y < 0) s.y = c.height;
      ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,Math.PI*2);
      ctx.fillStyle = s.col;
      ctx.globalAlpha = s.a*0.9;
      ctx.fill();
    });
    
    // Kayan yıldızlar
    shoots.forEach(function(s,i){
      ctx.strokeStyle='rgba(255,220,150,'+s.life+')';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(s.x,s.y);
      ctx.lineTo(s.x-s.vx*s.trail/4, s.y-s.vy*s.trail/4);
      ctx.stroke();
      s.x+=s.vx; s.y+=s.vy; s.life-=0.025;
      if(s.life<=0) shoots.splice(i,1);
    });
    
    // EduVerse yüzen yazılar
    eduTexts.forEach(function(e){
      e.x += e.vx;
      e.y += e.vy;
      if(e.y < -40) { e.y = c.height+20; e.x = Math.random()*c.width; }
      if(e.x < -80 || e.x > c.width+80){ e.vx *= -1; }
      ctx.save();
      ctx.translate(e.x, e.y);
      ctx.rotate(e.rot);
      ctx.globalAlpha = e.alpha;
      ctx.fillStyle = e.col;
      ctx.font = 'bold '+Math.round(e.size)+'px "Fredoka One", Arial Black';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(e.text, 0, 0);
      ctx.restore();
    });
    
    ctx.globalAlpha = 1;
    _hmSpaceAnim = requestAnimationFrame(draw);
  }
  
  _hmSpaceAnim = requestAnimationFrame(draw);
}

// Resize
window.addEventListener('resize', function(){
  var c=document.getElementById('hm-space-c');
  if(c){ c.width=window.innerWidth; c.height=window.innerHeight; }
});

