var _selectedChar = 'erkek';
var _charSelectedOnEntry = false;
function _normalizeOkiChar(v){
  v = String(v||'erkek').toLowerCase();
  if(v==='verse' || v==='girl' || v==='female') return 'kiz';
  if(v==='edu' || v==='boy' || v==='male') return 'erkek';
  return v==='kiz' ? 'kiz' : 'erkek';
}
var _charState    = 'idle';
var _charImgEl    = null;  // the <img> element
var _charAnim     = null;  // requestAnimationFrame id
var _charStateTimer = null;

function loadSavedChar(){
  try{ _selectedChar = _normalizeOkiChar((typeof _eduGetScoped==='function'?_eduGetScoped('oki_char','erkek'):localStorage.getItem('oki_char'))||'erkek'); }catch(e){ _selectedChar='erkek'; }
}

function selectChar(type, silent){
  type = _normalizeOkiChar(type);
  _selectedChar = type;
  if(silent!==true){
    _charSelectedOnEntry = true;
    try{ if(typeof _eduSetScoped==='function') _eduSetScoped('oki_char', type); else localStorage.setItem('oki_char', type); savePlayerData(); }catch(e){}
  }
  setCharState('idle');
  // Seçim UI
  ['erkek','kiz'].forEach(function(t){
    var el = document.getElementById('char-sel-'+t);
    if(!el) return;
    var sel = t===type;
    el.style.border      = sel ? (t==='erkek'?'2.5px solid #88FF88':'2.5px solid #FF88CC') : '2.5px solid rgba(255,255,255,.15)';
    el.style.background  = sel ? 'rgba(255,255,255,.14)' : 'rgba(255,255,255,.04)';
    el.style.transform   = sel ? 'scale(1.06)' : 'scale(1)';
  });
}

function setCharState(state, durationMs){
  _charState = state;
  var _stage = typeof getCurrentStage==='function' ? getCurrentStage() : null;
  var _stageSet = _stage&&_stage.charSet;
  var _key = _selectedChar==='kiz'
    ? (_stageSet ? (_stageSet==='erkek_agac'?'kiz_agac':'kiz_fidan') : 'kiz')
    : (_stageSet || 'erkek');
  var imgs = _CHARS[_key] || _CHARS[_selectedChar] || _CHARS.erkek;
  var src  = imgs[state] || imgs['idle'];
  // ana ekran
  var el = document.getElementById('char-main-img');
  if(el){ el.src = src; _applyStateAnim(el, state); }
  // oyun içi
  var gel = document.getElementById('char-game-img');
  if(gel){ gel.src = src; }
  // auto-return to idle
  if(_charStateTimer){ clearTimeout(_charStateTimer); _charStateTimer=null; }
  if(state !== 'idle' && state !== 'sleep'){
    _charStateTimer = setTimeout(function(){ setCharState('idle'); }, durationMs||2500);
  }
}

function _applyStateAnim(el, state){
  el.style.animation = 'none';
  el.style.transform = '';
  el.style.filter    = '';
  setTimeout(function(){
    if(state==='idle')  el.style.animation = 'charFloat 3s ease-in-out infinite';
    if(state==='wave')  el.style.animation = 'charWave 0.5s ease-in-out 4, charFloat 3s ease-in-out 2s infinite';
    if(state==='jump')  el.style.animation = 'charJump 0.4s ease-out 3, charFloat 3s ease-in-out 1.2s infinite';
    if(state==='eat')   el.style.animation = 'charBounce 0.5s ease-in-out 3, charFloat 3s ease-in-out 1.5s infinite';
    if(state==='sleep') el.style.animation = 'charSway 2s ease-in-out infinite';
    if(state==='sad')   el.style.animation = 'charSad 1s ease-in-out 2, charFloat 3s ease-in-out 2s infinite';
  }, 10);
}

function okiWave()  { setCharState('wave',  2500); showOkiBubble('Hepinize merhaba! 👋 '); }
function okiEat()   { setCharState('eat',   3000); showOkiBubble(_selectedChar==='kiz'?'Çilek yiyorum! 🍓 Leziz!':'Elma yiyorum! 🍎 Leziz!'); }
function okiSleep() { setCharState('sleep', 0);    showOkiBubble('Uyuyorum... zZz 😴'); setTimeout(function(){setCharState('idle');},5000); }
function okiJump()  { setCharState('jump',  2000); showOkiBubble('Yaay! Zıplıyorum! 🎉'); }
function okiSad()   { setCharState('sad',   3000); showOkiBubble('Üzüldüm... 😢'); }

function _spawnSpark(){
  var wrap=document.querySelector('#char-main-img')?.parentElement;
  if(!wrap) return;
  var sp=document.createElement('div');
  var emojis=['✨','⭐','💫','🌟','✦'];
  sp.textContent=emojis[Math.floor(Math.random()*emojis.length)];
  var angle=Math.random()*Math.PI*2;
  var r=55+Math.random()*20;
  sp.style.cssText='position:absolute;font-size:'+(10+Math.random()*8)+'px;'+
    'left:calc(50% + '+Math.cos(angle)*r+'px);'+
    'top:calc(50% + '+Math.sin(angle)*r+'px);'+
    'transform:translate(-50%,-50%);pointer-events:none;z-index:10;'+
    'animation:charSpark '+(0.8+Math.random()*0.6)+'s ease forwards;';
  wrap.appendChild(sp);
  setTimeout(function(){sp.remove();},1500);
}
// Periyodik spark
setInterval(function(){
  if(!gameActive) _spawnSpark();
},2000);

function charSpeak(){
  var msgs = {
    erkek:['Merhaba! Ben Oki! 🌱','Hadi oynayalım! 🎮','Bugün ne yapacağız? ✨'],
    kiz:  ['Selam! Ben Aylin! 🌸','Seninle olmak çok güzel! 💕','Hadi öğrenelim! 📚'],
  };
  var m = msgs[_selectedChar];
  showOkiBubble(m[Math.floor(Math.random()*m.length)]);
  okiWave();
}

// Otomatik davranışlar
function startCharAutoActions(){
  setInterval(function(){
    if(gameActive || _charState!=='idle') return;
    var r = Math.random();
    if(r<.2)       okiWave();
    else if(r<.35) okiEat();
    else if(r<.45) okiJump();
    else if(r<.5)  okiSleep();
  }, 12000);
}

// okiGameTapped override - oyun içi karaktere tıklayınca


window.addEventListener('load', function(){
  loadSavedChar();
  selectChar(_selectedChar, true);
  startCharAutoActions();
});

