function shopCharClick(){
  var cat = _shopRoomCat==='Tumu'?'Tumu':_shopRoomCat;
  var msgs = (SHOP_CAT_MSGS[_shopRoomChar]||SHOP_CAT_MSGS.edu)[cat] || SHOP_CAT_MSGS.edu.Tumu;
  var idx = _shopMsgIdx[_shopRoomChar] || 0;
  shopBubble(evShopRoomMsg(cat, idx));
  _shopMsgIdx[_shopRoomChar] = (idx+1) % msgs.length;
  var img=document.getElementById('shop-char-img');
  if(img){ img.style.animation='shopBounce .4s ease 3, shopFloat 3s ease-in-out 1.2s infinite';
    setTimeout(function(){img.style.animation='shopFloat 3s ease-in-out infinite';},2500); }
}

function shopSwitchChar(c){
  _shopRoomChar=c;
  var imgs=_CHARS[c==='edu'?'erkek':'kiz'];
  var el=document.getElementById('shop-char-img');
  if(el) el.src=imgs.idle;
  var nm=document.getElementById('shop-char-name');
  if(nm) nm.textContent=c==='edu'?'🌱 Edu':'🌸 Verse';
  ['edu','verse'].forEach(function(t){
    var btn=document.getElementById('shop-btn-'+t);
    if(!btn) return;
    var sel=t===c;
    btn.style.background=sel?'rgba(255,255,255,.12)':'rgba(255,255,255,.04)';
    btn.style.borderColor=sel?(t==='edu'?'rgba(100,255,100,.5)':'rgba(255,100,200,.5)'):'rgba(255,255,255,.1)';
  });
  shopUpdateWearing();
  shopRenderItems();
}

function shopUpdateWearing(){
  // In-memory'den oku — sr_wearing'i YAZMA (overwrite etme)
  var w=_shopRoomWearing[_shopRoomChar]||[];
  var txt=w.map(function(id){
    var it=SHOP_ROOM_ITEMS.find(function(i){return i.id===id;});
    return it?it.emoji:'';
  }).join(' ');
  var el=document.getElementById('shop-wearing-txt');
  if(el) el.textContent=txt||(evShopRoomIsAr()?evShopRoomUi('nothing'):((evValuesOn()&&evValuesLang()==='fr')?'Rien':((evValuesOn()&&evValuesLang()==='en')?'Nothing':((evValuesOn()&&evValuesLang()==='de')?'Nichts':'Yok'))));
  evApplyShopRoomGerman();
  var ce=document.getElementById('shop-coin-count');
  if(ce) ce.textContent=getRealCoins();
}

function shopRenderCats(){
  var el=document.getElementById('shop-cats'); if(!el) return;
  el.innerHTML='';
  SHOP_ROOM_CATS.forEach(function(c){
    var btn=document.createElement('button');
    btn.style.cssText='padding:5px 14px;border-radius:20px;font-size:.75rem;cursor:pointer;backdrop-filter:blur(8px);font-family:Nunito;font-weight:700;border:1.5px solid rgba(100,180,255,'+( c===_shopRoomCat?'.7':'.2')+');background:'+(c===_shopRoomCat?'rgba(30,60,150,.6)':'rgba(10,20,60,.4)')+';color:'+(c===_shopRoomCat?'#88CCFF':'rgba(150,200,255,.6)')+';transition:all .2s;margin:2px;';
    btn.textContent=evShopRoomCatText(c);
    btn.onclick=function(){
      _shopRoomCat=c; shopRenderCats(); shopRenderItems();
      playShopSound(c);
      // Kategoriye göre poz
      var catPoses={Doga:'wave',Kahraman:'jump',Sihirbaz:'wave',Uzay:'jump',Akvaryum:'eat',Sampion:'jump',Tumu:'wave'};
      shopSetPose(catPoses[c]||'wave', 2500);
      var catMsgs=(SHOP_CAT_MSGS[_shopRoomChar]||SHOP_CAT_MSGS.edu)[c]||SHOP_CAT_MSGS.edu.Tumu;
      var idx=_shopMsgIdx[_shopRoomChar]||0;
      showOkiBubble(evShopRoomMsg(c, idx));
      _shopMsgIdx[_shopRoomChar]=(idx+1)%catMsgs.length;
    };
    el.appendChild(btn);
  });
}

function shopRenderItems(){
  var el=document.getElementById('shop-items'); if(!el) return;
  el.innerHTML='';
  var coins=(typeof getRealCoins==='function')?getRealCoins():((typeof getCoins==='function')?getCoins():0);
  var list=_shopRoomCat==='Tumu'?SHOP_ROOM_ITEMS:SHOP_ROOM_ITEMS.filter(function(i){return i.cat===_shopRoomCat;});
  var w=_shopRoomWearing[_shopRoomChar]||[];
  list.forEach(function(item){
    var owned=_shopRoomOwned.indexOf(item.id)>=0;
    var worn=w.indexOf(item.id)>=0;
    var canBuy=coins>=item.price;
    var card=document.createElement('div');
    card.style.cssText='background:rgba(10,20,60,'+(worn?'.7':'.5')+');border:1.5px solid rgba('+(worn?'255,215,0,.5':owned?'100,255,100,.25':'100,180,255,.1')+');border-radius:18px;padding:14px 10px;text-align:center;position:relative;transition:all .2s;backdrop-filter:blur(4px);box-shadow:'+(worn?'0 0 16px rgba(255,215,0,.25)':'none')+';';
    var badge=worn?'<span style="position:absolute;top:6px;right:8px;font-size:.55rem;padding:2px 6px;border-radius:8px;background:rgba(255,215,0,.2);color:#FFD700;font-family:Fredoka One;">&#9989; '+(evShopRoomIsAr()?evShopRoomUi('worn'):((evValuesOn()&&evValuesLang()==='fr')?'Porte':((evValuesOn()&&evValuesLang()==='en')?'Wearing':((evValuesOn()&&evValuesLang()==='de')?'Wird getragen':'Giyili'))))+'</span>':
               owned?'<span style="position:absolute;top:6px;right:8px;font-size:.55rem;padding:2px 6px;border-radius:8px;background:rgba(100,255,100,.15);color:#88FF88;font-family:Fredoka One;">&#10003; '+(evShopRoomIsAr()?evShopRoomUi('owned'):((evValuesOn()&&evValuesLang()==='fr')?'Possede':((evValuesOn()&&evValuesLang()==='en')?'Owned':((evValuesOn()&&evValuesLang()==='de')?'Gekauft':'Sahip'))))+'</span>':'';
    var btnStyle='width:100%;padding:7px;border-radius:11px;font-size:.78rem;cursor:pointer;font-family:Nunito;font-weight:700;transition:all .2s;border:1px solid rgba('+(worn?'255,215,0,.5':owned?'100,255,100,.3':'255,215,0,.3')+');background:rgba('+(worn?'255,215,0,.15':owned?'100,255,100,.1':'255,215,0,.08')+');color:'+(worn?'#FFD700':owned?'#88FF88':'#FFD700')+'+'+((!owned&&!canBuy)?';opacity:.4;cursor:default':'')+'";';
    var btnTxt=evShopRoomIsAr()?(worn?evShopRoomUi('takeOff'):owned?evShopRoomUi('wear'):(item.price+' '+evShopRoomUi('coins'))):((evValuesOn()&&evValuesLang()==='fr')?(worn?'Enlever':owned?'Porter':('Pieces: '+item.price)):((evValuesOn()&&evValuesLang()==='en')?(worn?'Take off':owned?'Wear':('Coins: '+item.price)):((evValuesOn()&&evValuesLang()==='de')?(worn?'Ausziehen':owned?'Anziehen':('?? '+item.price)):(worn?'Cikar':owned?'Giy':('?? '+item.price)))));
    card.innerHTML=badge+
      '<div style="font-size:2.2rem;margin-bottom:6px;">'+item.emoji+'</div>'+
      '<div style="font-family:Fredoka One;font-size:.85rem;color:#E8C8FF;margin-bottom:3px;">'+evShopRoomItemText(item,'name')+'</div>'+
      '<div style="font-size:.62rem;color:rgba(255,255,255,.32);margin-bottom:8px;">'+evShopRoomItemText(item,'desc')+'</div>'+
      '<button style="'+btnStyle+'">'+btnTxt+'</button>';
    card.querySelector('button').addEventListener('click',function(){shopItemAction(item.id);});
    el.appendChild(card);
  });
  shopUpdateWearing();
}

function shopItemAction(id){
  var item=SHOP_ROOM_ITEMS.find(function(i){return i.id===id;}); if(!item) return;
  var coins=(typeof getRealCoins==='function')?getRealCoins():((typeof getCoins==='function')?getCoins():0);
  var owned=_shopRoomOwned.indexOf(id)>=0;
  var w=_shopRoomWearing[_shopRoomChar]||[];
  var worn=w.indexOf(id)>=0;
  if(worn){
    _shopRoomWearing[_shopRoomChar]=w.filter(function(i){return i!==id;});
    saveWearingItems(_shopRoomChar, _shopRoomWearing[_shopRoomChar]);
    shopRoomSave(); shopRenderItems(); shopSetPose('sad', 2000); showOkiBubble(evShopRoomIsAr()?evShopRoomUi('removed'):((evValuesOn()&&evValuesLang()==='fr')?'Enleve. Ca te va ?':((evValuesOn()&&evValuesLang()==='en')?'Removed. How does it look?':((evValuesOn()&&evValuesLang()==='de')?'Ausgezogen. Wie sieht das aus?':'Cikardim! Nasil?'))));
  } else if(owned){
    if(!_shopRoomWearing[_shopRoomChar]) _shopRoomWearing[_shopRoomChar]=[];
    _shopRoomWearing[_shopRoomChar].push(id);
    saveWearingItems(_shopRoomChar, _shopRoomWearing[_shopRoomChar]);
    shopRoomSave(); shopRenderItems(); shopSetPose('wave', 2500); showOkiBubble(evShopRoomIsAr()?(item.emoji+' '+evShopRoomUi('looksGood')):((evValuesOn()&&evValuesLang()==='fr')?(item.emoji+' Ca te va bien !'):((evValuesOn()&&evValuesLang()==='en')?(item.emoji+' Looks great on you!'):(evValuesOn()&&evValuesLang()==='de'?(item.emoji+' Das steht dir gut!'):item.emoji+' cok yakisti!'))));
  } else if(coins>=item.price){
    if(typeof spendCoins==='function') spendCoins(item.price);
    _shopRoomOwned.push(id);
    saveOwnedItems(_shopRoomOwned); // sr_owned'a da kaydet
    if(!_shopRoomWearing[_shopRoomChar]) _shopRoomWearing[_shopRoomChar]=[];
    _shopRoomWearing[_shopRoomChar].push(id);
    saveWearingItems(_shopRoomChar, _shopRoomWearing[_shopRoomChar]); // sr_wearing'e de kaydet
    shopRoomSave(); shopRenderItems(); shopCharClick();
    playShopSound(_shopRoomCat); shopSetPose('jump', 3000); showOkiBubble(evShopRoomIsAr()?(evShopRoomUi('bought')+' '+evShopRoomItemText(item,'name')+'!'):((evValuesOn()&&evValuesLang()==='fr')?('Super ! '+evShopRoomItemText(item,'name')+' !'):((evValuesOn()&&evValuesLang()==='en')?('Yes! I got '+evShopRoomItemText(item,'name')+'!'):(evValuesOn()&&evValuesLang()==='de'?('Ja! '+evShopRoomItemText(item,'name')+' gekauft!'):'Yess! '+item.emoji+' aldim!'))));
  } else {
    shopSetPose('sad', 3000); showOkiBubble(evShopRoomIsAr()?(evShopRoomUi('notEnough')+' '+item.price+'.'):((evValuesOn()&&evValuesLang()==='fr')?('Pas assez de pieces. Il me faut '+item.price+'.'):((evValuesOn()&&evValuesLang()==='en')?('Not enough coins. I need '+item.price+'.'):(evValuesOn()&&evValuesLang()==='de'?('Nicht genug Muenzen. Ich brauche '+item.price+'.'):'Param yetmedi! '+item.price+' lazim!'))));
  }
}

function showShopRoom(){
  var ov=document.getElementById('shop-ov');
  if(!ov) return;
  ov.style.display='block';
  // Karakter her 6 saniyede konuşsun
  if(_shopTalkTimer) clearInterval(_shopTalkTimer);
  _shopTalkTimer = setInterval(function(){
    if(!document.getElementById('shop-ov')||document.getElementById('shop-ov').style.display==='none'){
      clearInterval(_shopTalkTimer); return;
    }
    shopCharClick();
  }, 6000);
  // Init images
  var charKey=_selectedChar==='kiz'?'verse':'edu';
  _shopRoomChar=charKey;
  // localStorage'dan yükle
  // Her iki kaynaktan da en güncel veriyi yükle
  var _savedOwned1 = getOwnedItems(); // sr_owned
  var _savedOwned2 = (_shopRoomOwned||[]); // in-memory (savePlayerData'dan)
  // Daha uzun olanı kullan (daha fazla ürün = daha güncel)
  _shopRoomOwned = _savedOwned1.length >= _savedOwned2.length ? _savedOwned1 : _savedOwned2;
  var _wearLocal = (typeof _eduJsonGetScoped==='function')?_eduJsonGetScoped('sr_wearing',{}):JSON.parse(localStorage.getItem('sr_wearing')||'{}');
  var _wearPlayer = _shopRoomWearing||{};
  // Her karakter için en güncel wearing'i kullan
  ['edu','verse'].forEach(function(c){
    var l=_wearLocal[c]||[], p=_wearPlayer[c]||[];
    _shopRoomWearing[c] = l.length>0 ? l : p;
  });
  var imgs=_CHARS[_selectedChar];
  var si=document.getElementById('shop-char-img');
  var pe=document.getElementById('shop-prev-edu');
  var pv=document.getElementById('shop-prev-verse');
  if(si) si.src=imgs.idle;
  if(pe) pe.src=_CHARS.erkek.idle;
  if(pv) pv.src=_CHARS.kiz.idle;
  shopRenderCats();
  evApplyShopRoomGerman();
  shopRenderItems();
  initShopStars();
  setTimeout(function(){ shopSetPose('wave',2500); shopCharClick(); }, 400);
  shopRenderSplit();
}

function hideShop(){
  var ov=document.getElementById('shop-ov');
  if(ov) ov.style.display='none';
  if(_shopTalkTimer){ clearInterval(_shopTalkTimer); _shopTalkTimer=null; }
  shopStopEffect();
}


// ══ KARAKTER ODASI BÜYÜK EFEKT SAHNESİ ══
var _fxTimer = null;
var _fxRaf = null;
var _fxActive = false;

var FX_CONFIG = {
  Doga:     { icon:'🌿', label:'Doğa Ruhu!',     emojis:['🌿','🍃','🌸','🌺','🌻','🦋'], bg:'rgba(0,80,20,.3)',   glow:'rgba(50,220,80,.5)',  trail:'#44FF88' },
  Kahraman: { icon:'⚔️', label:'Savaşçı Ruhu!',  emojis:['⚔️','🛡️','⚡','💥','🌟','\uD83D\uDD25'], bg:'rgba(80,50,0,.3)',   glow:'rgba(255,180,0,.5)',  trail:'#FFAA00' },
  Sihirbaz: { icon:'🔮', label:'Büyü Zamanı!',   emojis:['✨','💫','🌟','⭐','🔮','🪄'], bg:'rgba(60,0,100,.3)',  glow:'rgba(200,80,255,.5)', trail:'#CC88FF' },
  Uzay:     { icon:'🚀', label:'Galaksiye!',      emojis:['⭐','🌟','💫','🚀','🌙','🪐'], bg:'rgba(0,20,80,.3)',   glow:'rgba(80,160,255,.5)', trail:'#88AAFF' },
  Akvaryum: { icon:'🐠', label:'Akvaryuma Daldık!', emojis:['🐠','🐟','🐡','🐙','🦈','🐚','🫧','🫧'], bg:'rgba(0,30,80,.5)', glow:'rgba(0,150,255,.5)', trail:'#44AAFF' },
  Sampion:  { icon:'🏆', label:'Şampiyon!',       emojis:['🏆','🥇','🎊','🎉','⭐','✨'], bg:'rgba(80,60,0,.3)',   glow:'rgba(255,215,0,.6)',  trail:'#FFD700' },
};

function shopStartEffect(item){
  shopStopEffect();
  _fxActive = true;
  var cfg = FX_CONFIG[item.cat] || FX_CONFIG.Doga;

  // Center icon + label + item name
  var icon = document.getElementById('shop-fx-icon');
  var lbl  = document.getElementById('shop-fx-label');
  var nm   = document.getElementById('shop-fx-name');
  if(icon){
    icon.textContent = item.emoji;
    icon.style.opacity='.2';
    setTimeout(function(){icon.style.opacity='.55';icon.style.fontSize='5rem';
      setTimeout(function(){icon.style.fontSize='4.5rem';},300);},50);
  }
  if(nm)   nm.textContent   = evShopRoomItemText(item,'name');
  var enFxLabels = {Doga:'Nature spirit!',Kahraman:'Hero spirit!',Sihirbaz:'Magic time!',Uzay:'To the galaxy!',Akvaryum:'Art and sea!',Sampion:'Champion!',Tumu:'Select an item!'};
  if(lbl)  lbl.textContent  = evShopRoomIsAr()?(SHOP_ROOM_AR_FX[item.cat]||SHOP_ROOM_AR_FX.Tumu):((evValuesOn()&&evValuesLang()==='en')?(enFxLabels[item.cat]||enFxLabels.Tumu):cfg.label);

  // Stage background
  var stage = document.getElementById('shop-effect-stage');
  if(stage){
    stage.style.background = cfg.bg;
    stage.style.borderColor = cfg.glow.replace('.5',',.4').replace('rgba','rgba');
    stage.style.boxShadow = 'inset 0 0 30px ' + cfg.glow + ', 0 0 20px ' + cfg.glow;
  }

  // Glow rengi karaktere
  var charImg = document.getElementById('shop-char-img');
  if(charImg){
    charImg.style.filter = 'drop-shadow(0 0 18px '+cfg.glow+') drop-shadow(0 4px 12px rgba(0,0,0,.3))';
    charImg.style.animation = 'shopBounce .4s ease 3, shopFloat 3s ease-in-out 1.2s infinite';
    setTimeout(function(){
      if(charImg) charImg.style.animation = 'shopFloat 3s ease-in-out infinite';
    }, 2500);
  }

  // Glow halkası rengi
  var glow = document.getElementById('shop-char-glow');
  if(glow) glow.style.background = 'radial-gradient(circle,'+cfg.glow.replace('.5','.25')+',transparent 70%)';

  // Canvas efekti başlat
  _startFxCanvas(cfg);

  // Emoji yağmuru
  _fxTimer = setInterval(function(){
    if(!_fxActive) return;
    _spawnFxEmoji(cfg.emojis);
  }, 280);
}

function shopStopEffect(){
  _fxActive = false;
  if(_fxTimer){ clearInterval(_fxTimer); _fxTimer=null; }
  if(_fxRaf){ cancelAnimationFrame(_fxRaf); _fxRaf=null; }

  var stage = document.getElementById('shop-effect-stage');
  if(stage){ stage.style.background='rgba(0,0,20,.5)'; stage.style.boxShadow='none'; stage.style.borderColor='rgba(100,180,255,.15)'; }
  var icon = document.getElementById('shop-fx-icon');
  var lbl  = document.getElementById('shop-fx-label');
  if(icon) icon.textContent = '✨';
  if(lbl)  lbl.textContent  = evShopRoomIsAr()?evShopRoomUi('choose'):((evValuesOn()&&evValuesLang()==='en')?'Select an item!':((evValuesOn()&&evValuesLang()==='fr')?'Choisis un article !':((evValuesOn()&&evValuesLang()==='de')?'Waehle ein Produkt!':'Bir urun sec!')));
  var charImg = document.getElementById('shop-char-img');
  if(charImg) charImg.style.filter = 'drop-shadow(0 4px 16px rgba(0,200,100,.4))';
  var glow = document.getElementById('shop-char-glow');
  if(glow) glow.style.background = 'radial-gradient(circle,rgba(100,255,150,.2),transparent 70%)';
  var emDiv = document.getElementById('shop-fx-emojis');
  if(emDiv) emDiv.innerHTML = '';
}

function _startFxCanvas(cfg){
  var canvas = document.getElementById('shop-fx-canvas');
  if(!canvas) return;
  var stage = document.getElementById('shop-effect-stage');
  canvas.width  = stage ? stage.offsetWidth  : 180;
  canvas.height = stage ? stage.offsetHeight : 150;
  var ctx = canvas.getContext('2d');
  var particles = [];
  var W = canvas.width, H = canvas.height;

  // Parçacık sistemi
  for(var i=0;i<18;i++){
    particles.push({
      x: Math.random()*W, y: Math.random()*H,
      vx:(Math.random()-.5)*1.2, vy:-(Math.random()*1.5+.3),
      size: 2+Math.random()*4, life:1, dec:.008+Math.random()*.006,
      col: cfg.trail,
    });
  }

  // Akvaryum için balık pozisyonları
  var fishList = [];
  if(cfg.icon==='🐠'){
    for(var fi=0;fi<6;fi++) fishList.push({
      x:Math.random()*W, y:20+Math.random()*(H-40),
      vx:(Math.random()>.5?1:-1)*(0.4+Math.random()*.6),
      emoji:['🐠','🐟','🐡','🦈'][Math.floor(Math.random()*4)],
      size:12+Math.random()*10, wave:Math.random()*Math.PI*2
    });
  }
  function draw(){
    if(!_fxActive){ ctx.clearRect(0,0,W,H); return; }
    ctx.clearRect(0,0,W,H);

    // Dönen halka
    var t = Date.now()*.001;
    var cx=W/2, cy=H/2, r=Math.min(W,H)*.35;
    for(var j=0;j<8;j++){
      var ang = t*1.2 + j*(Math.PI*2/8);
      var px = cx+Math.cos(ang)*r, py = cy+Math.sin(ang)*r*.7;
      var g = ctx.createRadialGradient(px,py,0,px,py,8);
      g.addColorStop(0, cfg.trail);
      g.addColorStop(1,'transparent');
      ctx.fillStyle=g; ctx.beginPath(); ctx.arc(px,py,8,0,Math.PI*2); ctx.fill();
    }

    // İkinci halka tersi
    for(var j2=0;j2<5;j2++){
      var ang2 = -t*.8 + j2*(Math.PI*2/5);
      var px2=cx+Math.cos(ang2)*r*.55, py2=cy+Math.sin(ang2)*r*.45;
      ctx.fillStyle=cfg.glow.replace('.5','.6');
      ctx.beginPath(); ctx.arc(px2,py2,5,0,Math.PI*2); ctx.fill();
    }

    // Parçacıklar
    particles.forEach(function(p){
      p.x+=p.vx; p.y+=p.vy; p.life-=p.dec;
      if(p.life<=0){ p.x=Math.random()*W; p.y=H+5; p.life=1; p.vy=-(Math.random()*1.5+.3); }
      ctx.globalAlpha = p.life * .7;
      ctx.fillStyle = p.col;
      ctx.beginPath(); ctx.arc(p.x,p.y,p.size*p.life,0,Math.PI*2); ctx.fill();
    });

    // Balık animasyonu (akvaryum)
    if(cfg.icon==='🐠' && fishList.length){
      var t2=Date.now()*.001;
      ctx.font='20px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
      fishList.forEach(function(fish){
        fish.x += fish.vx;
        fish.y += Math.sin(t2*1.2+fish.wave)*0.4;
        if(fish.x > W+20) fish.x=-20;
        if(fish.x < -20) fish.x=W+20;
        ctx.globalAlpha=0.85;
        ctx.save();
        if(fish.vx < 0){ ctx.scale(-1,1); ctx.fillText(fish.emoji,-fish.x,fish.y); }
        else { ctx.fillText(fish.emoji,fish.x,fish.y); }
        ctx.restore();
        // Baloncuklar
        if(Math.random()<.04){
          ctx.globalAlpha=0.4; ctx.strokeStyle='#88CCFF'; ctx.lineWidth=1.2;
          ctx.beginPath(); ctx.arc(fish.x,fish.y-8,2+Math.random()*4,0,Math.PI*2); ctx.stroke();
        }
      });
    }
    ctx.globalAlpha=1;
    _fxRaf = requestAnimationFrame(draw);
  }
  draw();
}

function _spawnFxEmoji(emojis){
  var div = document.getElementById('shop-fx-emojis');
  var stage = document.getElementById('shop-effect-stage');
  if(!div||!stage) return;
  var W=stage.offsetWidth, H=stage.offsetHeight;
  var sp=document.createElement('div');
  var emoji=emojis[Math.floor(Math.random()*emojis.length)];
  var size=14+Math.random()*16;
  var startX=Math.random()*W;
  var endX=startX+(Math.random()-.5)*60;
  sp.textContent=emoji;
  sp.style.cssText='position:absolute;font-size:'+size+'px;'+
    'left:'+startX+'px;top:'+(H+10)+'px;'+
    'pointer-events:none;'+
    'transition:all 1.8s ease-out;opacity:1;';
  div.appendChild(sp);
  requestAnimationFrame(function(){
    requestAnimationFrame(function(){
      sp.style.top=(-size-10)+'px';
      sp.style.left=endX+'px';
      sp.style.opacity='0';
    });
  });
  setTimeout(function(){ if(sp.parentElement) sp.remove(); },2000);
}

// Hook into shopItemAction
var _origShopItemAction2 = shopItemAction;
shopItemAction = function(id){
  _origShopItemAction2(id);
  var item=SHOP_ROOM_ITEMS.find(function(i){return i.id===id;});
  if(item){
    var w=_shopRoomWearing[_shopRoomChar]||[];
    if(w.indexOf(id)>=0) shopStartEffect(item);
    else {
      // Check if any item still worn → show that effect
      var lastWorn = w.length ? SHOP_ROOM_ITEMS.find(function(i){return i.id===w[w.length-1];}) : null;
      if(lastWorn) shopStartEffect(lastWorn);
      else shopStopEffect();
    }
  }
};


// ══ KATEGORİ SESLERİ (Web Audio API - Telifsiz) ══
function playShopSound(cat){
  try{
    var ac = new(window.AudioContext||window.webkitAudioContext)();
    var patterns = {
      Doga:     [[523,.1],[659,.1],[784,.15],[1047,.2]],       // Do Mi Sol Do - huzurlu
      Kahraman: [[220,.05],[277,.05],[330,.05],[440,.15],[330,.05],[440,.2]], // güçlü
      Sihirbaz: [[800,.05],[1000,.05],[900,.05],[1200,.1],[600,.15]], // büyülü tınlama
      Uzay:     [[200,.1],[400,.05],[600,.05],[800,.1],[400,.15]],    // uzay synth
      Akvaryum: [[1046,.08],[1318,.08],[1568,.08],[2093,.12],[1568,.2]], // su damlaları
      Sampion:  [[523,.05],[659,.05],[784,.05],[1047,.05],[1318,.15],[1047,.1]], // zafer
      Tumu:     [[523,.1],[659,.15]],
    };
    var pattern = patterns[cat] || patterns.Tumu;
    var t = ac.currentTime;
    pattern.forEach(function(note, i){
      var o = ac.createOscillator();
      var g = ac.createGain();
      var wave = (cat==='Uzay'||cat==='Sihirbaz') ? 'sine' : (cat==='Kahraman'?'sawtooth':'triangle');
      o.type = wave;
      o.frequency.value = note[0];
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(.12, t+.02);
      g.gain.exponentialRampToValueAtTime(.001, t+note[1]+.1);
      o.connect(g); g.connect(ac.destination);
      var delay = pattern.slice(0,i).reduce(function(s,n){ return s+n[1]; },0);
      o.start(t+delay);
      o.stop(t+delay+note[1]+.15);
    });
  }catch(e){}
}

// Kategori tıklayınca ses çal - hook into renderCats
var _origShopRenderCats = shopRenderCats;
shopRenderCats = function(){
  _origShopRenderCats();
  // Ses zaten btn.onclick içinde çağrılacak
};

// ── KARAKTER POZ DEĞİŞTİRME ──
var _shopPoseTimer = null;

function shopSetPose(pose, durationMs){
  var charKey = _shopRoomChar==='edu' ? 'erkek' : 'kiz';
  var imgs = _CHARS[charKey];
  var src = imgs[pose] || imgs['idle'];
  var img = document.getElementById('shop-char-img');
  if(!img) return;
  img.src = src;
  // Bounce animasyonu
  img.style.animation = 'shopBounce .4s ease, shopFloat 3s ease-in-out 1s infinite';
  // Timer ile idle'a dön
  if(_shopPoseTimer) clearTimeout(_shopPoseTimer);
  _shopPoseTimer = setTimeout(function(){
    var idleSrc = (_CHARS[charKey]||{}).idle;
    if(img && idleSrc) img.src = idleSrc;
    img.style.animation = 'shopFloat 3s ease-in-out infinite';
  }, durationMs || 2500);
}

// ── YENİ SHOP RENDER (Sol/Sağ kolonlar) ──
function shopRenderSplit(){
  var left  = document.getElementById('shop-left');
  var right = document.getElementById('shop-right');
  if(!left||!right) return;
  left.innerHTML=''; right.innerHTML='';

  var coins = (typeof getRealCoins==='function')?getRealCoins():((typeof getCoins==='function')?getCoins():0);
  var list  = _shopRoomCat==='Tumu'?SHOP_ROOM_ITEMS:SHOP_ROOM_ITEMS.filter(function(i){return i.cat===_shopRoomCat;});
  var w     = _shopRoomWearing[_shopRoomChar]||[];

  list.forEach(function(item, idx){
    var owned = _shopRoomOwned.indexOf(item.id)>=0;
    var worn  = w.indexOf(item.id)>=0;
    var canBuy= coins>=item.price;

    var card = document.createElement('div');
    card.style.cssText =
      'background:rgba(10,20,60,'+(worn?'.8':'.5')+');'+
      'border:1.5px solid rgba('+(worn?'255,215,0,.6':owned?'100,255,100,.3':'100,180,255,.12')+');'+
      'border-radius:14px;padding:8px 4px;text-align:center;cursor:pointer;transition:all .2s;'+
      'box-shadow:'+(worn?'0 0 14px rgba(255,215,0,.3)':'none')+';'+
      'position:relative;';

    var badge = worn?
      '<div style="position:absolute;top:3px;right:3px;font-size:.48rem;background:rgba(255,215,0,.2);color:#FFD700;padding:1px 4px;border-radius:5px;">✅</div>':
      owned?'<div style="position:absolute;top:3px;right:3px;font-size:.48rem;background:rgba(100,255,100,.15);color:#88FF88;padding:1px 4px;border-radius:5px;">✓</div>':'';

    var btnTxt = evShopRoomIsAr()?(worn?evShopRoomUi('takeOff'):owned?evShopRoomUi('wear'):(item.price+' '+evShopRoomUi('coins'))):((evValuesOn()&&evValuesLang()==='en')?(worn?'Take off':owned?'Wear':('Coins: '+item.price)):((evValuesOn()&&evValuesLang()==='de')?(worn?'Ausziehen':owned?'Anziehen':('🪙'+item.price)):(worn?'\u00C7\u0131kar':owned?'Giy':('🪙'+item.price))));
    var btnCol = worn?'#FFD700':owned?'#88FF88':canBuy?'#FFD700':'rgba(255,255,255,.3)';

    card.innerHTML = badge +
      '<div style="font-size:1.8rem;margin-bottom:3px;">'+item.emoji+'</div>'+
      '<div style="font-family:Fredoka One;font-size:.6rem;color:#E8C8FF;margin-bottom:4px;line-height:1.2;">'+evShopRoomItemText(item,'name')+'</div>'+ 
      '<button style="width:100%;padding:3px 2px;border-radius:8px;font-size:.6rem;font-weight:700;font-family:Nunito;cursor:pointer;'+
        'border:1px solid rgba(255,215,0,.25);background:rgba(255,215,0,.08);color:'+btnCol+';'+
        ((!owned&&!canBuy)?'opacity:.4;':'')+'">'+btnTxt+'</button>';

    card.querySelector('button').addEventListener('click', function(){ shopItemAction(item.id); });

    // Sol/Sağ dağıtım
    if(idx%2===0) left.appendChild(card);
    else right.appendChild(card);
  });

  shopUpdateWearing();
}

// Override shopRenderItems to use split render
shopRenderItems = shopRenderSplit;

// ══ GERÇEK PARA SİSTEMİ ══
function getTotalSpent(){ return parseInt((typeof _eduGetScoped==='function'?_eduGetScoped('sr_spent','0'):localStorage.getItem('sr_spent'))||'0'); }
function getRealCoins(){ return Math.max(0, getTotalStars() - getTotalSpent()); }

function spendCoins(amount){
  var current = getRealCoins();
  if(current < amount) return false;
  var spent = getTotalSpent() + amount;
  if(typeof _eduSetScoped==='function') _eduSetScoped('sr_spent', spent); else localStorage.setItem('sr_spent', spent);
  return true;
}

// Satın alınan ürünler - tek liste, her yerden erişilebilir
function getOwnedItems(){ 
  return (typeof _eduJsonGetScoped==='function')?_eduJsonGetScoped('sr_owned',[]):JSON.parse(localStorage.getItem('sr_owned')||'[]'); 
}
function saveOwnedItems(arr){ 
  if(typeof _eduJsonSetScoped==='function') _eduJsonSetScoped('sr_owned', arr); else localStorage.setItem('sr_owned', JSON.stringify(arr)); 
}
function getWearingItems(char){ 
  var all=(typeof _eduJsonGetScoped==='function')?_eduJsonGetScoped('sr_wearing',{}):JSON.parse(localStorage.getItem('sr_wearing')||'{}');
  return all[char]||[];
}
function saveWearingItems(char, arr){
  var all=(typeof _eduJsonGetScoped==='function')?_eduJsonGetScoped('sr_wearing',{}):JSON.parse(localStorage.getItem('sr_wearing')||'{}');
  all[char]=arr;
  if(typeof _eduJsonSetScoped==='function') _eduJsonSetScoped('sr_wearing', all); else localStorage.setItem('sr_wearing', JSON.stringify(all));
}

