// EduVerse BÜYÜME SİSTEMİ
// 3 Aşama: Tohum → Fidan → Ağaç
// ══════════════════════════════════════════════════════

var GROWTH_STAGES = [
  {
    id: 'tohum',
    name: 'Seed Oki',
    emoji: String.fromCodePoint(0x1F331),
    minStars: 0,
    maxStars: 15000,
    scale: 0.72,
    label: 'Küçük ama güçlü!',
    color: '#88FF88',
    unlockMsg: 'Hoş geldin! Büyüme zamanı! 🌱',
  },
  {
    id: 'fidan',
    charSet: 'erkek_fidan',
    name: 'Sprout Oki',
    emoji: String.fromCodePoint(0x1F33F),
    minStars: 15000,
    maxStars: 50000,
    scale: 0.90,
    label: 'Büyüyorum!',
    color: '#44FF99',
    unlockMsg: 'Fidan oldum! 🌿 Çok büyüdüm!',
  },
  {
    id: 'agac',
    charSet: 'erkek_agac',
    name: 'Tree Oki',
    emoji: String.fromCodePoint(0x1F333),
    minStars: 50000,
    maxStars: 99999999,
    scale: 1.10,
    label: 'Tam güç!',
    color: '#FFD700',
    unlockMsg: 'AĞAÇ OLDUM! 🌳 Artık hiçbir şey beni durduramaz!',
  },
];

function getCurrentStage(){
  var stars = getTotalStars();
  var stage = GROWTH_STAGES[0];
  GROWTH_STAGES.forEach(function(s){
    if(stars >= s.minStars) stage = s;
  });
  return stage;
}

function getStageProgress(){
  var stars = getTotalStars();
  var stage = getCurrentStage();
  if(stage.id === 'agac') return 100;
  var range = stage.maxStars - stage.minStars;
  var done  = stars - stage.minStars;
  return Math.min(100, Math.floor(done/range*100));
}

var _lastStageId = null;

function checkGrowthUp(){
  var stage = getCurrentStage();
  if(_lastStageId && _lastStageId !== stage.id){
    // BÜYÜME KUTLAMASI!
    triggerGrowthCelebration(stage);
  }
  _lastStageId = stage.id;
  updateGrowthUI();
}

function updateGrowthUI(){
  var stage = getCurrentStage();
  var progress = getStageProgress();
  var stars = getTotalStars();
  // Aşamaya göre karakter resmi güncelle
  var _gCharSet = stage.charSet;
  var _gKey = _selectedChar==='kiz'
    ? (_gCharSet ? (_gCharSet==='erkek_agac'?'kiz_agac':'kiz_fidan') : 'kiz')
    : (_gCharSet || 'erkek');
  var _gImgs = _CHARS[_gKey] || _CHARS[_selectedChar] || _CHARS.erkek;
  var _gMi = document.getElementById('char-main-img');
  var _gGi = document.getElementById('char-game-img');
  if(_gMi && _gMi.src !== (_gImgs.idle||'')) _gMi.src = _gImgs.idle||'';
  if(_gGi && _gGi.src !== (_gImgs.idle||'')) _gGi.src = _gImgs.idle||'';

  // Ana ekran karakter boyutu
  var img = document.getElementById('char-main-img');
  if(img){
    img.style.width  = Math.round(120 * stage.scale) + 'px';
    img.style.height = Math.round(140 * stage.scale) + 'px';
  }

  // Büyüme bar güncelle
  var bar = document.getElementById('growth-bar-fill');
  if(bar) bar.style.width = progress + '%';
  var barLabel = document.getElementById('growth-bar-label');
  if(barLabel){
    var next = GROWTH_STAGES.find(function(s){ return s.minStars > stars; });
    if(typeof evValuesOn==='function' && evValuesOn() && typeof evValuesLang==='function' && evValuesLang()==='ar'){
      barLabel.textContent = next ? ('بذرة أوكي: بقي '+(next.minStars - stars)+' نجمة') : 'المستوى الأقصى!';
    } else if(typeof evValuesOn==='function' && evValuesOn() && typeof evValuesLang==='function' && evValuesLang()==='en'){
      barLabel.textContent = next ? (evEnglishOkiStageName(stage)+' -> '+(next.minStars - stars)+' stars left') : 'Maximum level!';
    } else if(!(typeof evValuesOn==='function' && evValuesOn())){
      var trStageNames={tohum:'Tohum Oki',fidan:'Fidan Oki',agac:'A\u011fa\u00e7 Oki',cicek:'\u00c7i\u00e7ek Oki',yildiz:'Y\u0131ld\u0131z Oki'};
      barLabel.textContent = next ? ((trStageNames[stage.id]||'Oki')+' -> '+(next.minStars - stars)+' y\u0131ld\u0131z kald\u0131') : 'Maksimum seviye!';
    } else {
      barLabel.textContent = next ? (stage.name+' -> '+(next.minStars - stars)+' stars left') : 'Maximum level!';
    }
  }

  // Aşama emojisi
  var stageEl = document.getElementById('growth-stage-emoji');
  if(stageEl) stageEl.textContent = stage.emoji;

  // Oki name badge
  var nm = document.getElementById('oki-name');
  if(nm && nm.textContent){
    nm.style.color = stage.color;
  }
}

function triggerGrowthCelebration(stage){
  // Büyük konfeti
  startCoinRain && startCoinRain();
  setTimeout(function(){ stopCoinRain && stopCoinRain(); }, 4000);

  // Karakter zıplar
  setCharState('jump');
  setTimeout(function(){ setCharState('wave'); }, 2500);
  setTimeout(function(){ setCharState('idle'); }, 5000);

  // Konuşma
  showOkiBubble(stage.unlockMsg);

  // Büyüme overlay göster
  showGrowthOverlay(stage);
}

function showGrowthOverlay(stage){
  var ov = document.getElementById('growth-ov');
  if(!ov) return;
  var icon = document.getElementById('growth-ov-icon');
  var title = document.getElementById('growth-ov-title');
  var sub = document.getElementById('growth-ov-sub');
  var l='tr'; try{ if(typeof evValuesOn==='function'&&evValuesOn()&&typeof evValuesLang==='function') l=evValuesLang()||'tr'; }catch(e){}
  var sid=(stage&&stage.id)||'fidan';
  var M={
    tr:{fidan:['Fidan oldun!','Artık büyüdün!'],agac:['Ağaç oldun!','Tam güce ulaştın!']},
    de:{fidan:['Du bist ein Setzling!','Du bist gewachsen!'],agac:['Du bist ein Baum!','Du hast volle Kraft erreicht!']},
    en:{fidan:['You became a sapling!','You have grown!'],agac:['You became a tree!','You reached full strength!']},
    fr:{fidan:['Tu es devenu une pousse !','Tu as grandi !'],agac:['Tu es devenu un arbre !','Tu as atteint ta pleine force !']},
    ar:{fidan:['أصبحت شتلة!','لقد كبرت!'],agac:['أصبحت شجرة!','وصلت إلى قوتك الكاملة!']}
  };
  var mm=(M[l]&&M[l][sid])?M[l][sid]:(M.tr[sid]||M.tr.fidan);
  if(icon)  icon.textContent  = stage.emoji;
  if(title){ title.textContent = mm[0]; title.setAttribute('translate','no'); }
  if(sub){ sub.textContent = mm[1]; sub.setAttribute('translate','no'); }
  ov.style.display = 'flex';
  setTimeout(function(){evV47FFullScreenFireCleanup();},40);
  setTimeout(function(){ ov.style.display='none'; }, 6000);
}

// Her 5 saniyede büyüme kontrol
setInterval(checkGrowthUp, 5000);
window.addEventListener('load', function(){
  _lastStageId = getCurrentStage().id;
  setTimeout(updateGrowthUI, 800);
});

function updateCharImages(){
  loadSavedChar();
  var imgs = _CHARS[_selectedChar] || _CHARS.erkek;
  var mi = document.getElementById('char-main-img');
  var gi = document.getElementById('char-game-img');
  var nn = document.getElementById('oki-name');
  if(mi) mi.src = imgs.idle;
  if(gi) gi.src = imgs.idle;
  if(nn) nn.textContent = _selectedChar==='kiz' ? '🌸 Verse' : '🌱 Edu';
}

