    var valuesMode=false;
    try{ valuesMode=!!(typeof evValuesOn==='function' && evValuesOn()); }catch(e0){}
    if(!valuesMode){
      try{ valuesMode=(localStorage.getItem('eduverse_values_mode')==='1'); }catch(e1){}
    }
    var l='tr';
    if(valuesMode){
      l=(typeof evValuesLang==='function' && evValuesLang()) || localStorage.getItem('ev_values_lang') || 'tr';
    }else{
      l=(typeof _duaLang!=='undefined' && _duaLang) || localStorage.getItem('dua_lang') || 'tr';
    }
    l=String(l||'tr').toLowerCase();
    if(l.indexOf('ar')===0) return 'ar';
    if(l.indexOf('fr')===0) return 'fr';
    if(l.indexOf('de')===0) return 'de';
