  var ci = document.getElementById('gbig-char');
  if(ci) ci.src = imgs.idle||imgs[Object.keys(imgs)[0]];

  // Karakter konuşuyor
  var msg = _selectedChar==='kiz' ? cfg.msg_verse : cfg.msg_edu;
  document.getElementById('gbig-bubble').textContent = msg;

  // Konfeti
  var conf = document.getElementById('gbig-conf');
