    try{ if(!l && typeof window.eduverseValuesLang==='function') l=window.eduverseValuesLang(); }catch(e2){}
    try{ if(!l) l=localStorage.getItem('ev_values_lang')||localStorage.getItem('edu_values_lang')||localStorage.getItem('edu_lang')||localStorage.getItem('lang')||''; }catch(e3){}
    return v48nNorm(l||'tr');
