  function v48pTheme(){ var t='ocean'; try{ t=localStorage.getItem('v48p_ball_theme')||'ocean'; }catch(e){} if(v48pThemes.indexOf(t)<0) t='ocean'; return t; }
  function v48pThemeName(t){ var l=v48pLang(); return (v48pThemeNames[l]&&v48pThemeNames[l][t])||(v48pThemeNames.tr[t]||t); }
  function v48pNextTheme(){ var t=v48pTheme(); var i=v48pThemes.indexOf(t); if(i<0) i=0; t=v48pThemes[(i+1)%v48pThemes.length]; try{ localStorage.setItem('v48p_ball_theme',t); }catch(e){} v48pSound('theme'); v48pApplyTheme(); }
  function v48pApplyTheme(){
    var ov=document.getElementById('v48p-arena'); var t=v48pTheme();
    if(ov){ ov.className='v48p-theme-'+t; }
    var btn=document.getElementById('v48p-theme-btn'); if(btn){ btn.textContent='🎨 '+v48pUi('theme')+': '+v48pThemeName(t); }
    var sb=document.getElementById('v48p-sound-btn'); if(sb){ sb.textContent=(v48pSoundOn?'🔊 ':'🔇 ')+(v48pSoundOn?v48pUi('soundOn'):v48pUi('soundOff')); }
  }
  function v48pToggleSound(){ v48pSoundOn=!v48pSoundOn; try{ localStorage.setItem('v48p_sound_off',v48pSoundOn?'0':'1'); }catch(e){} v48pApplyTheme(); if(v48pSoundOn) v48pSound('theme'); }
  function v48pAudio(){
    if(!v48pSoundOn) return null;
    try{ if(!v48pAudioCtx){ var AC=window.AudioContext||window.webkitAudioContext; if(AC) v48pAudioCtx=new AC(); } if(v48pAudioCtx&&v48pAudioCtx.state==='suspended') v48pAudioCtx.resume(); }catch(e){}
    return v48pAudioCtx;
  }
  function v48pTone(freq,dur,type,gain,delay){
    var ctx=v48pAudio(); if(!ctx) return;
    try{ var osc=ctx.createOscillator(); var g=ctx.createGain(); osc.type=type||'sine'; osc.frequency.value=freq; g.gain.setValueAtTime(0.0001,ctx.currentTime+(delay||0)); g.gain.exponentialRampToValueAtTime(gain||0.035,ctx.currentTime+(delay||0)+0.012); g.gain.exponentialRampToValueAtTime(0.0001,ctx.currentTime+(delay||0)+dur); osc.connect(g); g.connect(ctx.destination); osc.start(ctx.currentTime+(delay||0)); osc.stop(ctx.currentTime+(delay||0)+dur+0.02); }catch(e){}
  }
  function v48pSound(kind){
    if(kind==='click'){ v48pTone(420,0.06,'triangle',0.022,0); return; }
    if(kind==='correct'){ v48pTone(620,0.08,'sine',0.035,0); v48pTone(880,0.12,'sine',0.035,0.07); return; }
    if(kind==='wrong'){ v48pTone(170,0.16,'sawtooth',0.020,0); return; }
    if(kind==='gift'){ v48pTone(740,0.08,'sine',0.035,0); v48pTone(980,0.10,'sine',0.030,0.06); return; }
    if(kind==='theme'){ v48pTone(520,0.06,'triangle',0.025,0); v48pTone(720,0.08,'triangle',0.022,0.055); return; }
    if(kind==='win'){ v48pTone(520,0.10,'sine',0.035,0); v48pTone(660,0.10,'sine',0.035,0.08); v48pTone(820,0.12,'sine',0.040,0.16); return; }
  }
  function v48pBurst(btn,good){
    var box=document.getElementById('v48p-box'); if(!box) return;
    var r=btn?btn.getBoundingClientRect():box.getBoundingClientRect(); var br=box.getBoundingClientRect(); var cx=r.left-br.left+r.width/2, cy=r.top-br.top+r.height/2; var i,sp,ang,dist;
    for(i=0;i<(good?10:4);i++){ sp=document.createElement('span'); sp.className='v48p-spark '+(good?'good':'bad'); sp.textContent=good?'✦':'•'; ang=(Math.PI*2*i)/(good?10:4); dist=good?(28+Math.random()*24):(16+Math.random()*10); sp.style.left=cx+'px'; sp.style.top=cy+'px'; sp.style.setProperty('--x',Math.cos(ang)*dist+'px'); sp.style.setProperty('--y',Math.sin(ang)*dist+'px'); box.appendChild(sp); (function(x){ setTimeout(function(){ try{x.remove();}catch(e){} },680); })(sp); }
  }
  function v48pWinRain(){
    var box=document.getElementById('v48p-box'); if(!box) return;
    var i,sp;
    for(i=0;i<28;i++){ sp=document.createElement('span'); sp.className='v48p-win-star'; sp.textContent=(i%3===0?'⭐':(i%3===1?'✨':'🎉')); sp.style.left=(8+Math.random()*84)+'%'; sp.style.animationDelay=(Math.random()*0.7)+'s'; box.appendChild(sp); (function(x){ setTimeout(function(){ try{x.remove();}catch(e){} },1700); })(sp); }
  }

