      +'@media(max-width:560px){#v48p-box{width:98vw;max-height:98dvh;padding:10px 9px 13px}#v48p-head{justify-content:center;text-align:center}.v48p-chip{font-size:10px;padding:4px 7px}#v48p-tools{margin:5px 0}.v48p-tool{font-size:11px;padding:7px 9px}#v48p-grid{grid-template-columns:repeat(5,clamp(47px,17.5vw,67px));gap:5px}.v48p-ball{width:clamp(47px,17.5vw,67px);height:clamp(47px,17.5vw,67px);font-size:clamp(7.3px,2.35vw,10.2px);padding:2px;box-shadow:inset 0 -6px 12px rgba(0,0,0,.16),0 5px 13px rgba(0,0,0,.22)}}@media(max-height:640px){#v48p-title{font-size:16px}#v48p-q{font-size:13px;padding:7px;margin:5px 0 7px}.v48p-chip{padding:4px 7px;font-size:10px}#v48p-feedback{min-height:20px;margin:5px 0}#v48p-grid{grid-template-columns:repeat(5,clamp(40px,13.2vh,82px));gap:4px}.v48p-ball{width:clamp(40px,13.2vh,82px);height:clamp(40px,13.2vh,82px);font-size:clamp(7px,1.9vh,11px)}}';
