(function(){
  if(window.__v48r2ExistingRoomMusicFix) return;
  window.__v48r2ExistingRoomMusicFix=true;

  function showAdaMusic(){
    try{
      var m=document.getElementById('ada-muzik');
      if(m){
        m.style.display='flex';
        m.style.zIndex='1000005';
        m.style.position='fixed';
      }
      var layers=document.getElementById('ada-layers');
      if(layers){ layers.style.zIndex='1000006'; }
    }catch(e){}
  }
  function hideTinyMusicButtons(){
    try{
      var b=document.getElementById('v48p-music-btn'); if(b) b.remove();
      b=document.getElementById('v48q-music'); if(b) b.remove();
    }catch(e){}
  }
  function activateRoomMusic(roomId){
    showAdaMusic();
    hideTinyMusicButtons();
    try{
      if(roomId==='bilgitoplari') window._adaIdx=9;
      if(roomId==='hikayestudio') window._adaIdx=10;
      if(typeof window._adaMarkActive==='function') window._adaMarkActive(window._adaIdx||0);
    }catch(e){}
    setTimeout(showAdaMusic,120);
    setTimeout(showAdaMusic,520);
  }

  function wrapSpecialRooms(){
    if(typeof window.openBilgiToplariArena==='function' && !window.openBilgiToplariArena.__v48r2MusicWrapped){
      var oldTop=window.openBilgiToplariArena;
      window.openBilgiToplariArena=function(){
        var r=oldTop.apply(this,arguments);
        activateRoomMusic('bilgitoplari');
        return r;
      };
      window.openBilgiToplariArena.__v48r2MusicWrapped=true;
    }
    if(typeof window.openHikayeStudyosu==='function' && !window.openHikayeStudyosu.__v48r2MusicWrapped){
      var oldStory=window.openHikayeStudyosu;
      window.openHikayeStudyosu=function(){
        var r=oldStory.apply(this,arguments);
        activateRoomMusic('hikayestudio');
        return r;
      };
      window.openHikayeStudyosu.__v48r2MusicWrapped=true;
    }
  }

  function boot(){
    hideTinyMusicButtons();
    wrapSpecialRooms();
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot); else boot();
  setTimeout(boot,500);
  setTimeout(boot,1600);
})();
