/* V48S3_VALUES_OLD_QA_HARD_BLOCK_START
   Purpose: keep the V48J/V48O dynamic visual Values gate as the primary entry path
   and prevent the old visible Values question-answer door/card system from reappearing.
   Safe scope: runtime guard only; no IDs, onclick handlers, GA tag, libraries, or room logic changed.
   No document-wide observer; no let/const. */
(function(){
  if(window.__v48s3ValuesOldQAHardBlock) return;
  window.__v48s3ValuesOldQAHardBlock=true;

  var V48S3_VALUES_IDS={
    ders:1,oyuncak:1,cevre:1,caliskan:1,sanat:1,mutfak:1,aile:1,ada:1,sifa:1,ilkbahar:1,
    odulodasi:1,nefes:1,para:1,arapca:1,gizli:1,english:1,deutsch:1,francais:1,okyanus:1,
    atlas:1,muzik:1,boyama:1,kumanda:1,puzzle:1,lazer:1,bilgisayar:1,hayvanat:1,refleks:1,
    sinema:1,bilgitoplari:1,hikayestudio:1,oki3dbahce:1
  };
  var V48S3_EXCLUDE_IDS={
    kucukmelekler:1,ibadet:1,dua:1,shop:1,dukkan:1,dukkkan:1,wunderhaus:1
  };

  function v48s3Id(room){
    try{ return String((room&&room.id)||'').toLowerCase(); }catch(e){ return ''; }
  }
  function v48s3ValuesMode(){
    try{ return !!((typeof evValuesOn==='function' && evValuesOn()) || localStorage.getItem('eduverse_values_mode')==='1'); }catch(e){ return false; }
  }
  function v48s3IsValuesRoom(room){
    var id=v48s3Id(room);
    if(!id || V48S3_EXCLUDE_IDS[id]) return false;
    if(V48S3_VALUES_IDS[id]) return true;
    try{ if(window.evV48JGateRooms && window.evV48JGateRooms[id]) return true; }catch(e0){}
    try{ if(v48s3ValuesMode() && room && room.type!=='dua' && room.type!=='islamic') return true; }catch(e1){}
    return false;
  }
  function v48s3ResetOldQuestionOverlay(){
    try{ _soruState={active:false,room:null,q:null,answered:false,answerBalloonPending:false,answerBalloonSpawned:false,onEnter:null}; }catch(e0){}
    try{
      var ov=document.getElementById('ov-soru2');
      if(ov){ ov.classList.remove('show'); ov.style.display='none'; ov.setAttribute('aria-hidden','true'); }
    }catch(e1){}
  }

  var v48s3OldShow=(typeof showRoomSoru==='function')?showRoomSoru:(window.showRoomSoru||null);
  if(v48s3OldShow && !v48s3OldShow.__v48s3ValuesOldQABlocked){
    showRoomSoru=function(room,onEnter){
      if(v48s3IsValuesRoom(room)){
        v48s3ResetOldQuestionOverlay();
        if(typeof onEnter==='function') onEnter();
        return;
      }
      return v48s3OldShow.apply(this,arguments);
    };
    showRoomSoru.__v48s3ValuesOldQABlocked=true;
    try{ window.showRoomSoru=showRoomSoru; }catch(e2){}
  }

  window.evV48S3ValuesOldQABlocked=function(room){ return v48s3IsValuesRoom(room); };
})();
/* V48S3_VALUES_OLD_QA_HARD_BLOCK_END */

