  var v48s4State={level:1,selected:'seed',grid:{},camera:0,done:false,log:'',celebrate:0};

  function v48s4WorldIndex(n){ return Math.floor((n-1)/5)%8; }
  function v48s4WorldName(n){ var l=v48s4Lang(); var arr=v48s4Worlds[l]||v48s4Worlds.tr; return arr[v48s4WorldIndex(n)]||arr[0]; }
  function v48s4Pattern(n){ var l=v48s4Lang(); var a=v48s4Patterns[l]||v48s4Patterns.tr; return a[(n-1)%a.length]||a[0]; }
  function v48s4Mission(){
    var n=v48s4State.level||1, p=v48s4Pattern(n), need=[], i;
    for(i=0;i<p.need.length;i++) need.push(p.need[i]);
    if(n>12 && n%3===0 && need.indexOf('sensor')<0) need.push('sensor');
    if(n>18 && n%4===0 && need.indexOf('battery')<0) need.push('battery');
    if(n>30 && n%5===0 && need.indexOf('wind')<0) need.push('wind');
    while(need.length>5) need.pop();
    return {level:n,world:v48s4WorldName(n),worldIndex:v48s4WorldIndex(n),title:String(p.title).replace('{world}',v48s4WorldName(n)),goal:p.goal,need:need,tier:Math.floor((n-1)/5)+1};
  }
  function v48s4TileCount(){
    var n=v48s4State.level||1;
    if(n<6) return 8;
    if(n<11) return 10;
    if(n<16) return 12;
    if(n<21) return 14;
    return 16;
  }
  function v48s4Has(a,x){ var i; for(i=0;i<a.length;i++){ if(a[i]===x) return true; } return false; }
  function v48s4ModuleList(m){
    var out=[], i, k;
    for(i=0;i<m.need.length;i++){ if(!v48s4Has(out,m.need[i])) out.push(m.need[i]); }
    for(i=0;i<v48s4Modules.length&&out.length<6;i++){
      k=v48s4Modules[(i+m.level+m.worldIndex)%v48s4Modules.length];
      if(!v48s4Has(out,k)) out.push(k);
    }
    return out;
  }
  function v48s4GridArray(){ var arr=[], k; for(k in v48s4State.grid){ if(v48s4State.grid.hasOwnProperty(k)) arr.push(v48s4State.grid[k]); } return arr; }
  function v48s4Counts(){
    var arr=v48s4GridArray(), c={light:0,water:0,energy:0,growth:0}, i, k;
    for(i=0;i<arr.length;i++){
      k=arr[i];
      if(k==='sun'||k==='lamp'||k==='shade') c.light++;
      if(k==='water') c.water++;
      if(k==='energy'||k==='wind'||k==='battery'||k==='sensor') c.energy++;
      if(k==='seed'||k==='bee'||k==='compost'||k==='bridge') c.growth++;
    }
    c.growth=Math.min(100,Math.round((arr.length/Math.max(1,v48s4Mission().need.length))*72)+(v48s4State.done?28:0));
    return c;
  }
  function v48s4PlacedHas(k){
    var g=v48s4State.grid, x;
    for(x in g){ if(g.hasOwnProperty(x)&&g[x]===k) return true; }
    return false;
  }
  function v48s4NeedHtml(m){
    var s='', i, k;
    for(i=0;i<m.need.length;i++){
      k=m.need[i];
      s+='<span class="v48s4-need '+(v48s4PlacedHas(k)?'ok':'')+'">'+v48s4Html(v48s4ModData[k].ico)+' '+v48s4Html(v48s4ModName(k))+'</span>';
    }
    return s;
  }
  function v48s4MapHtml(m){
    var arr=v48s4Worlds[v48s4Lang()]||v48s4Worlds.tr, i, cls, html='';
    for(i=0;i<arr.length;i++){
      cls=(i<m.worldIndex?'done':(i===m.worldIndex?'now':'future'));
      html+='<span class="v48s4-node '+cls+'"><b>'+(i+1)+'</b><em>'+v48s4Html(arr[i])+'</em></span>';
    }
    return html;
  }
  function v48s4BoardHtml(m){
    var n=v48s4TileCount(), i, k, ico, cls, html='';
    for(i=0;i<n;i++){
      k=v48s4State.grid['p'+i]||''; ico=k?(v48s4ModData[k]&&v48s4ModData[k].ico)||'✨':'';
      cls=k?' filled kind-'+v48s4Html((v48s4ModData[k]&&v48s4ModData[k].kind)||'growth'):'';
      if(v48s4State.done) cls+=' complete';
      html+='<button class="v48s4-tile'+cls+'" data-pos="p'+i+'" type="button" aria-label="tile '+i+'">'+(k?'<span class="v48s4-cube-icon">'+v48s4Html(ico)+'</span><i>'+v48s4Html(v48s4ModName(k))+'</i>':'<small></small>')+'</button>';
    }
    return html;
  }
  function v48s4ModsHtml(m){
    var mods=v48s4ModuleList(m), i, k, html='';
    for(i=0;i<mods.length;i++){
      k=mods[i];
      html+='<button class="v48s4-mod '+(v48s4State.selected===k?'active':'')+'" data-mod="'+v48s4Html(k)+'" type="button"><span>'+v48s4Html(v48s4ModData[k].ico)+'</span><b>'+v48s4Html(v48s4ModName(k))+'</b></button>';
    }
    return html;
  }
  function v48s4PanelClass(m){ return 'world'+String((m.worldIndex||0)+1)+' cam'+String(v48s4State.camera||0)+(v48s4State.done?' solved':''); }

