      +'#v48s4-shell{width:min(1240px,98vw);height:calc(100dvh - 18px);max-height:calc(100dvh - 18px);border-radius:30px;padding:12px;background:linear-gradient(145deg,rgba(255,255,255,.14),rgba(255,255,255,.05)),linear-gradient(145deg,#0b1724,#0b3523);border:1px solid rgba(255,255,255,.20);box-shadow:0 28px 85px rgba(0,0,0,.48);position:relative;overflow:hidden;box-sizing:border-box;isolation:isolate}#v48s4-shell:before{content:"";position:absolute;inset:9px;border-radius:24px;border:1px solid rgba(125,211,252,.14);background-image:linear-gradient(rgba(125,211,252,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(125,211,252,.07) 1px,transparent 1px);background-size:34px 34px;opacity:.55;pointer-events:none}'
      +'#v48s4-head{position:relative;z-index:2;display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center;min-height:58px}#v48s4-title{margin:0;font-size:clamp(25px,3.2vw,42px);line-height:1;font-weight:1000;text-shadow:0 6px 18px rgba(0,0,0,.45)}#v48s4-role{display:inline-flex;margin-top:7px;padding:7px 13px;border-radius:999px;background:rgba(14,165,233,.17);border:1px solid rgba(125,211,252,.35);font-weight:950;color:#dff7ff;font-size:13px}#v48s4-topchips{display:flex;gap:5px;flex-wrap:wrap;justify-content:flex-end}.v48s4-chip{display:inline-flex;align-items:center;gap:5px;padding:7px 10px;border-radius:999px;background:rgba(255,255,255,.13);border:1px solid rgba(255,255,255,.15);font-weight:950;font-size:12px;white-space:nowrap}'
      +'#v48s4-layout{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,1.33fr) minmax(340px,.72fr);gap:10px;height:calc(100% - 72px);margin-top:8px;min-height:0}#v48s4-viewport{position:relative;overflow:hidden;border-radius:28px;border:1px solid rgba(255,255,255,.17);background:radial-gradient(circle at 55% 20%,rgba(20,184,166,.23),transparent 30%),linear-gradient(180deg,rgba(125,211,252,.10),rgba(0,0,0,.18));box-shadow:inset 0 0 35px rgba(14,165,233,.12);perspective:1000px}.world2 #v48s4-viewport{background:radial-gradient(circle at 52% 18%,rgba(190,242,100,.20),transparent 25%),linear-gradient(180deg,rgba(22,163,74,.18),rgba(0,0,0,.18))}.world3 #v48s4-viewport{background:radial-gradient(circle at 50% 25%,rgba(56,189,248,.30),transparent 33%),linear-gradient(180deg,rgba(14,165,233,.16),rgba(0,0,0,.20))}.world4 #v48s4-viewport{background:radial-gradient(circle at 45% 20%,rgba(250,204,21,.22),transparent 28%),linear-gradient(180deg,rgba(34,197,94,.14),rgba(0,0,0,.21))}.world5 #v48s4-viewport{background:radial-gradient(circle at 60% 15%,rgba(168,85,247,.25),transparent 28%),linear-gradient(180deg,rgba(15,23,42,.28),rgba(2,6,23,.24))}.world6 #v48s4-viewport{background:radial-gradient(circle at 58% 24%,rgba(251,191,36,.25),transparent 30%),linear-gradient(180deg,rgba(244,114,182,.12),rgba(0,0,0,.20))}.world7 #v48s4-viewport{background:radial-gradient(circle at 50% 18%,rgba(74,222,128,.30),transparent 32%),linear-gradient(180deg,rgba(20,83,45,.22),rgba(0,0,0,.21))}.world8 #v48s4-viewport{background:radial-gradient(circle at 60% 16%,rgba(103,232,249,.26),transparent 30%),linear-gradient(180deg,rgba(30,64,175,.18),rgba(0,0,0,.22))}'
      +'#v48s4-viewport:before{content:"";position:absolute;left:7%;right:7%;top:15%;height:3px;border-radius:99px;background:linear-gradient(90deg,transparent,rgba(125,211,252,.86),transparent);box-shadow:0 0 22px rgba(125,211,252,.7);animation:v48s4Scan 5s ease-in-out infinite;z-index:5;pointer-events:none}#v48s4-viewport:after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 24% 69%,rgba(134,239,172,.18),transparent 15%),radial-gradient(circle at 75% 28%,rgba(250,204,21,.12),transparent 16%),radial-gradient(circle at 52% 52%,rgba(56,189,248,.10),transparent 22%);animation:v48s4Glow 5.8s ease-in-out infinite;pointer-events:none;z-index:1}'
      +'#v48s4-board{position:absolute;left:50%;top:52%;width:430px;height:430px;margin-left:-215px;margin-top:-202px;display:grid;grid-template-columns:repeat(4,1fr);gap:12px;transform-style:preserve-3d;transform:rotateX(60deg) rotateZ(-35deg);transition:transform .45s ease;z-index:3}.cam1 #v48s4-board{transform:rotateX(56deg) rotateZ(43deg)}.cam2 #v48s4-board{transform:rotateX(64deg) rotateZ(-126deg)}.v48s4-tile{border:0;border-radius:18px;background:linear-gradient(145deg,#1d7c4d,#0f5132);box-shadow:0 18px 0 #06351e,0 26px 24px rgba(0,0,0,.34);position:relative;transform-style:preserve-3d;cursor:pointer;outline:1px solid rgba(134,239,172,.24);min-height:86px;transition:transform .18s ease,outline .18s ease,filter .18s ease}.v48s4-tile:hover{outline:4px solid rgba(250,204,21,.58);filter:brightness(1.12)}.v48s4-tile:before{content:"";position:absolute;inset:8px;border-radius:14px;background:linear-gradient(145deg,rgba(255,255,255,.16),rgba(255,255,255,.03));border:1px solid rgba(255,255,255,.12)}.v48s4-tile.filled{outline:3px solid rgba(74,222,128,.60)}.v48s4-tile.complete{animation:v48s4TileWin 1.4s ease-in-out infinite}.v48s4-tile small{position:absolute;left:15%;top:15%;width:13px;height:13px;border-radius:50%;background:rgba(187,247,208,.56);box-shadow:0 0 14px rgba(187,247,208,.7);animation:v48s4Node 2.8s ease-in-out infinite}.v48s4-cube-icon{position:absolute;left:50%;top:48%;width:74px;height:74px;margin-left:-37px;margin-top:-56px;border-radius:21px;background:linear-gradient(145deg,#fff,#dbeafe);color:#0f172a;display:flex;align-items:center;justify-content:center;font-size:35px;font-weight:1000;box-shadow:0 15px 0 rgba(15,23,42,.25),0 24px 28px rgba(0,0,0,.28);transform:translateZ(42px) rotateZ(35deg) rotateX(-60deg);border:1px solid rgba(255,255,255,.55)}.v48s4-tile i{position:absolute;left:8px;right:8px;bottom:7px;font-style:normal;font-size:9px;font-weight:1000;color:#dcfce7;text-shadow:0 2px 6px rgba(0,0,0,.5);transform:translateZ(26px) rotateZ(35deg) rotateX(-60deg)}'
