      +'@media(max-height:760px) and (min-width:821px){#v48s4-shell{height:calc(100dvh - 12px);max-height:calc(100dvh - 12px);padding:9px}#v48s4-head{min-height:48px}#v48s4-title{font-size:clamp(22px,2.8vw,32px)}#v48s4-role{padding:5px 10px;font-size:12px}.v48s4-chip{padding:5px 8px;font-size:10px}#v48s4-layout{height:calc(100% - 58px);gap:8px;margin-top:5px}#v48s4-board{width:360px;height:360px;margin-left:-180px;margin-top:-162px;gap:9px}.v48s4-tile{min-height:72px;border-radius:15px;box-shadow:0 13px 0 #06351e,0 20px 22px rgba(0,0,0,.30)}.v48s4-cube-icon{width:60px;height:60px;margin-left:-30px;margin-top:-49px;font-size:29px}.v48s4-tile i{display:none}#v48s4-mission-title{font-size:16px;margin-top:5px}#v48s4-goal{font-size:12px}.v48s4-mod{min-height:50px;padding:4px}.v48s4-mod span{font-size:19px}.v48s4-map{min-height:34px}.v48s4-node em{display:none}#v48s4-log{min-height:30px;max-height:36px;padding:7px}.v48s4-action{padding:7px 9px;font-size:11px}}'
