  function v48s4Overlay(){
    var ov=document.getElementById('v48s-oki3d');
    if(!ov){ ov=document.createElement('div'); ov.id='v48s-oki3d'; document.body.appendChild(ov); }
    ov.className='v48s4-mode';
    ov.setAttribute('dir',v48s4Lang()==='ar'?'rtl':'ltr');
    return ov;
  }
  function v48s4Lock(){
    try{ document.documentElement.style.overflow='hidden'; document.body.style.overflow='hidden'; document.documentElement.setAttribute('data-v48s4-oki3d','1'); }catch(e){}
  }
  function v48s4Unlock(){
    try{ document.documentElement.style.overflow=''; document.body.style.overflow=''; document.documentElement.removeAttribute('data-v48s4-oki3d'); }catch(e){}
  }
  function v48s4Stage(){
    var c=v48s4Counts().growth;
    if(v48s4State.done) return 4;
    if(c>70) return 3;
    if(c>35) return 2;
    return 1;
  }
  function v48s4PresentNeed(m){
    var miss=[], i;
    for(i=0;i<m.need.length;i++){ if(!v48s4PlacedHas(m.need[i])) miss.push(m.need[i]); }
    return miss;
  }
  function v48s4Log(txt){ v48s4State.log=txt||''; var el=document.getElementById('v48s4-log'); if(el) el.textContent=v48s4State.log; }
  function v48s4Render(){
    var ov=v48s4Overlay(), m=v48s4Mission(), c=v48s4Counts(), done=v48s4DoneCount(), award=800+Math.min(3000,(m.level*40)), ml=v48s4ModuleList(m);
    if(!v48s4Has(ml,v48s4State.selected)) v48s4State.selected=ml[0]||'seed';
    ov.innerHTML='<div id="v48s4-shell" class="'+v48s4PanelClass(m)+' stage'+v48s4Stage()+'">'
      +'<div id="v48s4-head"><div><h1 id="v48s4-title">🏗️ '+v48s4Html(v48s4T('title'))+'</h1><div id="v48s4-role">'+v48s4Html(v48s4T('role'))+' • '+v48s4Html(v48s4T('future'))+'</div></div>'
      +'<div id="v48s4-topchips"><span class="v48s4-chip">🏁 '+v48s4Html(v48s4T('level'))+': '+m.level+'</span><span class="v48s4-chip">🗺️ '+v48s4Html(v48s4T('region'))+': '+(m.worldIndex+1)+'</span><span class="v48s4-chip">✅ '+v48s4Html(v48s4T('progress'))+': '+done+'</span><span class="v48s4-chip">🌿 '+v48s4Html(v48s4T('growth'))+': '+c.growth+'%</span></div></div>'
      +'<div id="v48s4-layout"><div id="v48s4-viewport"><div class="v48s4-drone">🚁</div><div class="v48s4-waterline"></div><div id="v48s4-board">'+v48s4BoardHtml(m)+'</div><div id="v48s4-plant"><span class="v48s4-stem"></span><span class="v48s4-leaf"></span><span class="v48s4-leaf r"></span><span class="v48s4-flower"></span></div><div class="v48s4-crane">🏗️</div><div class="v48s4-stars" id="v48s4-stars"></div></div>'
      +'<aside id="v48s4-panel"><div class="v48s4-pill">'+v48s4Html(v48s4T('mission'))+' '+m.level+' • '+v48s4Html(m.world)+'</div><h2 id="v48s4-mission-title">'+v48s4Html(m.title)+'</h2><p id="v48s4-goal">'+v48s4Html(m.goal)+'</p><div class="v48s4-needrow"><span class="v48s4-pill">'+v48s4Html(v48s4T('needed'))+'</span>'+v48s4NeedHtml(m)+'</div><div class="v48s4-map-title">🧭 '+v48s4Html(v48s4T('map'))+'</div><div class="v48s4-map">'+v48s4MapHtml(m)+'</div><div id="v48s4-mod-title" class="v48s4-pill">🧰 '+v48s4Html(v48s4T('modules'))+'</div><div id="v48s4-mods" class="v48s4-mod-grid">'+v48s4ModsHtml(m)+'</div><div id="v48s4-log">'+v48s4Html(v48s4State.log||v48s4T('hint'))+'</div><div class="v48s4-actions"><button id="v48s4-run" class="v48s4-action" type="button">▶ '+v48s4Html(v48s4T('run'))+'</button><button id="v48s4-next" class="v48s4-action" type="button">➡ '+v48s4Html(v48s4T('next'))+'</button><button id="v48s4-reset" class="v48s4-action" type="button">🧹 '+v48s4Html(v48s4T('reset'))+'</button><button id="v48s4-rotate" class="v48s4-action" type="button">📐 '+v48s4Html(v48s4T('rotate'))+'</button><button id="v48s4-close" class="v48s4-action" type="button">✕ '+v48s4Html(v48s4T('close'))+'</button></div></aside></div></div>';
    v48s4Wire();
  }
  function v48s4Wire(){
    var a=document.querySelectorAll('#v48s4-mods .v48s4-mod'), b=document.querySelectorAll('#v48s4-board .v48s4-tile'), i, el;
    for(i=0;i<a.length;i++){
      a[i].onclick=function(){ v48s4State.selected=this.getAttribute('data-mod')||'seed'; v48s4State.log=v48s4ModData[v48s4State.selected].ico+' '+v48s4ModName(v48s4State.selected); v48s4Render(); };
    }
    for(i=0;i<b.length;i++){
      b[i].onclick=function(){ v48s4Place(this.getAttribute('data-pos')); };
    }
    el=document.getElementById('v48s4-run'); if(el) el.onclick=v48s4Check;
    el=document.getElementById('v48s4-next'); if(el) el.onclick=v48s4Next;
    el=document.getElementById('v48s4-reset'); if(el) el.onclick=v48s4Reset;
    el=document.getElementById('v48s4-rotate'); if(el) el.onclick=v48s4Rotate;
    el=document.getElementById('v48s4-close'); if(el) el.onclick=v48s4Close;
  }
  function v48s4Place(pos){
    if(!pos) return;
    v48s4State.grid[pos]=v48s4State.selected||'seed';
    v48s4State.done=false;
    v48s4State.log=((v48s4ModData[v48s4State.selected]&&v48s4ModData[v48s4State.selected].ico)||'🔧')+' '+v48s4ModName(v48s4State.selected);
    v48s4Render();
    v48s4Pop(((v48s4ModData[v48s4State.selected]&&v48s4ModData[v48s4State.selected].ico)||'✨'));
  }
  function v48s4Pop(icon){
    var box=document.getElementById('v48s4-stars'); if(!box) return;
    var i, sp;
    for(i=0;i<14;i++){
      sp=document.createElement('span'); sp.className='v48s4-pop'; sp.textContent=(i%4===0?icon:(i%2===0?'✨':'🌿')); sp.style.left=(18+Math.random()*64)+'%'; sp.style.top=(30+Math.random()*46)+'%'; sp.style.animationDelay=(Math.random()*0.25)+'s'; box.appendChild(sp);
      setTimeout((function(x){return function(){try{x.remove();}catch(e){}};})(sp),1600);
    }
  }
  function v48s4Award(){
    var add=800+Math.min(3000,(v48s4State.level*40));
    try{ totalScore=(parseInt(totalScore,10)||0)+add; _eduScoreSync(totalScore); }catch(e){}
    try{ if(typeof updateHud==='function') updateHud(); }catch(e2){}
    return add;
  }
  function v48s4Check(){
    var m=v48s4Mission(), miss=v48s4PresentNeed(m), add, txt, i;
    if(miss.length===0){
      if(!v48s4State.done){ add=v48s4Award(); v48s4SaveDone(v48s4State.level); v48s4SaveLevel(v48s4State.level+1); }
      else add=0;
      v48s4State.done=true;
      txt=v48s4T('good')+' '+(add?('+'+add+' '+v48s4T('award')+'. '):'')+v48s4T('saved');
      v48s4State.log=txt;
      v48s4Render();
      v48s4Pop('🌸');
      try{ if(window.evV48RRoomMusicHit) window.evV48RRoomMusicHit('success'); }catch(e){}
    }else{
      txt=v48s4T('missing')+' → ';
      for(i=0;i<miss.length;i++){ txt+=(i?', ':'')+((v48s4ModData[miss[i]]&&v48s4ModData[miss[i]].ico)||'🔧')+' '+v48s4ModName(miss[i]); }
      v48s4Log(txt);
      try{ if(window.evV48RRoomMusicHit) window.evV48RRoomMusicHit('soft'); }catch(e2){}
    }
  }
  function v48s4Next(){
    if(!v48s4State.done){ v48s4Log(v48s4T('finishFirst')); return; }
    v48s4State.level=(v48s4State.level||1)+1;
    v48s4SaveLevel(v48s4State.level);
    v48s4State.grid={}; v48s4State.done=false; v48s4State.selected='seed'; v48s4State.log=v48s4T('worldOpen')+' • '+v48s4T('hint');
    v48s4Render(); v48s4Pop('🚀');
  }
  function v48s4Reset(){
    v48s4State.grid={}; v48s4State.done=false; v48s4State.selected='seed'; v48s4State.log=v48s4T('hint'); v48s4Render();
  }
  function v48s4Rotate(){
    v48s4State.camera=(v48s4State.camera+1)%3; v48s4Render();
  }
  function v48s4ShowMusic(){
    try{
      var m=document.getElementById('ada-muzik');
      if(m){ m.style.display='flex'; m.style.position='fixed'; m.style.zIndex='1000005'; }
      var layers=document.getElementById('ada-layers'); if(layers) layers.style.zIndex='1000006';
      window._adaIdx=12;
      if(typeof window._adaMarkActive==='function') window._adaMarkActive(12);
    }catch(e){}
  }
  function v48s4Open(){
    v48s4InjectStyle(); v48s4Lock();
    try{ document.getElementById('gs').style.display='none'; }catch(e){}
    try{ document.getElementById('hm').style.display='none'; }catch(e2){}
    v48s4State.level=v48s4GetLevel(); v48s4State.grid={}; v48s4State.selected='seed'; v48s4State.done=false; v48s4State.camera=0; v48s4State.log=v48s4T('openMsg')+' '+v48s4T('hint');
    var ov=v48s4Overlay(); ov.style.display='flex';
    v48s4Render(); v48s4ShowMusic(); setTimeout(v48s4ShowMusic,260); setTimeout(v48s4ShowMusic,900);
  }
  function v48s4Close(){
    var ov=document.getElementById('v48s-oki3d'); if(ov) ov.style.display='none';
    v48s4Unlock();
    try{ currentRoom=null; gameActive=false; }catch(e){}
    try{ document.getElementById('gs').style.display='none'; document.getElementById('hm').style.display='flex'; }catch(e2){}
    try{ buildGrid(); }catch(e3){}
  }
  function v48s4InstallGate(){
    try{
      if(window.evV48JGateRooms){
        window.evV48JGateRooms.oki3dbahce={
          icon:'🏗️',
          btn:{tr:'3D Bahçeye Gir',en:'Enter 3D Garden',de:'In den 3D-Garten',fr:'Entrer au jardin 3D',ar:'ادخل الحديقة الثلاثية'},
          m:{
            tr:['Level level büyüyen akıllı bahçeye gir.','Her başarı yeni bir alan açar.','Oki robotu 100 level yolculuğa hazır.','Tohum, su, enerji ve ışığı mühendis gibi kur.','Bahçeyi tek çiçekten teknoloji adasına taşı.'],
            en:['Enter the smart garden that grows level by level.','Every success opens a new zone.','Oki robot is ready for a 100-level journey.','Build seed, water, energy and light like an engineer.','Turn one flower into a technology island.'],
            de:['Betritt den smarten Garten, der Level für Level wächst.','Jeder Erfolg öffnet einen neuen Bereich.','Oki-Roboter ist bereit für 100 Level.','Baue Samen, Wasser, Energie und Licht wie ein Ingenieur.','Mach aus einer Blume eine Technikinsel.'],
            fr:['Entre dans le jardin intelligent qui grandit niveau par niveau.','Chaque réussite ouvre une nouvelle zone.','Le robot Oki est prêt pour 100 niveaux.','Construis graine, eau, énergie et lumière comme un ingénieur.','Transforme une fleur en île technologique.'],
            ar:['ادخل الحديقة الذكية التي تكبر مستوى بعد مستوى.','كل نجاح يفتح منطقة جديدة.','روبوت أوكي جاهز لرحلة من 100 مستوى.','ابنِ البذرة والماء والطاقة والضوء مثل مهندس.','حوّل زهرة واحدة إلى جزيرة تقنية.']
          },
          types:['portal','blocks','badge','ticket','frame'],
          pal:['#22c55e','#0ea5e9','#facc15']
        };
      }
    }catch(e){}
  }
  function v48s4InstallRoomName(){
    try{
      if(typeof ROOMS!=='undefined'){
        var i, found=false;
        for(i=0;i<ROOMS.length;i++){ if(ROOMS[i]&&ROOMS[i].id==='oki3dbahce'){ found=true; ROOMS[i].special='oki3dbahce'; ROOMS[i].type='special'; } }
        if(!found){ ROOMS.push({id:'oki3dbahce',name:"Oki'nin 3D Bahçesi",ico:'🏗️',type:'special',unlock:0,special:'oki3dbahce',bg:['#052e16','#064e3b','#0ea5e9','#fde047'],gr:['#064e3b','#052e16'],lesson:'Akıllı bahçeyi level level kur.'}); }
      }
    }catch(e){}
  }

  window.openOki3DBahcesi=v48s4Open;
  window.openOki3DBahcesi.__v48s4ScalableLevelEngine=true;
  window.evV48S4Oki3DLevelReset=function(){ v48s4SaveLevel(1); try{ localStorage.setItem(V48S4_DONE_KEY,'0'); }catch(e){} };
