+'#v14-panel{min-height:0;padding:18px;box-sizing:border-box;display:flex;flex-direction:column;gap:10px}.v14-paneltop{padding:13px 18px;border-radius:22px;background:rgba(2,6,23,.58);border:1px solid rgba(255,255,255,.12);font-size:19px;font-weight:1000}.v14-panel h3{margin:4px 0 2px;color:#fde68a;font-size:35px;line-height:1.05}.v14-panel p{margin:0 0 6px;font-size:21px;line-height:1.22;font-weight:900;color:#ecfeff}.v14-steps{display:flex;gap:8px}.v14-step{flex:1;text-align:center;padding:9px 0;border-radius:14px;background:rgba(255,255,255,.15);font-size:18px;font-weight:1000}.v14-step.on{background:#22c55e}.v14-msg{padding:12px 16px;border-radius:18px;background:rgba(2,6,23,.68);font-size:19px;line-height:1.18;font-weight:1000;color:#fef3c7;min-height:45px}.v14-actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.v14-btn{border:none;border-radius:18px;padding:14px 18px;font-size:19px;font-weight:1000;cursor:pointer;box-shadow:0 8px 0 rgba(0,0,0,.18)}.v14-primary{background:linear-gradient(90deg,#facc15,#fb923c);color:#051322}.v14-green{background:linear-gradient(90deg,#22c55e,#86efac);color:#052e16}.v14-gray{background:linear-gradient(90deg,#cbd5e1,#94a3b8);color:#0f172a}.v14-blue{background:linear-gradient(90deg,#7dd3fc,#c4b5fd);color:#051322}.v14-dpad{display:grid;grid-template-columns:80px 80px 80px;grid-template-rows:66px 66px;gap:9px;justify-content:center;margin-top:auto}.v14-dpad .v14-btn{padding:7px 0;font-size:31px}.v14-dpad .up{grid-column:2}.v14-dpad .left{grid-column:1;grid-row:2}.v14-dpad .down{grid-column:2;grid-row:2}.v14-dpad .right{grid-column:3;grid-row:2}.v14-bottom{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-top:auto}.v14-bottom .v14-btn{font-size:18px;padding:13px 10px}.v14-win{animation:v14pop .55s ease both}.v14-shake{animation:v14shake .25s ease both}@keyframes v14pop{0%{transform:scale(.9)}70%{transform:scale(1.05)}100%{transform:scale(1)}}@keyframes v14shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-7px)}75%{transform:translateX(7px)}}'
