  function headHtml(){ return '<div id="v14-head"><div class="v14-title"><div class="ico">🏃</div><div><h2>'+esc(tx('title'))+'</h2><div class="v14-sub">'+esc(tx('sub'))+'</div></div></div><div class="v14-topstats"><div class="v14-pill">🎮 '+esc(tx('chapter'))+': '+S.stage+'/'+MAX_STAGE+'</div><div class="v14-pill">✅ '+esc(tx('done'))+': '+S.done+'</div><div class="v14-pill">⭐ '+esc(tx('score'))+': '+S.score+'</div></div></div>'; }
  function stageHtml(){ var a=st(), h='<div id="v14-stage" class="'+(S.celebrate?'v14-win ':'')+(S.wrong?'v14-shake ':'')+'"><div class="v14-badge">'+esc(a.icon)+' '+esc(localized(a.name))+'</div><div class="v14-world"></div>'; if(a.type==='move'||a.type==='maze') h+=gridHtml(a); else if(a.type==='door') h+=doorStage(a); else if(a.type==='memory') h+=memoryStage(a); else if(a.type==='timing') h+=timingStage(a); else if(a.type==='reflex') h+=reflexStage(a); else h+=finalStage(a); return h+'</div>'; }
  function keyFor(x,y){ return x+'_'+y; }
  function isBlock(a,x,y){ var i,b=a.blocks||[]; for(i=0;i<b.length;i++) if(b[i][0]===x&&b[i][1]===y) return true; return false; }
  function starAt(a,x,y){ var i,b=a.stars||[]; for(i=0;i<b.length;i++) if(b[i][0]===x&&b[i][1]===y&&!S.items[keyFor(x,y)]) return i; return -1; }
  function gridHtml(a){ var x,y,h='<div class="v14-grid">', content, cls, g=a.gate||[4,3]; for(y=0;y<4;y++){ for(x=0;x<5;x++){ cls='v14-cell'; content=''; if(isBlock(a,x,y)){ cls+=' block'; content=''; } if(g[0]===x&&g[1]===y){ cls+=' gate'; content=S.gateOpen||a.type==='maze'?'🚪':'🔒'; } if(starAt(a,x,y)>=0){ content=a.icon||'⭐'; } if(S.x===x&&S.y===y){ cls+=' oki'; content='<span class="v14-oki">🤖</span><span class="v14-label">Oki</span>'; } h+='<button class="'+cls+'" onclick="evV48S14TapCell('+x+','+y+')">'+content+'</button>'; }} return h+'</div>'; }
  function doorStage(a){ var i,h='<div class="v14-doorwrap">'; for(i=0;i<3;i++){ h+='<button class="v14-door '+(i+1===a.answer?'good':'wrong')+'" onclick="evV48S14Door('+(i+1)+')">'+esc(a.doors[i]||'🚪')+'</button>'; } return h+'</div>'; }
  function memoryStage(a){ var i,h='<div class="v14-stones">'; for(i=1;i<=4;i++){ h+='<button class="v14-stone '+(S.flash===i?'flash':'')+'" onclick="evV48S14Stone('+i+')">'+i+'</button>'; } return h+'</div>'; }
  function timingStage(a){ var left=a.safe[0], w=a.safe[1]-a.safe[0]; return '<div class="v14-timewrap"><div class="v14-timebar"><div class="v14-safe" style="left:'+left+'%;width:'+w+'%"></div><div class="v14-marker" style="left:'+S.timerPos+'%"></div></div></div>'; }
  function reflexStage(a){ var i,h='<div class="v14-reflex">'; for(i=0;i<6;i++){ h+='<button class="v14-target" onclick="evV48S14Reflex('+i+')">'+esc(a.items[i]||'⭐')+'</button>'; } return h+'</div>'; }
  function finalStage(a){ return '<div class="v14-final"><div style="font-size:110px;filter:drop-shadow(0 0 30px rgba(250,204,21,.65))">🎉</div><div style="font-size:42px;font-weight:1000;color:#fde68a;max-width:480px;line-height:1.05">'+esc(localized(a.text))+'</div></div>'; }
  function stepsHtml(){ var i,h='<div class="v14-steps">'; for(i=1;i<=Math.min(MAX_STAGE,5);i++){ h+='<div class="v14-step '+(i<=((S.stage-1)%5)+1?'on':'')+'">'+i+'</div>'; } return h+'</div>'; }
  function panelHtml(){ var a=st(), h='<div id="v14-panel" class="v14-panel"><div class="v14-paneltop">🎯 '+esc(tx('chapter'))+' '+S.stage+'</div><h3>'+esc(localized(a.name))+'</h3><p>'+esc(localized(a.text))+'</p>'+stepsHtml()+'<div class="v14-msg">'+esc(S.msg)+'</div>'; if(a.type==='move'||a.type==='maze'){ h+=dpadHtml(); if(S.gateOpen||a.type==='maze') h+='<div class="v14-actions"><button class="v14-btn v14-primary" onclick="evV48S14Gate()">🚪 '+esc(tx('go'))+'</button></div>'; } else if(a.type==='door'){ h+='<div class="v14-actions"><button class="v14-btn v14-blue" onclick="evV48S14Door(1)">'+esc(a.doors[0])+' 1</button><button class="v14-btn v14-blue" onclick="evV48S14Door(2)">'+esc(a.doors[1])+' 2</button><button class="v14-btn v14-blue" onclick="evV48S14Door(3)">'+esc(a.doors[2])+' 3</button></div>'; } else if(a.type==='memory'){ h+='<div class="v14-actions"><button class="v14-btn v14-primary" onclick="evV48S14ShowOrder()">👀 '+esc(tx('watch'))+'</button><div class="v14-pill" style="font-size:16px;padding:12px 14px">'+esc(tx('target'))+': '+S.seqStep+'/'+(a.seq?a.seq.length:0)+'</div></div>'; } else if(a.type==='timing'){ h+='<div class="v14-actions"><button class="v14-btn v14-primary" onclick="evV48S14StartTiming()">▶ '+esc(tx('start'))+'</button><button class="v14-btn v14-green" onclick="evV48S14TimingTap()">⚡ '+esc(tx('tap'))+'</button></div>'; } else if(a.type==='reflex'){ h+='<div class="v14-actions"><div class="v14-pill">'+esc(tx('target'))+': '+esc(a.target)+' '+S.reflexGood+'/'+a.need+'</div></div>'; } else { h+='<div class="v14-actions"><button class="v14-btn v14-primary" onclick="evV48S14Final()">🎉 '+esc(tx('ready'))+'</button></div>'; } h+='<div class="v14-bottom"><button class="v14-btn v14-gray" onclick="evV48S14Reset()">↻ '+esc(tx('reset'))+'</button><button class="v14-btn v14-gray" onclick="evV48S14Music()">🎵 '+esc(tx('music'))+'</button><button class="v14-btn v14-gray" onclick="evV48S14Close()">× '+esc(tx('close'))+'</button></div></div>'; return h; }
  function dpadHtml(){ return '<div class="v14-dpad"><button class="v14-btn v14-green up" onclick="evV48S14Move(0,-1)">↑</button><button class="v14-btn v14-green left" onclick="evV48S14Move(-1,0)">←</button><button class="v14-btn v14-green down" onclick="evV48S14Move(0,1)">↓</button><button class="v14-btn v14-green right" onclick="evV48S14Move(1,0)">→</button></div>'; }
  function render(){ var o=overlay(); o.innerHTML='<div id="v14-shell">'+headHtml()+stageHtml()+panelHtml()+'</div>'; }

  function move(dx,dy,noRender){ var a=st(), nx=S.x+dx, ny=S.y+dy, star, g; if(!(a.type==='move'||a.type==='maze')) return; if(nx<0||nx>4||ny<0||ny>3||isBlock(a,nx,ny)){ S.msg=tx('bad'); S.wrong=1; if(!noRender) render(); S.wrong=0; return; } S.x=nx; S.y=ny; star=starAt(a,nx,ny); if(star>=0){ S.items[keyFor(nx,ny)]=1; S.count++; S.score+=100+(S.stage*5); S.msg='⭐ '+S.count+'/'+((a.stars&&a.stars.length)||0); if(a.stars && S.count>=a.stars.length){ S.gateOpen=true; S.msg='✅ '+tx('go'); } } g=a.gate||[4,3]; if(nx===g[0]&&ny===g[1]){ if(a.type==='maze'||S.gateOpen){ complete(noRender); return; } S.msg=tx('need'); } if(!noRender) render(); }
  function tapCell(x,y){ if(x===S.x&&y===S.y) return; if(Math.abs(x-S.x)+Math.abs(y-S.y)===1) move(x-S.x,y-S.y); }
  function gate(noRender){ var a=st(), g=a.gate||[4,3]; if((a.type==='move'||a.type==='maze') && S.x===g[0]&&S.y===g[1] && (a.type==='maze'||S.gateOpen)){ complete(noRender); } else { S.msg=tx('need'); if(!noRender) render(); } }
  function door(n,noRender){ var a=st(); if(a.type!=='door') return; if(n===a.answer){ S.score+=350+S.stage*12; complete(noRender); } else { S.score=Math.max(0,S.score-25); S.msg=tx('bad'); S.wrong=1; if(!noRender) render(); S.wrong=0; } }
  function showOrder(){ var a=st(), i=0; if(a.type!=='memory') return; if(timer){ clearInterval(timer); timer=null; } S.seqStep=0; S.msg=tx('memoryHint'); timer=setInterval(function(){ if(i>=a.seq.length){ clearInterval(timer); timer=null; S.flash=0; render(); return; } S.flash=a.seq[i]; render(); i++; },430); }
  function stone(n,noRender){ var a=st(); if(a.type!=='memory') return; if(n===a.seq[S.seqStep]){ S.seqStep++; S.score+=75+S.stage; S.msg='✅ '+S.seqStep+'/'+a.seq.length; if(S.seqStep>=a.seq.length){ complete(noRender); return; } } else { S.seqStep=0; S.msg=tx('bad'); S.wrong=1; } if(!noRender) render(); S.wrong=0; }
  function startTiming(){ var a=st(); if(a.type!=='timing') return; if(timer) clearInterval(timer); timer=setInterval(function(){ S.timerPos+=S.timerDir*(a.speed||8); if(S.timerPos>92){ S.timerPos=92; S.timerDir=-1; } if(S.timerPos<2){ S.timerPos=2; S.timerDir=1; } render(); },120); }
  function timingTap(noRender){ var a=st(); if(a.type!=='timing') return; if(S.timerPos>=a.safe[0] && S.timerPos<=a.safe[1]){ S.score+=420+S.stage*11; if(timer){ clearInterval(timer); timer=null; } complete(noRender); } else { S.score=Math.max(0,S.score-20); S.msg=tx('bad'); S.wrong=1; if(!noRender) render(); S.wrong=0; } }
  function reflex(i,noRender){ var a=st(); if(a.type!=='reflex') return; if((a.items[i]||'')===a.target){ S.reflexGood++; S.score+=90+S.stage; S.msg='✅ '+S.reflexGood+'/'+a.need; if(S.reflexGood>=a.need){ complete(noRender); return; } } else { S.score=Math.max(0,S.score-20); S.msg=tx('bad'); S.wrong=1; } if(!noRender) render(); S.wrong=0; }
  function finalGo(noRender){ if(st().type==='final') complete(noRender); }
  function complete(noRender){ if(timer){ clearInterval(timer); timer=null; } if(S.stage>S.done) S.done=S.stage; S.score+=500+S.stage*30; S.celebrate=1; S.msg=(S.stage>=MAX_STAGE)?tx('finish'):tx('ok'); save(); if(!noRender) render(); if(S.stage<MAX_STAGE){ if(noRender){ prep(S.stage+1); save(); } else { setTimeout(function(){ prep(S.stage+1); save(); render(); },760); } } else { save(); } S.celebrate=0; }

