  window.evV48S14SelfTest=function(){ var i,a,j,rep={start:false,flow:false,end:false,stages:0}; reset(false); rep.start=(S.stage===1&&S.done===0); for(i=1;i<=MAX_STAGE;i++){ prep(i); a=st(); if(a.type==='door'){ door(a.answer,true); } else if(a.type==='memory'){ for(j=0;j<a.seq.length;j++) stone(a.seq[j],true); } else if(a.type==='timing'){ S.timerPos=Math.floor((a.safe[0]+a.safe[1])/2); timingTap(true); } else if(a.type==='reflex'){ for(j=0;j<a.items.length;j++){ if(a.items[j]===a.target){ S.reflexGood=a.need-1; reflex(j,true); break; } } } else if(a.type==='move'){ S.count=(a.stars&&a.stars.length)||0; S.gateOpen=true; S.x=(a.gate||[4,3])[0]; S.y=(a.gate||[4,3])[1]; gate(true); } else if(a.type==='maze'){ S.x=(a.gate||[4,3])[0]; S.y=(a.gate||[4,3])[1]; gate(true); } else if(a.type==='final'){ finalGo(true); } if(S.done>=i) rep.stages++; } rep.flow=(rep.stages===MAX_STAGE); rep.end=(S.done===MAX_STAGE); reset(false); return rep; };

