  function load(){ S.stage=intval(get(KEY_STAGE,'1'),1); S.done=intval(get(KEY_DONE,'0'),0); S.score=intval(get(KEY_SCORE,'0'),0); if(S.stage<1||S.stage>MAX_STAGE) S.stage=1; prep(S.stage); }
  function save(){ set(KEY_STAGE,S.stage); set(KEY_DONE,S.done); set(KEY_SCORE,S.score); }
  function reset(renderIt){ S.stage=1; S.done=0; S.score=0; prep(1); save(); if(renderIt) render(); }
  function prep(n){ var a=stageData(n); S.stage=n; S.x=a.start?a.start[0]:0; S.y=a.start?a.start[1]:2; S.count=0; S.items={}; S.picks={}; S.step=0; S.preview=0; S.flash=-1; S.gateOpen=false; S.busy=0; S.completed=0; S.msg=tx('levelStart'); if(a.type==='seq') S.msg=tx('seqHint'); if(a.type==='pattern') S.msg=tx('patHint'); if(a.type==='move') S.msg=tx('moveHint'); }

  function headHtml(){ return '<div class="v16-head"><div class="v16-title"><div class="ico">🏃</div><div><h2>'+esc(tx('title'))+'</h2><div class="v16-sub">'+esc(tx('sub'))+'</div></div></div><div class="v16-stats"><div class="v16-pill">🎮 '+esc(tx('chapter'))+': '+S.stage+'/'+MAX_STAGE+'</div><div class="v16-pill">✅ '+esc(tx('done'))+': '+S.done+'</div><div class="v16-pill">⭐ '+esc(tx('score'))+': '+S.score+'</div></div></div>'; }
  function stepsHtml(){ var a=stageData(S.stage), i, total=(a.type==='seq')?a.seq.length:(a.type==='pattern'?a.pattern.length:(a.stars?a.stars.length:3)), h='<div class="v16-steps">'; if(total>8) total=8; for(i=0;i<total;i++) h+='<div class="v16-step '+(i<S.step||i<S.count?'on':'')+'">'+(i+1)+'</div>'; return h+'</div>'; }
  function isBlock(a,x,y){ var i,b=a.blocks||[]; for(i=0;i<b.length;i++) if(b[i][0]===x&&b[i][1]===y) return true; return false; }
  function starAt(a,x,y){ var i,s=a.stars||[]; for(i=0;i<s.length;i++) if(s[i][0]===x&&s[i][1]===y&&!S.items[keyFor(x,y)]) return i; return -1; }
  function playHtml(){ var a=stageData(S.stage); if(a.type==='move') return moveHtml(a); if(a.type==='pattern') return patternHtml(a); return seqHtml(a); }
  function moveHtml(a){ var x,y,h='<div class="v16-grid">', cls, content, g=a.gate||[4,3]; for(y=0;y<4;y++){ for(x=0;x<5;x++){ cls='v16-cell'; content=''; if(isBlock(a,x,y)){ cls+=' block'; } if(starAt(a,x,y)>=0) content=a.icon||'⭐'; if(g[0]===x&&g[1]===y){ cls+=' gate'; content=S.gateOpen?'🚪':'🔒'; } if(S.x===x&&S.y===y){ cls+=' oki'; content='<span class="v16-oki">🤖</span><span class="v16-label">Oki</span>'; } h+='<button class="'+cls+'" onclick="evV48S16TapCell('+x+','+y+')">'+content+'</button>'; }} return h+'</div>'; }
  function seqHtml(a){ var i,h='<div class="v16-seqstage"><div class="v16-tag">'+esc(a.icon)+' '+esc(localized(a.name))+'</div><div class="v16-runway">'; for(i=0;i<a.seq.length;i++){ h+='<div class="v16-token '+((S.preview||S.flash===i)?'':'hide')+' '+(S.flash===i?'flash':'')+'">'+esc(a.items[a.seq[i]])+'</div>'; } h+='</div><div class="v16-progress">'+esc(tx('target'))+': '+S.step+'/'+a.seq.length+'</div></div>'; return h; }
  function patternHtml(a){ var i,h='<div class="v16-seqstage"><div class="v16-tag">🧩 '+esc(localized(a.name))+'</div><div class="v16-pattern">'; for(i=0;i<a.cells;i++){ h+='<button class="v16-patcell '+((S.preview&&a.pattern.indexOf(i)>=0)?'show ':'')+(S.picks[i]?'pick':'')+'" onclick="evV48S16Pat('+i+')">'+((S.preview&&a.pattern.indexOf(i)>=0)||S.picks[i]?'✨':'')+'</button>'; } h+='</div><div class="v16-progress">'+esc(tx('target'))+': '+S.step+'/'+a.pattern.length+'</div></div>'; return h; }
  function stageHtml(){ return '<div class="v16-play"><div class="v16-tag">'+esc(stageData(S.stage).icon)+' '+esc(localized(stageData(S.stage).name))+'</div><div class="v16-board">'+playHtml()+'</div>'+(S.completed?'<div class="v16-confetti"></div>':'')+'</div>'; }
  function optionsHtml(a){ var i,h=''; if(a.type==='seq'){ h+='<div class="v16-options">'; for(i=0;i<a.items.length;i++) h+='<button class="v16-choice" onclick="evV48S16Pick('+i+')">'+esc(a.items[i])+'</button>'; h+='</div><div class="v16-actions"><button class="v16-btn gold" onclick="evV48S16Show()">👀 '+esc(tx('watch'))+'</button></div>'; } else if(a.type==='pattern'){ h+='<div class="v16-actions"><button class="v16-btn gold" onclick="evV48S16Show()">👀 '+esc(tx('watch'))+'</button></div>'; } else { h+='<div class="v16-dpad"><button class="v16-btn green up" onclick="evV48S16Move(0,-1)">↑</button><button class="v16-btn green left" onclick="evV48S16Move(-1,0)">←</button><button class="v16-btn green down" onclick="evV48S16Move(0,1)">↓</button><button class="v16-btn green right" onclick="evV48S16Move(1,0)">→</button></div><div class="v16-actions"><button class="v16-btn gold" onclick="evV48S16Gate()">🚪 '+esc(tx('go'))+'</button></div>'; } return h; }
  function panelHtml(){ var a=stageData(S.stage); return '<div class="v16-panel"><div class="v16-paneltop">🎯 '+esc(tx('chapter'))+' '+S.stage+'</div><h3>'+esc(localized(a.name))+'</h3><p>'+esc(localized(a.text))+'</p>'+stepsHtml()+'<div class="v16-msg">'+esc(S.msg)+'</div>'+optionsHtml(a)+'<div class="v16-bottom"><button class="v16-btn gray" onclick="evV48S16Reset()">↻ '+esc(tx('reset'))+'</button><button class="v16-btn gray" onclick="evV48S16Music()">🎵 '+esc(tx('music'))+'</button><button class="v16-btn gray" onclick="evV48S16Close()">× '+esc(tx('close'))+'</button></div></div>'; }
  function render(){ var o=overlay(); o.innerHTML='<div id="v16-shell">'+headHtml()+'<div class="v16-main">'+stageHtml()+panelHtml()+'</div></div>'; }

  function show(){ var a=stageData(S.stage), i=0; if(timer){ clearInterval(timer); clearTimeout(timer); timer=null; } if(a.type==='seq'){ S.preview=1; S.flash=-1; render(); timer=setInterval(function(){ S.flash=i; render(); i++; if(i>a.seq.length){ clearInterval(timer); timer=null; S.flash=-1; S.preview=0; render(); } },520); } else if(a.type==='pattern'){ S.preview=1; render(); timer=setTimeout(function(){ S.preview=0; timer=null; render(); },1600+Math.min(900,a.need*160)); } }
  function pick(i,noRender){ var a=stageData(S.stage); if(a.type!=='seq'||S.busy) return; if(i===a.seq[S.step]){ S.step++; S.score+=60+S.stage; S.msg='✅ '+S.step+'/'+a.seq.length; if(S.step>=a.seq.length){ complete(noRender); return; } } else { S.step=0; S.score=Math.max(0,S.score-25); S.msg=tx('bad'); } if(!noRender) render(); }
  function pat(i,noRender){ var a=stageData(S.stage); if(a.type!=='pattern'||S.busy) return; if(a.pattern.indexOf(i)>=0&&!S.picks[i]){ S.picks[i]=1; S.step++; S.score+=70+S.stage; S.msg='✅ '+S.step+'/'+a.pattern.length; if(S.step>=a.pattern.length){ complete(noRender); return; } } else { S.picks={}; S.step=0; S.score=Math.max(0,S.score-25); S.msg=tx('bad'); } if(!noRender) render(); }
  function move(dx,dy,noRender){ var a=stageData(S.stage), nx=S.x+dx, ny=S.y+dy, star, g; if(a.type!=='move'||S.busy) return; if(nx<0||nx>4||ny<0||ny>3||isBlock(a,nx,ny)){ S.msg=tx('bad'); if(!noRender) render(); return; } S.x=nx; S.y=ny; star=starAt(a,nx,ny); if(star>=0){ S.items[keyFor(nx,ny)]=1; S.count++; S.step=S.count; S.score+=90+S.stage; S.msg='⭐ '+S.count+'/'+((a.stars&&a.stars.length)||0); if(a.stars&&S.count>=a.stars.length){ S.gateOpen=true; S.msg='✅ '+tx('go'); } } g=a.gate||[4,3]; if(nx===g[0]&&ny===g[1]){ if(S.gateOpen){ complete(noRender); return; } S.msg=tx('need'); } if(!noRender) render(); }
  function tapCell(x,y){ if(Math.abs(x-S.x)+Math.abs(y-S.y)===1) move(x-S.x,y-S.y); }
  function gate(noRender){ var a=stageData(S.stage), g=a.gate||[4,3]; if(a.type==='move'&&S.x===g[0]&&S.y===g[1]&&S.gateOpen) complete(noRender); else { S.msg=tx('need'); if(!noRender) render(); } }
  function complete(noRender){ if(timer){ clearInterval(timer); clearTimeout(timer); timer=null; } S.busy=1; S.completed=1; if(S.stage>S.done) S.done=S.stage; S.score+=450+S.stage*20; S.msg=(S.stage>=MAX_STAGE)?tx('finish'):tx('ok'); save(); if(!noRender) render(); if(S.stage<MAX_STAGE){ if(noRender){ prep(S.stage+1); save(); } else { setTimeout(function(){ prep(S.stage+1); save(); render(); },900); } } }
  function music(){ try{ var m=document.getElementById('ada-muzik'); if(m){ m.style.display='flex'; m.style.position='fixed'; m.style.zIndex='1000012'; } var layers=document.getElementById('ada-layers'); if(layers) layers.style.zIndex='1000013'; window._adaIdx=12; if(typeof window._adaMarkActive==='function') window._adaMarkActive(12); }catch(e){} }
