  function seqFor(n,len,optlen){ var a=[],i,v; for(i=0;i<len;i++){ v=(n*7+i*3+Math.floor(i/2)+i*i)%optlen; a.push(v); } return a; }
  function patFor(n,cells,need){ var a=[],i,v; for(i=0;i<need;i++){ v=(n*11+i*5+i*i)%cells; while(a.indexOf(v)>=0) v=(v+1)%cells; a.push(v); } return a; }
  function stageData(n){
    var cycle=['move','numbers','colors','letters','pattern','animals','icons','arrows','shapes','mixed','numbers','colors','pattern','letters','animals','icons','arrows','move','mixed','pattern'];
    var kind=cycle[(n-1)%cycle.length];
    var diff=Math.floor((n-1)/10);
    var len=Math.min(3+Math.floor((n-1)/14),8);
    var opts=Math.min(4+Math.floor((n-1)/12),8);
    var d={kind:kind,type:'seq',len:len,opts:opts,need:len,diff:diff};
    if(kind==='move'){
      d.type='move'; d.icon='⭐'; d.name={tr:'Yıldız Yolu',en:'Star Path',de:'Sternenweg',fr:'Chemin des étoiles',ar:'طريق النجوم'}; d.text={tr:'Yıldızları topla, kapıya ulaş.',en:'Collect the stars and reach the gate.',de:'Sammle Sterne und erreiche das Tor.',fr:'Ramasse les étoiles et va à la porte.',ar:'اجمع النجوم واذهب إلى الباب.'};
      d.stars=[[4,0],[3,2],[0,3],[4,3],[2,1]].slice(0,Math.min(2+Math.floor(diff/2),5));
      d.blocks=(diff<2)?[[1,1],[2,2]]:(diff<5?[[1,1],[2,0],[2,2],[3,1]]:[[1,1],[2,0],[2,2],[3,1],[0,1],[4,2]]);
      d.gate=[4,3]; d.start=[0,2]; return d;
    }
    if(kind==='pattern'){
      d.type='pattern'; d.icon='🧩'; d.name={tr:'Parlayan Desenler',en:'Glowing Patterns',de:'Leuchtmuster',fr:'Motifs lumineux',ar:'أنماط مضيئة'}; d.text={tr:'Ayrı yerlerde parlayan kutuları aklında tut.',en:'Remember the boxes glowing in different places.',de:'Merke dir die an verschiedenen Stellen leuchtenden Felder.',fr:'Mémorise les cases qui brillent à différents endroits.',ar:'تذكّر الخانات المضيئة في أماكن مختلفة.'}; d.cells=Math.min(12+diff,20); d.need=Math.min(3+Math.floor(diff/2),8); d.pattern=patFor(n,d.cells,d.need); return d;
    }
    var set=SETS[kind]||SETS.icons; d.icon=set.icon; d.name=set.label; d.text=(kind==='mixed')?{tr:'Karışık sırayı aklında tut: sayı, renk, ikon, hayvan.',en:'Remember the mixed order: number, color, icon, animal.',de:'Merke dir die gemischte Reihe: Zahl, Farbe, Symbol, Tier.',fr:'Retiens l’ordre mélangé : nombre, couleur, icône, animal.',ar:'تذكّر الترتيب المختلط: رقم، لون، رمز، حيوان.'}:{tr:'Gösterilen sırayı aklında tut ve aynısını seç.',en:'Remember the shown order and choose the same one.',de:'Merke dir die gezeigte Reihenfolge und tippe sie nach.',fr:'Retiens l’ordre affiché puis choisis le même.',ar:'تذكّر الترتيب المعروض واختره نفسه.'};
    d.items=set.items.slice(0,Math.min(opts,set.items.length)); d.seq=seqFor(n,len,d.items.length); return d;
  }
  function current(){ return stageData(S.stage); }

