  function startFromOldIfNeeded(){ var ns=get(KEY_STAGE,null); if(ns!=null) return; var od=intval(get(OLD_DONE,'0'),0), os=intval(get(OLD_SCORE,'0'),0); if(od>=30){ set(KEY_DONE,Math.min(od,MAX_STAGE)); set(KEY_STAGE,Math.min(od+1,MAX_STAGE)); set(KEY_SCORE,os); } }
  function load(){ startFromOldIfNeeded(); S.stage=Math.max(1,Math.min(MAX_STAGE,intval(get(KEY_STAGE,'1'),1))); S.done=Math.max(0,Math.min(MAX_STAGE,intval(get(KEY_DONE,'0'),0))); S.score=Math.max(0,intval(get(KEY_SCORE,'0'),0)); prep(S.stage); }
  function save(){ set(KEY_STAGE,S.stage); set(KEY_DONE,S.done); set(KEY_SCORE,S.score); }
  function reset(doRender){ S.stage=1; S.done=0; S.score=0; prep(1); save(); if(doRender) render(); }
  function prep(n){ var a=stageData(n); S.stage=Math.max(1,Math.min(MAX_STAGE,n)); S.x=(a.start&&a.start[0])||0; S.y=(a.start&&a.start[1])||2; S.count=0; S.items={}; S.msg=tx('levelStart'); S.step=0; S.preview=0; S.flash=-1; S.picks={}; S.gateOpen=false; S.busy=0; S.completed=0; S.started=0; }

  function headHtml(){ return '<div class="v17-head"><div class="v17-title"><div class="ico">🏃</div><div><h2>'+esc(tx('title'))+'</h2><div class="v17-sub">'+esc(tx('sub'))+'</div></div></div><div class="v17-stats"><div class="v17-pill">🎮 '+esc(tx('chapter'))+': '+S.stage+'/'+MAX_STAGE+'</div><div class="v17-pill">✅ '+esc(tx('done'))+': '+S.done+'</div><div class="v17-pill">⭐ '+esc(tx('score'))+': '+S.score+'</div></div></div>'; }
  function stepsHtml(){ var a=stageData(S.stage), total=(a.type==='pattern'?a.pattern.length:(a.type==='seq'?a.seq.length:((a.stars&&a.stars.length)||0))), i,h='<div class="v17-steps">'; for(i=0;i<total;i++) h+='<button class="v17-step '+(i<S.step?'on':'')+'">'+(i+1)+'</button>'; return h+'</div>'; }
  function isBlock(a,x,y){ var i,b=a.blocks||[]; for(i=0;i<b.length;i++) if(b[i][0]===x&&b[i][1]===y) return true; return false; }
  function starAt(a,x,y){ var i,k,s=a.stars||[]; for(i=0;i<s.length;i++){ k=keyFor(s[i][0],s[i][1]); if(s[i][0]===x&&s[i][1]===y&&!S.items[k]) return i; } return -1; }
  function moveHtml(a){ var x,y,cls,k,star,g,h='<div class="v17-grid">'; for(y=0;y<4;y++){ for(x=0;x<5;x++){ cls='v17-cell'; if(isBlock(a,x,y)) cls+=' block'; g=a.gate||[4,3]; if(x===g[0]&&y===g[1]) cls+=' gate'; if(x===S.x&&y===S.y) cls+=' oki'; star=starAt(a,x,y); k=keyFor(x,y); h+='<button class="'+cls+'" onclick="evV48S17TapCell('+x+','+y+')">'; if(x===S.x&&y===S.y) h+='<span class="v17-oki">🤖</span><span class="v17-label">Oki</span>'; else if(star>=0) h+='⭐'; else if(x===g[0]&&y===g[1]) h+='🚪'; h+='</button>'; } } return h+'</div>'; }
  function posStyle(i,total){ var p=[ [12,18],[34,12],[58,18],[78,28],[66,54],[42,62],[20,52],[12,36],[50,36],[82,50] ]; var q=p[i%p.length]; if(total>8&&i>=8){ q=[20+(i*13)%62, 22+(i*17)%46]; } return 'left:'+q[0]+'%;top:'+q[1]+'%;'; }
  function seqHtml(a){ var i,idx,txt,h='<div class="v17-field"><div class="v17-tag midtag">'+esc(a.icon)+' '+esc(localized(a.name))+'</div>'; for(i=0;i<a.seq.length;i++){ idx=a.seq[i]; txt=(S.preview&&(S.flash===i||S.flash<0))?a.items[idx]:(i<S.step?'✓':''); h+='<div class="v17-slot '+(S.preview&&S.flash===i?'lit':'')+'" style="'+posStyle(i,a.seq.length)+'">'+esc(txt)+'</div>'; } h+='<div class="v17-target">'+esc(tx('target'))+': '+S.step+'/'+a.seq.length+'</div></div>'; return h; }
  function patHtml(a){ var i,lit,txt,h='<div class="v17-field"><div class="v17-tag midtag">'+esc(a.icon)+' '+esc(localized(a.name))+'</div>'; for(i=0;i<a.cells;i++){ lit=(S.preview&&a.pattern.indexOf(i)>=0)||S.picks[i]; txt=S.picks[i]?'✓':''; h+='<button class="v17-slot '+(lit?'lit':'')+'" style="'+posStyle(i,a.cells)+'" onclick="evV48S17Pat('+i+')">'+esc(txt)+'</button>'; } h+='<div class="v17-target">'+esc(tx('target'))+': '+S.step+'/'+a.pattern.length+'</div></div>'; return h; }
