  function panelHtml(){ var a=stageData(S.stage), hint=(a.type==='pattern'?tx('patHint'):(a.type==='move'?tx('moveHint'):(a.kind==='mixed'?tx('mixHint'):tx('seqHint')))); return '<div class="v17-panel"><div class="v17-paneltop">🎯 '+esc(tx('chapter'))+' '+S.stage+'</div><h3>'+esc(localized(a.name))+'</h3><p>'+esc(localized(a.text))+'</p>'+stepsHtml()+'<div class="v17-msg">'+esc(S.msg||hint)+'</div>'+optionsHtml(a)+'<div class="v17-bottom"><button class="v17-btn gray" onclick="evV48S17Reset()">↻ '+esc(tx('reset'))+'</button><button class="v17-btn gray" onclick="evV48S17Close()">× '+esc(tx('close'))+'</button></div></div>'; }
