  function pick(i,noRender){ var a=stageData(S.stage); if(a.type!=='seq'||S.busy) return; if(i===a.seq[S.step]){ S.step++; S.score+=70+S.stage; S.msg='✅ '+S.step+'/'+a.seq.length; if(S.step>=a.seq.length){ complete(noRender); return; } } else { S.step=0; S.score=Math.max(0,S.score-30); S.msg=tx('bad'); } if(!noRender) render(); }
  function pat(i,noRender){ var a=stageData(S.stage); if(a.type!=='pattern'||S.busy) return; if(a.pattern.indexOf(i)>=0&&!S.picks[i]){ S.picks[i]=1; S.step++; S.score+=80+S.stage; S.msg='✅ '+S.step+'/'+a.pattern.length; if(S.step>=a.pattern.length){ complete(noRender); return; } } else { S.picks={}; S.step=0; S.score=Math.max(0,S.score-30); S.msg=tx('bad'); } if(!noRender) render(); }
  function move(dx,dy,noRender){ var a=stageData(S.stage), nx=S.x+dx, ny=S.y+dy, star, g; if(a.type!=='move'||S.busy) return; if(nx<0||nx>4||ny<0||ny>3||isBlock(a,nx,ny)){ S.msg=tx('bad'); if(!noRender) render(); return; } S.x=nx; S.y=ny; star=starAt(a,nx,ny); if(star>=0){ S.items[keyFor(nx,ny)]=1; S.count++; S.step=S.count; S.score+=100+S.stage; S.msg='⭐ '+S.count+'/'+((a.stars&&a.stars.length)||0); if(a.stars&&S.count>=a.stars.length){ S.gateOpen=true; S.msg='✅ '+tx('go'); } } g=a.gate||[4,3]; if(nx===g[0]&&ny===g[1]){ if(S.gateOpen){ complete(noRender); return; } S.msg=tx('need'); } if(!noRender) render(); }
