  var MOT={tr:['Bravo {name}, çok iyi hatırladın!','Harika dikkat! Oki alkışlıyor.','Müthiş! Bir adım daha güçlendin.','Süper hafıza! Devam edelim.','Bu tam bir kaşif hamlesi!','Oki seninle gurur duydu!','Çok iyi gördün, doğru sırayı yakaladın.','Zihnin ısındı, yeni görev geliyor.','Helal olsun {name}, temiz iş!','Dikkatini topladın, sonuç geldi.'],en:['Bravo {name}, great memory!','Great focus! Oki is clapping.','Awesome! One step stronger.','Super memory! Let’s continue.','That was a true explorer move!','Oki is proud of you!'],de:['Bravo {name}, gut gemerkt!','Tolle Konzentration! Oki klatscht.','Super! Ein Schritt stärker.','Starkes Gedächtnis! Weiter geht’s.'],fr:['Bravo {name}, belle mémoire !','Super attention ! Oki applaudit.','Excellent ! Encore plus fort.','Très bonne mémoire ! On continue.'],ar:['أحسنت يا {name}! ذاكرة رائعة.','تركيز ممتاز! أوكي يصفق.','رائع! خطوة أقوى.','ذاكرة ممتازة! نكمل.']};
  var BADGES=[item('Dikkat Rozeti','Focus Badge','Aufmerksamkeitsabzeichen','Badge attention','شارة التركيز'),item('Hafıza Rozeti','Memory Badge','Gedächtnisabzeichen','Badge mémoire','شارة الذاكرة'),item('Renk Ustası','Color Master','Farbenmeister','Maître couleurs','خبير الألوان'),item('Harf Kaşifi','Letter Explorer','Buchstabenentdecker','Explorateur lettres','مستكشف الحروف'),item('Desen Ustası','Pattern Master','Mustermeister','Maître motifs','خبير الأنماط'),item('Hayvan Dostu','Animal Friend','Tierfreund','Ami des animaux','صديق الحيوانات'),item('Hızlı Zihin','Quick Mind','Schneller Kopf','Esprit rapide','عقل سريع'),item('Sıra Ustası','Order Master','Reihenmeister','Maître des suites','خبير الترتيب'),item('Büyük Kaşif','Great Explorer','Großer Entdecker','Grand explorateur','المستكشف الكبير'),item('Akıl Şampiyonu','Mind Champion','Denk-Champion','Champion mémoire','بطل الذاكرة'),item('Yeni Sezon Kaşifi','New Season Explorer','Neue-Saison-Entdecker','Explorateur nouvelle saison','مستكشف موسم جديد')];

  function seqFor(n,len,optlen){ var a=[],i,v; for(i=0;i<len;i++){ v=(n*7+i*5+Math.floor(i/2)+i*i)%optlen; a.push(v); } return a; }
  function patFor(n,cells,need){ var a=[],i,v; for(i=0;i<need;i++){ v=(n*11+i*7+i*i)%cells; while(a.indexOf(v)>=0) v=(v+1)%cells; a.push(v); } return a; }
  function diffFor(n){ var block=Math.floor((n-1)/10), pos=(n-1)%10, wave=(pos<2?-1:(pos<6?0:1)); var d=Math.floor(block/2)+wave; if(d<0)d=0; return d; }
  function stageData(n){
    var season=n>100?2:1, local=((n-1)%100)+1, cycle=(season===1?SEASON1:SEASON2), kind=cycle[(local-1)%cycle.length], diff=diffFor(n), pos=(local-1)%10, len, opts, d, set, pool;
    len=Math.min(3+Math.floor(diff/2)+(pos>6?1:0),9); opts=Math.min(4+Math.floor(diff/2),9);
    d={kind:kind,type:'seq',len:len,opts:opts,need:len,season:season};
    if(kind==='move'){
      d.type='move'; d.icon='⭐'; d.name=item(season===1?'Yıldız Yolu':'Keşif Yolu','Star Path','Sternenweg','Chemin des étoiles','طريق النجوم'); d.text=item('Yıldızları topla, kapıya ulaş.','Collect the stars and reach the gate.','Sammle Sterne und erreiche das Tor.','Ramasse les étoiles et va à la porte.','اجمع النجوم واذهب إلى الباب.');
      d.stars=[[4,0],[3,2],[0,3],[4,3],[2,1],[1,0]].slice(0,Math.min(2+Math.floor(diff/2),6));
      d.blocks=(diff<2)?[[1,1],[2,2]]:(diff<5?[[1,1],[2,0],[2,2],[3,1]]:[[1,1],[2,0],[2,2],[3,1],[0,1],[4,2]]);
      d.gate=[4,3]; d.start=[0,2]; return d;
    }
    if(kind==='pattern'){
      d.type='pattern'; d.icon='🧩'; d.name=item('Parlayan Desenler','Glowing Patterns','Leuchtmuster','Motifs lumineux','أنماط مضيئة'); d.text=item('Ayrı yerlerde parlayan kutuları aklında tut.','Remember the boxes glowing in different places.','Merke dir die leuchtenden Felder.','Mémorise les cases lumineuses.','تذكّر الخانات المضيئة.'); d.cells=Math.min(12+Math.floor(diff/2),24); d.need=Math.min(3+Math.floor(diff/2)+(pos>7?1:0),9); d.pattern=patFor(n,d.cells,d.need); return d;
    }
    if(kind==='mixed'||kind==='mixed2'){
      pool=[].concat(SETS.numbers.items,SETS.colors.items.slice(0,4),SETS.animals.items.slice(0,4),SETS.school.items.slice(0,4),SETS.devices.items.slice(0,3),SETS.foods.items.slice(0,3),SETS.shapes.items.slice(0,5));
      d.icon='🧠'; d.name=item(season===1?'Karışık Hafıza':'Yeni Sezon Karışımı','Mixed Memory','Gemischtes Merken','Mémoire mixte','ذاكرة مختلطة'); d.text=item('Sayı, renk, şekil ve nesneleri karıştırmadan sırayla seç.','Choose numbers, colors, shapes and objects in order.','Wähle Zahlen, Farben, Formen und Dinge der Reihe nach.','Choisis nombres, couleurs, formes et objets dans l’ordre.','اختر الأرقام والألوان والأشكال والأشياء بالترتيب.'); d.items=pool.slice(0,Math.min(opts+4,pool.length)); d.seq=seqFor(n,len,d.items.length); return d;
    }
    set=SETS[kind]||SETS.icons; d.icon=set.icon; d.name=set.label; d.text=item('Gösterilen sırayı aklında tut ve aynısını seç.','Remember the shown order and choose the same one.','Merke dir die gezeigte Reihenfolge und tippe sie nach.','Retiens l’ordre affiché puis choisis le même.','تذكّر الترتيب المعروض واختره نفسه.'); d.items=set.items.slice(0,Math.min(opts,set.items.length)); d.seq=seqFor(n,len,d.items.length); return d;
  }
  function current(){ return stageData(S.stage); }

  function overlay(){ var o=document.getElementById('v48s18-oki'); if(!o){ o=document.createElement('div'); o.id='v48s18-oki'; document.body.appendChild(o); } return o; }
  function injectStyle(){ if(document.getElementById('v48s18-style')) return; var s=document.createElement('style'); s.id='v48s18-style'; s.textContent=`body[data-v48s18-oki="1"]{overflow:hidden!important}#v48s18-oki{position:fixed;inset:0;z-index:999999;background:linear-gradient(135deg,#06192a,#063b2f 55%,#06192a);display:none;align-items:center;justify-content:center;font-family:inherit;color:#fff}#v18-shell{width:calc(100vw - 18px);height:calc(100vh - 18px);box-sizing:border-box;border:1px solid rgba(255,255,255,.18);border-radius:22px;background:linear-gradient(135deg,rgba(8,47,73,.82),rgba(6,78,59,.84));box-shadow:0 18px 58px rgba(0,0,0,.42);padding:10px 12px;overflow:hidden;position:relative}#v18-shell.theme-ocean{background:linear-gradient(135deg,rgba(7,89,133,.85),rgba(14,116,144,.86))}#v18-shell.theme-candy{background:linear-gradient(135deg,rgba(112,26,117,.80),rgba(236,72,153,.45),rgba(6,78,59,.65))}#v18-shell.theme-night{background:linear-gradient(135deg,rgba(15,23,42,.94),rgba(49,46,129,.68),rgba(2,44,34,.80))}#v18-shell.theme-sun{background:linear-gradient(135deg,rgba(120,53,15,.72),rgba(21,128,61,.72),rgba(14,116,144,.58))}#v18-shell:before{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.04) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.04) 1px,transparent 1px);background-size:64px 64px;pointer-events:none}.v18-head{height:62px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:center;position:relative;z-index:1}.v18-title{display:flex;align-items:center;gap:10px;min-width:0}.v18-title .ico{font-size:34px}.v18-title h2{font-size:clamp(28px,3.2vw,42px);line-height:.96;margin:0;font-weight:950;letter-spacing:-.6px}.v18-sub{display:inline-block;margin-top:4px;padding:5px 12px;border-radius:999px;background:rgba(14,165,233,.30);border:1px solid rgba(125,211,252,.34);font-weight:900;font-size:clamp(12px,1.05vw,16px);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:660px}.v18-stats{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.v18-pill{border-radius:999px;background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.22);padding:7px 12px;font-size:15px;font-weight:950;box-shadow:inset 0 1px 0 rgba(255,255,255,.16)}.v18-main{height:calc(100% - 70px);display:grid;grid-template-columns:minmax(0,1.12fr) minmax(365px,.88fr);gap:10px;position:relative;z-index:1}.v18-play,.v18-panel{min-height:0;overflow:hidden;border-radius:20px;border:1px solid rgba(255,255,255,.16);background:rgba(3,41,48,.42);box-shadow:inset 0 1px 0 rgba(255,255,255,.10);position:relative}.v18-play{padding:10px}.v18-panel{padding:11px;display:flex;flex-direction:column;gap:7px}.v18-tag{display:inline-flex;align-items:center;gap:7px;border-radius:999px;padding:7px 12px;background:rgba(2,6,23,.72);border:1px solid rgba(255,255,255,.15);font-weight:950;font-size:15px}.v18-board{height:calc(100% - 38px);display:flex;align-items:center;justify-content:center;overflow:hidden}.v18-grid{width:min(74%,560px);height:min(54vh,330px);display:grid;grid-template-columns:repeat(5,1fr);grid-template-rows:repeat(4,1fr);gap:8px;transform:skewY(-7deg) rotate(-3deg) scale(.86);transform-origin:center center;padding:14px;border-radius:22px;background:linear-gradient(135deg,rgba(14,165,233,.14),rgba(34,197,94,.18));box-shadow:14px 20px 0 rgba(0,0,0,.22)}.v18-cell{border:0;border-radius:14px;background:linear-gradient(145deg,#22c55e,#12834f);box-shadow:0 7px 0 rgba(0,0,0,.26),inset 0 2px 0 rgba(255,255,255,.18);font-size:26px;font-weight:950;color:#031827;position:relative}.v18-cell.block{background:linear-gradient(145deg,#64748b,#334155)}.v18-cell.gate{background:linear-gradient(145deg,#facc15,#f97316);box-shadow:0 0 26px rgba(250,204,21,.50),0 7px 0 rgba(0,0,0,.26)}.v18-cell.oki{outline:4px solid rgba(255,255,255,.95);background:linear-gradient(145deg,#dbeafe,#a7f3d0);transform:translateY(-5px)}.v18-oki{font-size:34px;display:block}.v18-label{position:absolute;left:50%;bottom:-24px;transform:translateX(-50%) skewY(7deg) rotate(3deg);padding:3px 9px;border-radius:999px;background:#dffcff;color:#042f2e;font-weight:950;font-size:13px}.v18-seqstage{width:min(88%,630px);min-height:190px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;border-radius:24px;background:linear-gradient(135deg,rgba(15,23,42,.42),rgba(34,197,94,.17));box-shadow:0 14px 0 rgba(0,0,0,.18);padding:18px}.v18-runway{display:flex;gap:9px;flex-wrap:wrap;justify-content:center;max-width:100%}.v18-token{min-width:58px;min-height:52px;border-radius:16px;border:2px solid rgba(255,255,255,.50);background:linear-gradient(145deg,#dcfce7,#bae6fd);color:#082f49;display:flex;align-items:center;justify-content:center;text-align:center;font-weight:950;font-size:clamp(18px,2vw,28px);padding:6px 9px;box-shadow:0 8px 0 rgba(0,0,0,.20)}.v18-token.small{font-size:15px}.v18-token.flash{outline:4px solid #fde047;box-shadow:0 0 32px rgba(250,204,21,.78),0 8px 0 rgba(0,0,0,.20);transform:translateY(-4px)}.v18-token.hide{color:transparent;text-shadow:0 0 0 transparent;background:rgba(255,255,255,.14)}.v18-pattern{display:grid;grid-template-columns:repeat(6,52px);grid-auto-rows:44px;gap:7px}.v18-patcell{border:0;border-radius:14px;background:linear-gradient(145deg,#064e3b,#059669);box-shadow:0 7px 0 rgba(0,0,0,.23);font-size:24px;color:#fff}.v18-patcell.show,.v18-patcell.pick{background:linear-gradient(145deg,#fde047,#fb923c);box-shadow:0 0 28px rgba(250,204,21,.72),0 7px 0 rgba(0,0,0,.23)}.v18-paneltop{border-radius:15px;background:rgba(2,6,23,.72);padding:8px 12px;font-size:17px;font-weight:950}.v18-panel h3{margin:0;color:#fde68a;font-size:clamp(24px,2.2vw,34px);line-height:1.02}.v18-panel p{margin:0;font-size:clamp(14px,1.25vw,19px);line-height:1.15;font-weight:900}.v18-steps{display:flex;gap:6px}.v18-step{flex:1;border-radius:10px;padding:6px 0;text-align:center;background:rgba(255,255,255,.16);font-weight:950;font-size:15px}.v18-step.on{background:#22c55e;color:#052e16}.v18-msg{border-radius:13px;background:rgba(2,6,23,.70);padding:8px 10px;font-weight:900;font-size:15px;min-height:20px}.v18-reward{border-radius:15px;padding:9px 11px;background:linear-gradient(135deg,rgba(250,204,21,.24),rgba(34,197,94,.22));border:1px solid rgba(250,204,21,.45);font-weight:950;color:#fef3c7;font-size:15px}.v18-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;min-height:0}.v18-choice,.v18-btn{border:0;border-radius:14px;padding:9px 11px;font-size:16px;font-weight:950;cursor:pointer;box-shadow:0 6px 0 rgba(0,0,0,.20);line-height:1.05}.v18-choice{background:linear-gradient(145deg,#dcfce7,#bae6fd);color:#052e2b;min-height:42px}.v18-choice:active,.v18-btn:active{transform:translateY(3px);box-shadow:0 3px 0 rgba(0,0,0,.20)}.v18-actions{display:flex;gap:8px;flex-wrap:wrap}.v18-btn.green{background:linear-gradient(145deg,#86efac,#22c55e);color:#052e16}.v18-btn.gold{background:linear-gradient(145deg,#fde047,#fb923c);color:#111827}.v18-btn.gray{background:linear-gradient(145deg,#cbd5e1,#94a3b8);color:#0f172a}.v18-btn.blue{background:linear-gradient(145deg,#bae6fd,#38bdf8);color:#082f49}.v18-dpad{display:grid;grid-template-columns:54px 54px 54px;grid-template-areas:". up ." "left down right";gap:6px;justify-content:center}.v18-dpad .up{grid-area:up}.v18-dpad .left{grid-area:left}.v18-dpad .down{grid-area:down}.v18-dpad .right{grid-area:right}.v18-dpad .v18-btn{min-height:48px}.v18-bottom{margin-top:auto;display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.v18-bottom .v18-btn{min-height:46px}.v18-progress{font-size:13px;opacity:.88}.v18-confetti{position:absolute;inset:0;pointer-events:none;background:radial-gradient(circle at 10% 20%,rgba(250,204,21,.9),transparent 5%),radial-gradient(circle at 30% 55%,rgba(34,197,94,.8),transparent 5%),radial-gradient(circle at 65% 25%,rgba(56,189,248,.85),transparent 6%),radial-gradient(circle at 88% 62%,rgba(244,114,182,.85),transparent 6%);animation:v18pop .85s ease-out both}.v18-badgepop{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:5;border-radius:28px;padding:18px 26px;background:linear-gradient(145deg,#fde047,#fb923c);color:#111827;font-weight:950;font-size:clamp(22px,3vw,42px);box-shadow:0 20px 50px rgba(0,0,0,.35);text-align:center;max-width:82%}@keyframes v18pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:scale(1)}}@media(max-height:820px){#v18-shell{padding:8px 10px}.v18-head{height:54px}.v18-title .ico{font-size:28px}.v18-title h2{font-size:clamp(24px,2.8vw,36px)}.v18-sub{font-size:12px;padding:4px 10px;max-width:590px}.v18-pill{font-size:13px;padding:6px 10px}.v18-main{height:calc(100% - 60px);grid-template-columns:minmax(0,1.12fr) minmax(350px,.88fr)}.v18-play{padding:8px}.v18-panel{padding:9px;gap:5px}.v18-tag{font-size:13px;padding:6px 10px}.v18-board{height:calc(100% - 32px)}.v18-grid{width:min(70%,500px);height:min(50vh,290px);gap:7px;padding:12px;transform:skewY(-7deg) rotate(-3deg) scale(.80)}.v18-cell{border-radius:12px;font-size:23px}.v18-oki{font-size:29px}.v18-label{font-size:11px;bottom:-20px}.v18-seqstage{min-height:150px;padding:14px;gap:10px}.v18-token{min-width:48px;min-height:44px;font-size:18px}.v18-token.small{font-size:13px}.v18-pattern{grid-template-columns:repeat(6,44px);grid-auto-rows:36px;gap:5px}.v18-patcell{font-size:20px;border-radius:11px}.v18-paneltop{font-size:15px;padding:6px 10px}.v18-panel h3{font-size:clamp(22px,2vw,30px)}.v18-panel p{font-size:14px}.v18-step{font-size:13px;padding:5px 0}.v18-msg,.v18-reward{font-size:13px;padding:6px 8px;min-height:18px}.v18-choice,.v18-btn{font-size:14px;padding:7px 9px;border-radius:12px}.v18-choice{min-height:36px}.v18-dpad{grid-template-columns:46px 46px 46px;gap:5px}.v18-dpad .v18-btn{min-height:40px}.v18-bottom .v18-btn{min-height:38px}.v18-progress{font-size:12px}}@media(max-width:980px){#v18-shell{padding:8px}.v18-head{height:56px}.v18-title h2{font-size:27px}.v18-sub{max-width:420px}.v18-main{height:calc(100% - 62px);grid-template-columns:1fr 330px;gap:7px}.v18-panel{padding:8px}.v18-choice,.v18-btn{font-size:13px;padding:7px}.v18-grid{gap:5px;padding:10px;transform:skewY(-7deg) rotate(-3deg) scale(.76)}.v18-token{min-width:42px;min-height:38px;font-size:17px}.v18-pattern{grid-template-columns:repeat(4,46px);grid-auto-rows:38px;gap:5px}}`; document.head.appendChild(s); }

  function load(){ S.stage=intval(get(KEY_STAGE,'1'),1); S.done=intval(get(KEY_DONE,'0'),0); S.score=intval(get(KEY_SCORE,'0'),0); S.theme=get(KEY_THEME,'forest'); if(THEMES.indexOf(S.theme)<0) S.theme='forest'; if(S.stage<1||S.stage>MAX_STAGE) S.stage=1; prep(S.stage); }
  function save(){ set(KEY_STAGE,S.stage); set(KEY_DONE,S.done); set(KEY_SCORE,S.score); set(KEY_THEME,S.theme); }
  function reset(renderIt){ S.stage=1; S.done=0; S.score=0; S.reward=''; S.celebrate=0; S.badge=''; prep(1); save(); if(renderIt) render(); }
  function prep(n){ var a=stageData(n); S.stage=n; S.x=a.start?a.start[0]:0; S.y=a.start?a.start[1]:2; S.count=0; S.items={}; S.picks={}; S.step=0; S.preview=0; S.flash=-1; S.gateOpen=false; S.busy=0; S.completed=0; S.wrong=0; S.msg=(a.type==='seq'?tx('seqHint'):(a.type==='pattern'?tx('patHint'):tx('moveHint'))); }
  function themeNext(){ var i=THEMES.indexOf(S.theme); if(i<0)i=0; S.theme=THEMES[(i+1)%THEMES.length]; save(); render(); }
  function themeName(){ return ({forest:'Yeşil',ocean:'Okyanus',candy:'Şeker',night:'Gece',sun:'Güneş'})[S.theme]||'Tema'; }

  function headHtml(){ return '<div class="v18-head"><div class="v18-title"><div class="ico">🏃</div><div><h2>'+esc(tx('title'))+'</h2><div class="v18-sub">'+esc(tx('sub'))+'</div></div></div><div class="v18-stats"><div class="v18-pill">🎮 '+esc(tx('chapter'))+': '+S.stage+'/'+MAX_STAGE+'</div><div class="v18-pill">✅ '+esc(tx('done'))+': '+S.done+'</div><div class="v18-pill">⭐ '+esc(tx('score'))+': '+S.score+'</div><div class="v18-pill">🎨 '+esc(themeName())+'</div></div></div>'; }
  function stepsHtml(){ var a=stageData(S.stage), i, total=(a.type==='seq')?a.seq.length:(a.type==='pattern'?a.pattern.length:(a.stars?a.stars.length:3)), h='<div class="v18-steps">'; if(total>9) total=9; for(i=0;i<total;i++) h+='<div class="v18-step '+(i<S.step||i<S.count?'on':'')+'">'+(i+1)+'</div>'; return h+'</div>'; }
  function isBlock(a,x,y){ var i,b=a.blocks||[]; for(i=0;i<b.length;i++) if(b[i][0]===x&&b[i][1]===y) return true; return false; }
  function starAt(a,x,y){ var i,s=a.stars||[]; for(i=0;i<s.length;i++) if(s[i][0]===x&&s[i][1]===y&&!S.items[keyFor(x,y)]) return i; return -1; }
  function playHtml(){ var a=stageData(S.stage); if(a.type==='move') return moveHtml(a); if(a.type==='pattern') return patternHtml(a); return seqHtml(a); }
  function textItem(v){ return esc(loc(v)); }
  function moveHtml(a){ var x,y,h='<div class="v18-grid">', cls, content, g=a.gate||[4,3]; for(y=0;y<4;y++){ for(x=0;x<5;x++){ cls='v18-cell'; content=''; if(isBlock(a,x,y)){ cls+=' block'; } if(starAt(a,x,y)>=0) content=a.icon||'⭐'; if(g[0]===x&&g[1]===y){ cls+=' gate'; content=S.gateOpen?'🚪':'🔒'; } if(S.x===x&&S.y===y){ cls+=' oki'; content='<span class="v18-oki">🤖</span><span class="v18-label">Oki</span>'; } h+='<button class="'+cls+'" onclick="evV48S18TapCell('+x+','+y+')">'+content+'</button>'; }} return h+'</div>'; }
  function seqHtml(a){ var i,txt,h='<div class="v18-seqstage"><div class="v18-tag">'+esc(a.icon)+' '+esc(loc(a.name))+'</div><div class="v18-runway">'; for(i=0;i<a.seq.length;i++){ txt=loc(a.items[a.seq[i]]); h+='<div class="v18-token '+(String(txt).length>5?'small ':'')+((S.preview||S.flash===i)?'':'hide')+' '+(S.flash===i?'flash':'')+'">'+esc(txt)+'</div>'; } h+='</div><div class="v18-progress">'+esc(tx('target'))+': '+S.step+'/'+a.seq.length+'</div></div>'; return h; }
  function patternHtml(a){ var i,h='<div class="v18-seqstage"><div class="v18-tag">🧩 '+esc(loc(a.name))+'</div><div class="v18-pattern">'; for(i=0;i<a.cells;i++){ h+='<button class="v18-patcell '+((S.preview&&a.pattern.indexOf(i)>=0)?'show ':'')+(S.picks[i]?'pick':'')+'" onclick="evV48S18Pat('+i+')">'+((S.preview&&a.pattern.indexOf(i)>=0)||S.picks[i]?'✨':'')+'</button>'; } h+='</div><div class="v18-progress">'+esc(tx('target'))+': '+S.step+'/'+a.pattern.length+'</div></div>'; return h; }
  function stageHtml(){ return '<div class="v18-play"><div class="v18-tag">'+esc(stageData(S.stage).icon)+' '+esc(loc(stageData(S.stage).name))+'</div><div class="v18-board">'+playHtml()+'</div>'+(S.completed?'<div class="v18-confetti"></div>':'')+(S.celebrate?'<div class="v18-badgepop">🏆<br>'+esc(S.badge||tx('badge'))+'</div>':'')+'</div>'; }
  function optionsHtml(a){ var i,h=''; if(a.type==='seq'){ h+='<div class="v18-options">'; for(i=0;i<a.items.length;i++) h+='<button class="v18-choice" onclick="evV48S18Pick('+i+')">'+textItem(a.items[i])+'</button>'; h+='</div><div class="v18-actions"><button class="v18-btn gold" onclick="evV48S18Show()">👀 '+esc(tx('watch'))+'</button></div>'; } else if(a.type==='pattern'){ h+='<div class="v18-actions"><button class="v18-btn gold" onclick="evV48S18Show()">👀 '+esc(tx('watch'))+'</button></div>'; } else { h+='<div class="v18-dpad"><button class="v18-btn green up" onclick="evV48S18Move(0,-1)">↑</button><button class="v18-btn green left" onclick="evV48S18Move(-1,0)">←</button><button class="v18-btn green down" onclick="evV48S18Move(0,1)">↓</button><button class="v18-btn green right" onclick="evV48S18Move(1,0)">→</button></div><div class="v18-actions"><button class="v18-btn gold" onclick="evV48S18Gate()">🚪 '+esc(tx('go'))+'</button></div>'; } return h; }
  function panelHtml(){ var a=stageData(S.stage), season=a.season||1; return '<div class="v18-panel"><div class="v18-paneltop">🎯 '+esc(tx('chapter'))+' '+S.stage+' · '+esc(tx('season'))+' '+season+'</div><h3>'+esc(loc(a.name))+'</h3><p>'+esc(loc(a.text))+'</p>'+stepsHtml()+'<div class="v18-msg">'+esc(S.msg)+'</div>'+(S.reward?'<div class="v18-reward">'+esc(S.reward)+'</div>':'')+optionsHtml(a)+'<div class="v18-bottom"><button class="v18-btn gray" onclick="evV48S18Reset()">↻ '+esc(tx('reset'))+'</button><button class="v18-btn blue" onclick="evV48S18Theme()">🎨 '+esc(tx('theme'))+'</button><button class="v18-btn gray" onclick="evV48S18Close()">× '+esc(tx('close'))+'</button></div></div>'; }
  function render(){ var o=overlay(); o.innerHTML='<div id="v18-shell" class="theme-'+esc(S.theme)+'">'+headHtml()+'<div class="v18-main">'+stageHtml()+panelHtml()+'</div></div>'; }

  function show(){ var a=stageData(S.stage), i=0, delay; if(timer){ clearInterval(timer); clearTimeout(timer); timer=null; } if(a.type==='seq'){ S.preview=1; S.flash=-1; render(); delay=Math.max(310,560-Math.floor(S.stage/12)*18); timer=setInterval(function(){ S.flash=i; render(); i++; if(i>a.seq.length){ clearInterval(timer); timer=null; S.flash=-1; S.preview=0; render(); } },delay); } else if(a.type==='pattern'){ S.preview=1; render(); timer=setTimeout(function(){ S.preview=0; timer=null; render(); },Math.max(900,1700+Math.min(900,a.need*130)-Math.floor(S.stage/10)*45)); } }
  function mot(){ var l=lang(), a=MOT[l]||MOT.tr, i=(S.stage*5+S.done)%a.length; return nameLine(a[i]); }
  function milestoneText(stage){ if(stage===100) return tx('hundred')+' 🏆 '+esc(loc(BADGES[9])); if(stage===200) return tx('final')+' 🏆 '+esc(loc(BADGES[10])); if(stage%10===0) return tx('ten')+' 🏅 '+loc(BADGES[((stage/10)-1)%BADGES.length]); return ''; }
  function finishStage(noRender){ var ms; if(timer){ clearInterval(timer); clearTimeout(timer); timer=null; } S.busy=1; S.completed=1; if(S.stage>S.done) S.done=S.stage; S.score+=450+S.stage*20; ms=milestoneText(S.stage); S.reward=ms||mot(); S.badge=ms?String(ms).replace(/^[^🏅🏆]*/,''):''; S.celebrate=ms?1:0; S.msg=(S.stage>=MAX_STAGE)?tx('finish'):nameLine(tx('ok')); save(); if(!noRender) render(); if(S.stage<MAX_STAGE){ if(noRender){ prep(S.stage+1); save(); } else { setTimeout(function(){ prep(S.stage+1); if(S.stage===101){ S.reward=tx('nextSeason'); S.celebrate=1; S.badge=loc(BADGES[10]); } save(); render(); },S.celebrate?1600:950); } } }
  function pick(i,noRender){ var a=stageData(S.stage); if(a.type!=='seq'||S.busy) return; if(i===a.seq[S.step]){ S.step++; S.score+=60+S.stage; S.msg='✅ '+S.step+'/'+a.seq.length; if(S.step>=a.seq.length){ finishStage(noRender); return; } } else { S.step=0; S.score=Math.max(0,S.score-25); S.wrong++; S.msg=tx('bad'); } if(!noRender) render(); }
  function pat(i,noRender){ var a=stageData(S.stage); if(a.type!=='pattern'||S.busy) return; if(a.pattern.indexOf(i)>=0&&!S.picks[i]){ S.picks[i]=1; S.step++; S.score+=70+S.stage; S.msg='✅ '+S.step+'/'+a.pattern.length; if(S.step>=a.pattern.length){ finishStage(noRender); return; } } else { S.picks={}; S.step=0; S.score=Math.max(0,S.score-25); S.wrong++; S.msg=tx('bad'); } if(!noRender) render(); }
  function move(dx,dy,noRender){ var a=stageData(S.stage), nx=S.x+dx, ny=S.y+dy, star, g; if(a.type!=='move'||S.busy) return; if(nx<0||nx>4||ny<0||ny>3||isBlock(a,nx,ny)){ S.msg=tx('bad'); if(!noRender) render(); return; } S.x=nx; S.y=ny; star=starAt(a,nx,ny); if(star>=0){ S.items[keyFor(nx,ny)]=1; S.count++; S.step=S.count; S.score+=90+S.stage; S.msg='⭐ '+S.count+'/'+((a.stars&&a.stars.length)||0); if(a.stars&&S.count>=a.stars.length){ S.gateOpen=true; S.msg='✅ '+tx('go'); } } g=a.gate||[4,3]; if(nx===g[0]&&ny===g[1]){ if(S.gateOpen){ finishStage(noRender); return; } S.msg=tx('need'); } if(!noRender) render(); }
