  function overlay(){ var o=document.getElementById('v48s22-meteor'); if(o) return o; o=document.createElement('div'); o.id='v48s22-meteor'; o.innerHTML='<div class="m20-shell"><div id="m20-sky" class="m20-sky"><div class="m20-ground"></div><div id="m20-oki" class="m20-oki">🤖</div></div><aside class="m20-side"><div><h2 class="m20-title" id="m20-title"></h2><p class="m20-sub" id="m20-sub"></p><div class="m20-sector" id="m20-sector"></div></div><div class="m20-stats"><div class="m20-stat">'+esc(tx('stage'))+'<b id="m20-level">1</b></div><div class="m20-stat">'+esc(tx('score'))+'<b id="m20-score">0</b></div><div class="m20-stat">'+esc(tx('life'))+'<b id="m20-lives">4</b></div><div class="m20-stat">'+esc(tx('energy'))+'<b id="m20-energy">5</b></div><div class="m20-stat">'+esc(tx('combo'))+'<b id="m20-combo">0</b></div></div><div class="m20-goal"><h3 id="m20-mission-title"></h3><p id="m20-goal-text"></p></div><div class="m20-progress"><div class="m20-bar" id="m20-bar"></div></div><div class="m20-msg" id="m20-msg"></div><div class="m20-controls"><div class="m20-row"><button class="m20-btn" onclick="window.evV48S22Move(-13)">◀ '+esc(tx('left'))+'</button><button class="m20-btn main" onclick="window.evV48S22Fire()">⚡ '+esc(tx('fire'))+'</button><button class="m20-btn" onclick="window.evV48S22Move(13)">'+esc(tx('right'))+' ▶</button></div><div class="m20-row"><button class="m20-btn main" onclick="window.evV48S22Shield()">🛡️ '+esc(tx('shield'))+'</button><button class="m20-btn dark" onclick="window.evV48S22Pause()" id="m20-pause">'+esc(tx('pause'))+'</button><button class="m20-btn dark" onclick="window.evV48S22Theme()">🎨 Tema</button></div><div class="m20-row"><button class="m20-btn warn" onclick="window.evV48S22Reset()">'+esc(tx('reset'))+'</button><button class="m20-btn dark" onclick="window.evV48S22Mega()">🌟 Mega</button><button class="m20-btn dark" onclick="window.evV48S22Close()">'+esc(tx('close'))+'</button></div></div></aside></div>'; document.body.appendChild(o); return o; }
  function load(){ try{ var x=JSON.parse(localStorage.getItem(KEY)||'{}'); if(x&&x.level) S.level=parseInt(x.level,10)||1; if(x&&x.score) S.score=parseInt(x.score,10)||0; if(x&&x.best) S.best=parseInt(x.best,10)||0; if(x&&x.theme!=null) S.theme=parseInt(x.theme,10)||0; }catch(e){} }
  function save(){ try{ if(S.score>S.best) S.best=S.score; localStorage.setItem(KEY,JSON.stringify({level:S.level,score:S.score,best:S.best,theme:S.theme})); }catch(e){} }
  function applyTheme(){ var o=document.getElementById('v48s22-meteor'), t=THEMES[S.theme%THEMES.length], s=sectorFor(S.level); if(!o) return; if(S.theme===0){ o.style.setProperty('--m20-bg1',s.bg1); o.style.setProperty('--m20-bg2',s.bg2); o.style.setProperty('--m20-accent',s.accent); } else { o.style.setProperty('--m20-bg1',t.bg1); o.style.setProperty('--m20-bg2',t.bg2); o.style.setProperty('--m20-accent',t.accent); } }
  function mission(){ if(!S.mission) S.mission=missionFor(S.level); return S.mission; }
  function difficulty(){ var n=S.level, s=sectorFor(n), local=((n-1)%50)+1, wave=Math.floor((local-1)/10), rest=(local===1?1:0); return {spawn:Math.max(300,900-wave*60-Math.min(160,s.idx*28)+rest*90),speed:1.0+wave*.16+Math.min(1.15,s.idx*.16)+Math.min(.55,local*.008),maxItems:4+Math.min(8,wave+s.idx)}; }
  function beginStage(){ stop(); clearItems(); S.mission=missionFor(S.level); S.need=S.mission.need; S.got=0; S.lives=4; S.combo=0; S.seqAt=0; S.boss=0; S.energy=S.maxEnergy; S.double=false; S.magnet=false; S.slow=false; S.megaReady=false; S.msg=tx('ready'); S.complete=false; S.paused=false; S.active=true; S.okiX=50; render(); startTimers(); }
  function startTimers(){ stop(); S.tickTimer=setInterval(tick,40); S.spawnTimer=setInterval(spawn, difficulty().spawn); spawn(); spawn(); }
  function stop(){ if(S.tickTimer){ clearInterval(S.tickTimer); S.tickTimer=null; } if(S.spawnTimer){ clearInterval(S.spawnTimer); S.spawnTimer=null; } }
  function clearItems(){ var i; for(i=0;i<S.items.length;i++){ try{ if(S.items[i].el&&S.items[i].el.parentNode) S.items[i].el.parentNode.removeChild(S.items[i].el); }catch(e){} } S.items=[]; for(i=0;i<S.shots.length;i++){ try{ if(S.shots[i].el&&S.shots[i].el.parentNode) S.shots[i].el.parentNode.removeChild(S.shots[i].el); }catch(e3){} } S.shots=[]; var sky=document.getElementById('m20-sky'); if(sky){ var old=sky.querySelectorAll('.m20-complete,.m20-over,.m20-confetti'); for(i=0;i<old.length;i++){ try{ old[i].parentNode.removeChild(old[i]); }catch(e2){} } } }
  function render(){ var m=mission(), o=document.getElementById('v48s22-meteor'), t=lang(), arr=MOT[t]||MOT.tr, p, sec=sectorFor(S.level); applyTheme(); var e; e=document.getElementById('m20-title'); if(e) e.textContent=tx('title'); e=document.getElementById('m20-sub'); if(e) e.textContent=tx('sub'); e=document.getElementById('m20-sector'); if(e) e.textContent=sec.emoji+' '+sec.name+' · '+sec.range; e=document.getElementById('m20-level'); if(e) e.textContent=S.level+(S.level>200?' '+tx('endless'):''); e=document.getElementById('m20-score'); if(e) e.textContent=S.score; e=document.getElementById('m20-lives'); if(e) e.textContent=S.lives; e=document.getElementById('m20-energy'); if(e) e.textContent=S.energy+'/'+S.maxEnergy; e=document.getElementById('m20-combo'); if(e) e.textContent=S.combo; e=document.getElementById('m20-mission-title'); if(e) e.textContent=m.title; e=document.getElementById('m20-goal-text'); if(e) e.textContent=m.goal; e=document.getElementById('m20-msg'); if(e) e.textContent=S.msg||arr[S.level%arr.length]; p=Math.max(0,Math.min(100,Math.round((S.got/S.need)*100))); e=document.getElementById('m20-bar'); if(e) e.style.width=p+'%'; e=document.getElementById('m20-pause'); if(e) e.textContent=S.paused?tx('play'):tx('pause'); positionOki(); }
  function positionOki(){ var e=document.getElementById('m20-oki'); if(!e) return; e.style.left=S.okiX+'%'; e.className='m20-oki'+(S.shield?' shield':'')+(S.energy>0?' fire':''); }
  function def(v){ var c='good', e=EMO[v]||String(v); if(v==='powerShield'||v==='powerDouble'||v==='powerMagnet'||v==='powerSlow'||v==='powerHeart'||v==='powerMega') c='power'; else if(v==='meteor'||v==='redMeteor'||v==='bigMeteor') c='danger'; else if(v==='blue') c='blue'; else if(v==='red') c='red'; else if(v==='yellow') c='yellow'; else if(v==='purple') c='purple'; return {v:v,e:e,c:c}; }
  function randomFrom(a){ return a[Math.floor(Math.random()*a.length)]; }
  function powerValue(){ var a=['powerShield','powerDouble','powerMagnet','powerSlow','powerHeart','powerMega']; return a[(S.level+S.score+S.got+Math.floor(Math.random()*a.length))%a.length]; }
  function spawnValue(){ var m=mission(), p=m.pool||['meteor','star','redMeteor'], chance=Math.random(), target; if(chance<.10) return powerValue(); if(m.type==='power'){ if(chance<.54) return powerValue(); if(chance<.72) return 'star'; return randomFrom(p); } if(m.type==='boss'){ if(chance<.48) return 'bigMeteor'; if(chance<.70) return 'star'; return randomFrom(p); } if(m.type==='seq'){ if(chance<.46) target=m.seq[S.seqAt]||m.seq[0]; else target=randomFrom(p); } else if(m.type==='even'||m.type==='odd'){ target=String(1+Math.floor(Math.random()*9)); } else if(m.type==='shield'){ target=(chance<.34?'bigMeteor':(chance<.68?'star':'redMeteor')); } else if(m.type==='tap'){ target=(chance<.58?'meteor':randomFrom(p)); } else if(m.type==='catch'){ target=(chance<.55?'star':randomFrom(p)); } else { target=(chance<.48?m.target:randomFrom(p)); } return target; }
  function spawn(){ var sky=document.getElementById('m20-sky'), d, b, it, dif=difficulty(), v; if(!sky||S.paused||!S.active||S.complete) return; if(S.items.length>=dif.maxItems) return; v=spawnValue(); d=def(v); b=document.createElement('button'); b.type='button'; b.className='m20-fall '+d.c; b.innerHTML=esc(d.e); it={id:++S.lastId,v:d.v,el:b,x:8+Math.random()*84,y:-8,speed:dif.speed+Math.random()*.55,hp:(d.v==='bigMeteor'?3:1)}; b.style.left=it.x+'%'; b.style.top='-62px'; b.onclick=(function(ref){ return function(ev){ if(ev){ ev.preventDefault(); ev.stopPropagation(); } tapItem(ref); }; })(it); sky.appendChild(b); S.items.push(it); }
  function isGoal(it){ var m=mission(), v=String(it.v), n=parseInt(v,10); if(m.type==='tap') return v==='meteor'; if(m.type==='catch') return v==='star'; if(m.type==='value'||m.type==='avoid'||m.type==='bonus') return v===String(m.target)||((m.type==='bonus')&&(v==='crystal'||v===String(m.target))); if(m.type==='even') return !isNaN(n)&&n%2===0; if(m.type==='odd') return !isNaN(n)&&n%2===1; if(m.type==='shield') return v==='star'; if(m.type==='power') return isPower(v); if(m.type==='seq') return v===String(m.seq[S.seqAt]); if(m.type==='boss') return v==='bigMeteor'; return false; }
