  function buildLang(base,lang){
    var i,out=[];
    for(i=0;i<base.length;i++){
      var b=base[i], e={ico:b.ico,title:b.title,sub:b.sub,theme:b.theme,bottom:b.bottom,info:b.info,msgs:b.msgs,q:b.q,zones:b.zones};
      out.push(e);
    }
    return out;
  }
