  try{ if(typeof ROOMS!=='undefined' && ROOMS){ var found=false; for(var ri=0;ri<ROOMS.length;ri++){ if(ROOMS[ri]&&ROOMS[ri].id==='okiyesor'){found=true; ROOMS[ri].name=T().room; ROOMS[ri].ico='🤖'; ROOMS[ri].type='special'; ROOMS[ri].unlock=0; ROOMS[ri].special='okiyesor'; ROOMS[ri].lesson=T().sub; } } if(!found) ROOMS.splice(1,0,{id:'okiyesor',name:T().room,ico:'🤖',type:'special',unlock:0,special:'okiyesor',bg:['#12051f','#2c1244','#4c1f58','#f8c76b'],gr:['#271033','#12051f'],lesson:T().sub}); } }catch(e){}
  var _oldName=(typeof evRoomDisplayName==='function')?evRoomDisplayName:null; if(_oldName && !_oldName.__okiyesorI18n){ evRoomDisplayName=function(room){ if(room&&room.id==='okiyesor') return T().room; return _oldName(room); }; evRoomDisplayName.__okiyesorI18n=true; }
